function getServiceUserCallCards(serviceUserId: string) {
  return demoServiceUserCallCards[serviceUserId] ?? demoServiceUserCallCards["demo-su-101"];
}

function rotaCallStatusTone(status: RotaCallCard["status"]): Tone {
  if (status === "Permanent") return "green";
  if (status === "Temporary") return "amber";
  if (status === "Unallocated") return "red";
  if (status === "Warning") return "red";
  return "blue";
}

function visitsCreatedForRange(dateRange: string, selectedCallCount: number) {
  if (!selectedCallCount) return 0;
  if (dateRange === "One day") return selectedCallCount;
  if (dateRange === "Two weeks") return selectedCallCount * 14;
  if (dateRange === "One month") return selectedCallCount * 31;
  return selectedCallCount * 14;
}

