function demoVisitToLiveShiftRow(visit: DemoVisitRecord): LiveShiftRow {
  const status: LiveShiftStatus = visit.status === "Completed" ? "Completed" : visit.status === "In progress" ? "In progress" : "No check-in";
  const fallbackId = `demo-live-${[visit.serviceUserName, visit.staffName, visit.callType, visit.expectedStart].filter(Boolean).join("-").toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
  return {
    id: visit.id || fallbackId,
    scheduledTime: `${visit.expectedStart} - ${visit.expectedEnd}`,
    serviceUser: visit.serviceUserName,
    callType: visit.callType,
    worker1: visit.staffName,
    worker2: "Not required",
    scheduledStart: visit.expectedStart,
    scheduledEnd: visit.expectedEnd,
    actualCheckIn: visit.actualCheckIn,
    actualCheckOut: visit.actualCheckOut,
    status,
    variance: visit.status === "In progress" || visit.status === "Completed" ? "0 mins" : "Awaiting check-in",
    coverage: "Manual override",
    riskLevel: "High Risk",
    highRisk: true,
    doubleUp: false,
    evidence: visit.status === "Completed" ? "Demo check-in/out, visit note and audit evidence recorded" : visit.status === "In progress" ? "Demo/manual check-in recorded" : "Allocated from Demo Setup"
  };
}

