function StaffWelcomeDashboard({
  defaultStaffRef = "UAT-ST-SARAH-001",
  incidents,
  messages,
  staffMembers,
  tasks,
  visits
}: {
  defaultStaffRef?: string;
  incidents: DemoIncidentRecord[];
  messages: DemoTaggedMessageRecord[];
  staffMembers: StaffMember[];
  tasks: DemoTaskRecord[];
  visits: DemoVisitRecord[];
}) {
  const availableStaff = useMemo(() => {
    const priorityRefs = ["UAT-ST-SARAH-001", "UAT-ST-AHMED-001", "UAT-ST-COORD-001", "UAT-ST-ADMIN-001"];
    const priorityStaff = priorityRefs
      .map((ref) => staffMembers.find((member) => member.ref === ref))
      .filter(Boolean) as StaffMember[];
    return priorityStaff.length ? priorityStaff : staffMembers.slice(0, 8);
  }, [staffMembers]);
  const [selectedStaffRef, setSelectedStaffRef] = useState(defaultStaffRef);
  useEffect(() => {
    setSelectedStaffRef(defaultStaffRef);
  }, [defaultStaffRef]);
  const currentStaff = availableStaff.find((member) => member.ref === selectedStaffRef) ?? availableStaff[0] ?? makeUatStaffRecords()[0];
  const companyId = currentStaff.companyId ?? launchPrimaryCompanyId;
  const taggedMessageCount = messages.filter((message) => message.companyId === companyId && message.taggedStaffIds.includes(currentStaff.ref) && !message.readByStaffIds.includes(currentStaff.ref) && message.status !== "Read").length;
  const outstandingTaskCount = tasks.filter((task) => task.companyId === companyId && task.assignedStaffId === currentStaff.ref && task.status !== "Completed").length;
  const todaysVisits = todayVisitCountForStaff(visits, currentStaff.ref, companyId);
  const medicationDue = medicationDueCountForStaff(visits, currentStaff.ref, companyId);
  const incidentsRequiringAction = incidents.filter((incident) => incident.companyId === companyId && incident.assignedStaffId === currentStaff.ref && incident.status === "Action required").length;

  return (
    <Card>
      <SectionTitle
        action={
          <label className="block min-w-72">
            <span className="text-xs font-bold uppercase text-slate-500">Demo logged-in staff</span>
            <select className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-semibold" onChange={(event) => setSelectedStaffRef(event.target.value)} value={currentStaff.ref}>
              {availableStaff.map((member) => (
                <option key={member.ref} value={member.ref}>{member.name} - {member.role}</option>
              ))}
            </select>
          </label>
        }
        subtitle="Personalised launch-readiness greeting with tenant-scoped message, task, rota, medication and incident counters."
        title={`Hi, ${currentStaff.name}`}
      />
      <div className="grid gap-3 md:grid-cols-5">
        <DashboardMetric label="Tagged messages" tone="blue" value={String(taggedMessageCount)} />
        <DashboardMetric label="Outstanding tasks" tone="amber" value={String(outstandingTaskCount)} />
        <DashboardMetric label="Today's visits" tone="teal" value={String(todaysVisits)} />
        <DashboardMetric label="Medication due" tone="purple" value={String(medicationDue)} />
        <DashboardMetric label="Incidents requiring action" tone={incidentsRequiringAction ? "red" : "green"} value={String(incidentsRequiringAction)} />
      </div>
      <div className="mt-4 rounded-lg bg-slate-50 p-3 text-sm font-bold text-slate-700 ring-1 ring-slate-100">
        You have: {taggedMessageCount} tagged messages, {outstandingTaskCount} outstanding tasks, {todaysVisits} visits today, {medicationDue} medication tasks due and {incidentsRequiringAction} incident{incidentsRequiringAction === 1 ? "" : "s"} requiring action.
      </div>
    </Card>
  );
}

