function iconToneClass(tone: Tone) {
  const tones: Record<Tone, string> = {
    green: "rounded-md bg-emerald-50 p-2 text-emerald-600",
    red: "rounded-md bg-rose-50 p-2 text-rose-600",
    amber: "rounded-md bg-amber-50 p-2 text-amber-600",
    blue: "rounded-md bg-blue-50 p-2 text-blue-600",
    teal: "rounded-md bg-teal-50 p-2 text-teal-600",
    slate: "rounded-md bg-slate-50 p-2 text-slate-600",
    purple: "rounded-md bg-purple-50 p-2 text-purple-600"
  };

  return tones[tone];
}

