function mobileViewFromPath(pathname: string): MobileAppView {
  if (pathname.includes("/calendar") || pathname.includes("/my-shifts")) return "My Shifts";
  if (pathname.includes("/tasks")) return "Task checklist";
  if (pathname.includes("/observations")) return "Observation entry";
  if (pathname.includes("/care-plan")) return "Care plan quick view";
  if (pathname.includes("/settings")) return "Icon settings";
  return "Visit details";
}

