function MobileShiftCalendar({ setActiveView }: { setActiveView: (view: MobileAppView) => void }) {
  const [shiftView, setShiftView] = useState("Today");
  const filteredRows = mobileShiftRows.filter(([bucket]) => {
    if (shiftView === "List" || shiftView === "Month") return true;
    if (shiftView === "Week") return ["Today", "Tomorrow", "Week"].includes(bucket);
    return bucket === shiftView;
  });

  return (
    <div className="space-y-4">
      <div className="rounded-2xl bg-[#0B1F3A] p-4 text-white">
        <div className="text-xs font-black uppercase text-teal-200">My Shifts</div>
        <div className="mt-1 text-2xl font-black">Future allocated shifts</div>
        <p className="mt-1 text-sm font-semibold text-slate-200">Staff can view and acknowledge shifts, but cannot edit the rota or see visits not allocated to them.</p>
      </div>
      <div className="grid grid-cols-5 gap-1">
        {["Today", "Tomorrow", "Week", "Month", "List"].map((view) => (
          <button className={`rounded-xl px-2 py-3 text-xs font-black ${shiftView === view ? "bg-teal-600 text-white" : "bg-white text-slate-700 ring-1 ring-slate-200"}`} key={view} onClick={() => setShiftView(view)} type="button">
            {view}
          </button>
        ))}
      </div>
      {filteredRows.map(([bucket, start, end, serviceUser, callType, postcode, status, detail, highRisk]) => (
        <div className="rounded-2xl bg-white p-4 shadow-sm ring-1 ring-slate-200" key={`${bucket}-${start}-${serviceUser}`}>
          <div className="flex items-center justify-between gap-3">
            <div>
              <div className="text-xs font-black uppercase text-slate-500">{bucket}</div>
              <div className="text-lg font-black text-slate-950">{start} - {end}</div>
              <div className="text-sm font-bold text-slate-700">{serviceUser}</div>
              <div className="text-xs font-semibold text-slate-500">{callType} | {postcode} | {detail}</div>
            </div>
            <div className="flex flex-col items-end gap-1">
              <PillBadge tone={status === "Cancelled" ? "slate" : status === "Changed" ? "amber" : status === "Confirmed" ? "green" : "blue"}>{status}</PillBadge>
              {highRisk === "Yes" ? <PillBadge tone="red">High-risk</PillBadge> : null}
            </div>
          </div>
          <div className="mt-3 grid grid-cols-3 gap-2">
            <button className="rounded-xl bg-[#0B1F3A] px-2 py-3 text-xs font-black text-white" type="button">Navigate</button>
            <button className="rounded-xl bg-teal-600 px-2 py-3 text-xs font-black text-white" onClick={() => setActiveView("Visit details")} type="button">View visit</button>
            <button className="rounded-xl bg-slate-50 px-2 py-3 text-xs font-black text-slate-800 ring-1 ring-slate-200" type="button">Acknowledge changes</button>
          </div>
        </div>
      ))}
    </div>
  );
}

