function buildAiCareReviewDraft(selectedUserName: string, suggestion: AiCareReviewSuggestion, reviewedBy: string) {
  const sourceList = suggestion.sourceRecords.map((source) => `- ${source}`).join("\n");
  const missingList = suggestion.missingInformation.map((item) => `- ${item}`).join("\n");

  return `AI-assisted draft - approval required

Client/service user: ${selectedUserName}
Draft type: ${suggestion.action}
Suggested recipient/owner: ${suggestion.recipient}
Prepared for review by: ${reviewedBy}

Reason for draft:
${suggestion.reason}

Source records used:
${sourceList}

Draft content:
Please review the recent care evidence for ${selectedUserName}. The records listed above suggest that follow-up may be required. The proposed action is: ${suggestion.recommendation}. This draft should be checked against the live care plan, risk assessment, medication records and professional judgement before approval.

Missing information to confirm before approval:
${missingList}

Governance note:
This draft must not be sent or saved as a final record until reviewed, edited if required and approved by an authorised user. The AI assistant has not updated the live client file.`;
}

