function AICareReviewReferralAssistant({ selectedUserName = "Demo Service User 101", serviceUserId = "demo-su-101" }: { selectedUserName?: string; serviceUserId?: string }) {
  const currentDemoUser = useDemoCurrentUser("Registered Manager");
  const [selectedAction, setSelectedAction] = useState<AiReferralDraftOption>("Draft OT referral/request");
  const [draftText, setDraftText] = useState("");
  const [draftStatus, setDraftStatus] = useState<"Not generated" | "AI-assisted draft - approval required" | "Approved and saved to client file" | "Rejected">("Not generated");
  const [emergencyScenario, setEmergencyScenario] = useState(false);
  const selectedSuggestion = aiCareReviewSuggestions.find((suggestion) => suggestion.action === selectedAction) ?? aiCareReviewSuggestions[0];
  const generated = draftStatus !== "Not generated";
  const approved = draftStatus === "Approved and saved to client file";

  const generateDraft = () => {
    setDraftText(buildAiCareReviewDraft(selectedUserName, selectedSuggestion, `${currentDemoUser.name} (${currentDemoUser.role})`));
    setDraftStatus("AI-assisted draft - approval required");
  };

  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle
          action={<PillBadge tone="purple">AI-assisted draft - approval required</PillBadge>}
          subtitle="Uses existing service-user evidence to suggest follow-up actions and prepare reviewable drafts. It does not update live records or send emails without human approval."
          title="AI Care Review & Referral Assistant"
        />
        <div className="grid gap-3 md:grid-cols-4">
          <RotaStat label="Client/service user" tone="blue" value={selectedUserName} />
          <RotaStat label="Suggested actions" tone="purple" value={String(aiCareReviewSuggestions.length)} />
          <RotaStat label="Draft status" tone={approved ? "green" : generated ? "amber" : "slate"} value={draftStatus} />
          <RotaStat label="Tenant boundary" tone="green" value="companyId locked" />
        </div>
        <div className="mt-4 rounded-lg bg-amber-50 p-4 text-sm font-bold leading-6 text-amber-950 ring-1 ring-amber-200">
          AI supports drafting only. Human review and approval are mandatory before sending, publishing or saving a final document. The assistant must not invent facts and must show source records and missing information.
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-3">
          <ProfileMini label="companyId" value="company-lqcs-demo" />
          <ProfileMini label="providerId" value="provider-lqcs-demo" />
          <ProfileMini label="serviceUserId" value={serviceUserId} />
        </div>
      </Card>

      <LqcsCarePlanAiGeneratorPanel selectedUserName={selectedUserName === "Demo Service User 101" ? "Mary Johnson" : selectedUserName} />

      <div className="grid gap-6 xl:grid-cols-[0.9fr_1.1fr]">
        <Card>
          <SectionTitle subtitle="Evidence is already recorded in the client file. Production AI must only use records for the authorised company/provider." title="Source records used" />
          <MedicationSimpleTable headings={["Source", "Record ID", "Relevant detail"]} rows={aiCareReviewSourceSnapshot} title="Minimum necessary source snapshot" />
          <label className="mt-4 flex items-start gap-3 rounded-lg bg-rose-50 p-4 text-sm font-bold text-rose-900 ring-1 ring-rose-200">
            <input checked={emergencyScenario} className="mt-1" onChange={(event) => setEmergencyScenario(event.target.checked)} type="checkbox" />
            Show emergency red-flag safeguard
          </label>
          {emergencyScenario ? (
            <div className="mt-4 rounded-lg bg-rose-100 p-4 text-base font-black leading-7 text-rose-950 ring-1 ring-rose-300">
              This may require immediate emergency action. Do not rely only on email. Follow emergency procedure and call 999 if required.
            </div>
          ) : null}
        </Card>

        <Card>
          <SectionTitle subtitle="The manager or care coordinator chooses what to generate. No action is taken automatically." title="Suggested follow-up actions" />
          <div className="grid gap-3">
            {aiCareReviewSuggestions.map((suggestion) => (
              <button
                className={`rounded-lg border p-4 text-left transition ${selectedAction === suggestion.action ? "border-teal-400 bg-teal-50" : "border-slate-200 bg-white hover:border-teal-200"}`}
                key={suggestion.action}
                onClick={() => { setSelectedAction(suggestion.action); setDraftStatus("Not generated"); setDraftText(""); }}
                type="button"
              >
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <div className="text-base font-black text-slate-950">{suggestion.recommendation}</div>
                  <PillBadge tone={suggestion.tone}>{suggestion.action}</PillBadge>
                </div>
                <p className="mt-2 text-sm leading-6 text-slate-600">{suggestion.reason}</p>
                <div className="mt-3 flex flex-wrap gap-2">
                  {suggestion.triggerExamples.map((trigger) => <PillBadge key={trigger} tone="slate">{trigger}</PillBadge>)}
                </div>
              </button>
            ))}
          </div>
        </Card>
      </div>

      <Card>
        <SectionTitle subtitle="Select a draft type, review missing information, then generate an editable draft for human approval." title="Draft generator" />
        <div className="grid gap-4 lg:grid-cols-[320px_1fr]">
          <div className="space-y-4">
            <FilterSelect label="Draft option" onChange={(value) => { setSelectedAction(value as AiReferralDraftOption); setDraftStatus("Not generated"); setDraftText(""); }} options={aiCareReviewDraftOptions} value={selectedAction} />
            <ProfileMini label="Suggested recipient/owner" value={selectedSuggestion.recipient} />
            <ProfileMini label="Reviewer defaults to logged-in user" value={`${currentDemoUser.name} (${currentDemoUser.role})`} />
            <ProfileMini label="Status" value={draftStatus} />
            <button className="w-full rounded-md bg-[#0B1F3A] px-4 py-3 text-sm font-black text-white" onClick={generateDraft} type="button">Generate AI-assisted draft</button>
            <button className="w-full rounded-md bg-emerald-600 px-4 py-3 text-sm font-black text-white disabled:cursor-not-allowed disabled:bg-slate-300" disabled={!generated || approved} onClick={() => setDraftStatus("Approved and saved to client file")} type="button">Approve and save to client file</button>
            <button className="w-full rounded-md bg-rose-50 px-4 py-3 text-sm font-black text-rose-800 ring-1 ring-rose-100 disabled:cursor-not-allowed disabled:text-slate-400" disabled={!generated || approved} onClick={() => setDraftStatus("Rejected")} type="button">Reject draft</button>
          </div>
          <div className="space-y-4">
            <div className="rounded-lg bg-blue-50 p-4 ring-1 ring-blue-100">
              <div className="text-sm font-black text-blue-950">Missing information before approval</div>
              <ul className="mt-2 list-disc space-y-1 pl-5 text-sm font-semibold leading-6 text-blue-900">
                {selectedSuggestion.missingInformation.map((item) => <li key={item}>{item}</li>)}
              </ul>
            </div>
            <label className="block">
              <span className="text-xs font-bold uppercase text-slate-500">Editable draft</span>
              <textarea
                className="mt-2 min-h-96 w-full rounded-lg border border-slate-200 px-4 py-3 font-mono text-sm leading-6"
                onChange={(event) => setDraftText(event.target.value)}
                placeholder="Generate a draft first. It will be clearly marked AI-assisted draft - approval required."
                value={draftText}
              />
            </label>
            {approved ? (
              <div className="rounded-lg bg-emerald-50 p-4 text-sm font-black text-emerald-900 ring-1 ring-emerald-200">
                Approved demo draft saved to the client file. In production this creates a versioned document/email/referral record and no email is sent unless a separate authorised send action is approved.
              </div>
            ) : null}
          </div>
        </div>
      </Card>

      <div className="grid gap-6 xl:grid-cols-2">
        <Card>
          <SectionTitle subtitle="Controls designed for UK GDPR, professional accountability and care governance." title="Safety and governance controls" />
          <MedicationSimpleTable headings={["Control", "How it works", "Status"]} rows={aiCareReviewGovernanceRows} title="AI governance register" />
        </Card>
        <Card>
          <SectionTitle subtitle="All versions are retained. Corrections and approvals are separate audit events." title="Version and approval history" />
          <MedicationSimpleTable
            headings={["Version", "Status", "Reviewer", "Date/time", "Outcome"]}
            rows={[
              ["v0.1", "AI-assisted draft", `${currentDemoUser.name} (${currentDemoUser.role})`, generated ? "04 Jun 2026 21:31" : "Pending generation", generated ? "Draft available for review" : "Not generated"],
              ["v0.2", "Human edits", `${currentDemoUser.name} (${currentDemoUser.role})`, generated ? "Pending" : "Pending generation", "Edits retained separately"],
              ["v1.0", approved ? "Approved final" : "Approval required", "Authorised manager/care coordinator", approved ? "04 Jun 2026 21:36" : "Pending", approved ? "Saved to client file" : "Not saved or sent"]
            ]}
            title="Draft version history"
          />
        </Card>
      </div>

      <MedicationSimpleTable headings={["Date/time", "User", "Role", "Action", "Source/final record", "Reason/comment", "Outcome"]} rows={aiCareReviewAuditRows} title="AI care review audit trail" />
    </div>
  );
}

