export function QualityIntelligenceCqcEvidenceHub() {
  const currentDemoUser = useDemoCurrentUser("Registered Manager");
  const [activeSection, setActiveSection] = useState<QualityHubSection>("Executive KPI Dashboard");
  const [reportDrafted, setReportDrafted] = useState(false);
  const [reportApproved, setReportApproved] = useState(false);
  const [packGenerated, setPackGenerated] = useState(false);

  const reportStatus = reportApproved ? "Approved quality report" : reportDrafted ? "Draft - approval required" : "Not generated";
  const reportDraftText = `AI-assisted draft - approval required

Monthly Quality Report: May 2026
Provider: London Quality Care Services demo provider
Prepared for review by: ${currentDemoUser.name} (${currentDemoUser.role})

Executive summary:
CareVerity has identified stable training compliance, a positive compliments trend and open improvement actions for late calls, transfer safety and complaint communication. This draft uses only the source records shown in the Quality Intelligence & CQC Evidence Hub and must be reviewed before finalisation.

KPI summary:
- Total incidents: 11
- Falls: 5
- Medication errors: 2
- Missed calls: 1
- Late calls: 7
- Compliments received: 14
- Staff training compliance: 92%

Lessons learned:
- Review transfer instructions after mobility change.
- Confirm rota changes in writing before they take effect.
- Refresh MAR reason-code recording guidance.

Good news and outcomes:
- Family compliment about kindness and dignity.
- Improved confidence after mobility review.

Missing information before approval:
- Confirm final complaint closure evidence.
- Confirm manager-approved lesson learned wording.
- Confirm whether any duty of candour action applies.
- Confirm evidence pack date range and CQC theme filters.`;

  const sectionIntro: Record<QualityHubSection, string> = {
    "Executive KPI Dashboard": "Operational, care, quality and governance indicators for manager review.",
    "Incident Trend Analysis": "Incident, accident, near-miss, safeguarding, medication and late/missed-call trends.",
    "Complaints and Compliments Analysis": "Complaint learning and positive feedback detection, both kept as draft until approved.",
    "Lessons Learned Tracker": "Root cause, learning, action owner, target date, approval and evidence tracking.",
    "Good News / Positive Outcomes Stories": "Positive outcomes and compliments that can be reviewed for CQC evidence.",
    "Staff Recognition / Good Practice Evidence": "Approved staff recognition, positive culture and workforce wellbeing evidence linked from HRIS.",
    "CQC Evidence Mapping": "Evidence mapped to Safe, Effective, Caring, Responsive and Well-led.",
    "Audit and Governance Tracker": "Audits, supervision, spot checks, safeguarding reviews and governance evidence.",
    "Care Plan and Risk Review Triggers": "Triggers for care plan and risk assessment review after incidents, concerns or referrals.",
    "Monthly Quality Report Generator": "AI-assisted monthly quality report draft with manager approval section.",
    "Inspection Evidence Pack": "Generate a draft pack by date range and CQC theme for inspection preparation."
  };

  const renderSection = () => {
    if (activeSection === "Executive KPI Dashboard") {
      return (
        <div className="space-y-6">
          <div className="grid gap-3 md:grid-cols-3 xl:grid-cols-6">
            {qualityHubKpis.map(([label, value, detail, tone]) => (
              <div className="space-y-2" key={label}>
                <RotaStat label={label} tone={tone} value={value} />
                <div className="rounded-md bg-white px-3 py-2 text-xs font-semibold leading-5 text-slate-600 ring-1 ring-slate-100">{detail}</div>
              </div>
            ))}
          </div>
          <Card>
            <SectionTitle subtitle="Source records used by the hub. Production reports must filter by companyId/providerId and use minimum necessary personal data." title="Quality intelligence data sources" />
            <MedicationSimpleTable headings={["Data source", "Demo source reference", "Analysis summary"]} rows={qualityHubSourceRows} title="Source record register" />
          </Card>
        </div>
      );
    }

    if (activeSection === "Incident Trend Analysis") {
      return <MedicationSimpleTable headings={["Theme", "This month", "Trend", "Risk level", "Suggested action", "CQC theme"]} rows={qualityIncidentTrendRows} title="Incident, near miss and safeguarding trend analysis" />;
    }

    if (activeSection === "Complaints and Compliments Analysis") {
      return (
        <div className="space-y-6">
          <MedicationSimpleTable headings={["Type", "Reference", "Category/theme", "Severity", "Suggested action", "Duty/apology consideration", "Care/risk review", "CQC mapping", "Status"]} rows={qualityComplaintRows} title="Complaints and compliments AI-assisted analysis" />
          <Card>
            <SectionTitle subtitle="Compliments and positive feedback remain draft evidence until a manager approves the wording and staff/client links." title="Compliments function" />
            <div className="grid gap-3 md:grid-cols-3">
              {["Add to compliments register", "Link to relevant staff", "Link to service-user outcome", "Generate good news story", "Map evidence to CQC themes", "Include in monthly quality report"].map((item) => (
                <div className="rounded-lg bg-emerald-50 p-4 text-sm font-black text-emerald-900 ring-1 ring-emerald-100" key={item}>{item}</div>
              ))}
            </div>
          </Card>
        </div>
      );
    }

    if (activeSection === "Lessons Learned Tracker") {
      return <MedicationSimpleTable headings={["Source type", "Source ref", "Date", "Service user", "Issue/event", "Immediate action", "Root cause", "AI suggested lesson", "Manager-approved lesson", "Action", "Responsible person", "Target date", "Completion date", "Status", "Evidence", "Care plan update", "Risk update", "Approved by", "Approval date/time"]} rows={qualityLessonsRows} title="Lessons learned tracker" />;
    }

    if (activeSection === "Good News / Positive Outcomes Stories") {
      return <MedicationSimpleTable headings={["Source ref", "Positive outcome / story", "Linked staff", "Linked service user/outcome", "CQC theme", "Suggested use", "Approval status"]} rows={qualityGoodNewsRows} title="Good news and positive outcomes register" />;
    }

    if (activeSection === "Staff Recognition / Good Practice Evidence") {
      return (
        <div className="space-y-6">
          <Card>
            <SectionTitle
              action={<a className="rounded-md bg-teal-600 px-4 py-2 text-sm font-black text-white" href="/hr/staff-recognition">Open Staff Recognition</a>}
              subtitle="Positive, approved good practice evidence from HRIS. No negative ranking is shown publicly."
              title="Good Practice Evidence from Staff Recognition"
            />
            <div className="rounded-lg bg-emerald-50 p-4 text-sm font-bold leading-6 text-emerald-950 ring-1 ring-emerald-100">
              Staff recognition evidence is decision-support only and must be approved by authorised managers before publication, emailing or inclusion in final CQC evidence packs.
            </div>
          </Card>
          <MedicationSimpleTable headings={["Nomination", "Staff", "Role", "Category", "Month", "Status", "Consent", "Nominated by", "Evidence summary"]} rows={staffRecognitionNominations.map((nomination) => [nomination.nominationId, nomination.staffName, nomination.staffRole, nomination.awardCategory, `${nomination.nominationMonth} ${nomination.nominationYear}`, nomination.status, nomination.consentStatus, nomination.nominatedByName, nomination.evidenceSummary])} title="Recognition Nominations Linked to Quality Hub" />
          <MedicationSimpleTable headings={["CQC theme", "Recognition evidence mapping"]} rows={staffRecognitionCqcMappingRows} title="Recognition CQC Mapping" />
        </div>
      );
    }

    if (activeSection === "CQC Evidence Mapping") {
      return <MedicationSimpleTable headings={["Evidence item", "CQC theme", "Source reference", "Evidence source", "Approval status"]} rows={qualityCqcMappingRows} title="CQC Safe / Effective / Caring / Responsive / Well-led mapping" />;
    }

    if (activeSection === "Audit and Governance Tracker") {
      return <MedicationSimpleTable headings={["Governance area", "Owner", "Frequency/due date", "Status", "CQC theme", "Notes"]} rows={qualityAuditGovernanceRows} title="Audit and governance tracker" />;
    }

    if (activeSection === "Care Plan and Risk Review Triggers") {
      return <MedicationSimpleTable headings={["Trigger source", "Reference", "Care plan trigger", "Risk assessment trigger", "Owner", "Status"]} rows={qualityReviewTriggerRows} title="Care plan and risk assessment review triggers" />;
    }

    if (activeSection === "Monthly Quality Report Generator") {
      return (
        <div className="space-y-6">
          <Card>
            <SectionTitle subtitle="Generate a reviewable draft. The report is not final until approved by an authorised manager." title="Monthly Quality Report Generator" />
            <div className="grid gap-4 lg:grid-cols-[320px_1fr]">
              <div className="space-y-4">
                <FilterSelect label="Report month" onChange={() => undefined} options={["May 2026", "April 2026", "March 2026"]} value="May 2026" />
                <FilterSelect label="Report type" onChange={() => undefined} options={["Monthly Quality Report", "Board summary", "CQC evidence summary", "Local authority quality update"]} value="Monthly Quality Report" />
                <FilterSelect label="Personal data level" onChange={() => undefined} options={["Minimum necessary", "Anonymised summary", "Named records for internal manager only"]} value="Minimum necessary" />
                <ProfileMini label="Reviewer" value={`${currentDemoUser.name} (${currentDemoUser.role})`} />
                <ProfileMini label="Status" value={reportStatus} />
                <button className="w-full rounded-md bg-[#0B1F3A] px-4 py-3 text-sm font-black text-white" onClick={() => { setReportDrafted(true); setReportApproved(false); }} type="button">Generate Draft Monthly Quality Report</button>
                <button className="w-full rounded-md bg-emerald-600 px-4 py-3 text-sm font-black text-white disabled:cursor-not-allowed disabled:bg-slate-300" disabled={!reportDrafted || reportApproved} onClick={() => setReportApproved(true)} type="button">Approve Quality Report</button>
                <button className="w-full rounded-md bg-rose-50 px-4 py-3 text-sm font-black text-rose-800 ring-1 ring-rose-100" onClick={() => { setReportDrafted(false); setReportApproved(false); }} type="button">Reject / reset draft</button>
              </div>
              <label className="block">
                <span className="text-xs font-bold uppercase text-slate-500">Draft monthly quality report</span>
                <textarea className="mt-2 min-h-96 w-full rounded-lg border border-slate-200 px-4 py-3 font-mono text-sm leading-6" readOnly value={reportDrafted ? reportDraftText : "Generate a draft report first. AI-assisted report content will appear here and must be reviewed before approval."} />
              </label>
            </div>
          </Card>
          <MedicationSimpleTable headings={["Date/time", "User", "Role", "Action", "Evidence", "Outcome"]} rows={qualityReportAuditRows} title="Quality report audit trail" />
        </div>
      );
    }

    return (
      <div className="space-y-6">
        <Card>
          <SectionTitle subtitle="Build a draft inspection pack by date range and CQC theme. No evidence item is final unless approved." title="Inspection Evidence Pack" />
          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
            <label className="block">
              <span className="text-xs font-bold uppercase text-slate-500">Date from</span>
              <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm" defaultValue="2026-05-01" type="date" />
            </label>
            <label className="block">
              <span className="text-xs font-bold uppercase text-slate-500">Date to</span>
              <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm" defaultValue="2026-05-31" type="date" />
            </label>
            <FilterSelect label="CQC theme" onChange={() => undefined} options={["All themes", "Safe", "Effective", "Caring", "Responsive", "Well-led"]} value="All themes" />
            <FilterSelect label="Approval status" onChange={() => undefined} options={["Approved only", "Draft and approved", "Needs review"]} value="Approved only" />
          </div>
          <div className="mt-4 flex flex-wrap gap-2">
            <button className="rounded-md bg-[#0B1F3A] px-4 py-2 text-sm font-black text-white" onClick={() => setPackGenerated(true)} type="button">Generate Draft Evidence Pack</button>
            <button className="rounded-md bg-slate-100 px-4 py-2 text-sm font-bold text-slate-700" type="button">Export pack placeholder</button>
          </div>
          {packGenerated ? <div className="mt-4 rounded-lg bg-teal-50 p-4 text-sm font-black text-teal-900 ring-1 ring-teal-100">Draft evidence pack generated for manager review. Approved reports, audits, trackers, complaints/compliments, lessons learned, care/risk review evidence, professional referrals, outcomes, training and supervision evidence are listed below.</div> : null}
        </Card>
        <MedicationSimpleTable headings={["Evidence pack item", "Included evidence", "CQC theme", "Approval rule"]} rows={[
          ["Approved reports", "Monthly quality report, KPI summary", "All themes", "Approved only"],
          ["Audits and action trackers", "Medication audit, care plan audit, spot checks", "Safe / Well-led", "Approved or manager reviewed"],
          ["Complaints and compliments", "Complaint learning and compliments register", "Responsive / Caring / Well-led", "Manager approved"],
          ["Lessons learned", "Open and closed learning actions", "Safe / Well-led", "Show status and owner"],
          ["Care plan/risk review evidence", "Review triggers and completed updates", "Safe / Effective / Responsive", "Approved versions only"],
          ["Professional referrals", "OT, GP, district nurse and social worker communications", "Safe / Effective / Responsive", "Minimum necessary data"],
          ["Service-user outcomes", "Positive outcome stories", "Caring / Effective / Responsive", "Approved wording only"],
          ["Training and supervision evidence", "Training matrix, certificates, supervision compliance", "Safe / Effective / Well-led", "Current records only"]
        ]} title="Inspection evidence pack contents" />
      </div>
    );
  };

  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle
          action={<PillBadge tone="purple">AI-assisted draft - human approval required</PillBadge>}
          subtitle="Analyses operational, care, quality and governance data already held in CareVerity to support KPI dashboards, evidence packs, lessons learned, quality reports and improvement tracking."
          title="Quality Intelligence & CQC Evidence Hub"
        />
        <div className="grid gap-3 md:grid-cols-4">
          <RotaStat label="Current quality status" tone="amber" value="Review active" />
          <RotaStat label="CQC themes mapped" tone="green" value="5" />
          <RotaStat label="Draft evidence items" tone="purple" value="18" />
          <RotaStat label="Approved evidence items" tone="green" value="42" />
        </div>
        <div className="mt-4 rounded-lg bg-amber-50 p-4 text-sm font-bold leading-6 text-amber-950 ring-1 ring-amber-200">
          AI suggestions are draft only. Managers must review, edit, reject or approve before reports, lessons learned, good-news stories or evidence summaries are finalised. The system must not invent facts and must show source records and missing information.
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-3">
          <ProfileMini label="companyId" value="company-lqcs-demo" />
          <ProfileMini label="providerId" value="provider-lqcs-demo" />
          <ProfileMini label="Personal data rule" value="Minimum necessary" />
        </div>
      </Card>

      <Card>
        <SectionTitle subtitle={sectionIntro[activeSection]} title="Quality hub sections" />
        <div className="flex flex-wrap gap-2">
          {qualityHubSections.map((section) => (
            <button className={`rounded-md px-3 py-2 text-xs font-bold ${activeSection === section ? "bg-[#0B1F3A] text-white" : "bg-slate-50 text-slate-700 ring-1 ring-slate-200"}`} key={section} onClick={() => setActiveSection(section)} type="button">
              {section}
            </button>
          ))}
        </div>
      </Card>

      {renderSection()}

      <Card>
        <SectionTitle subtitle="These controls apply to dashboards, report generation, lessons learned, good-news stories and inspection packs." title="AI safeguards and governance" />
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          {["AI suggestions marked as draft", "Human approval required", "Source records shown", "No invented facts or outcomes", "Missing information highlighted", "Edit/reject/approve controls", "All versions retained", "Audit trail permanent", "companyId tenant separation", "Minimum necessary personal data", "Authorised users only", "No final evidence without approval"].map((control) => (
            <div className="rounded-lg bg-slate-50 p-4 text-sm font-black text-slate-800 ring-1 ring-slate-100" key={control}>{control}</div>
          ))}
        </div>
      </Card>
    </div>
  );
}

