function staffField(profile: StaffFileProfile, label: string) {
  const allFields = [...profile.coreDetails, ...profile.contactDetails, ...profile.personalEquality, ...profile.nextOfKin, ...profile.dbsSafeguarding, ...profile.references];
  return allFields.find(([fieldLabel]) => fieldLabel === label)?.[1] ?? "Demo placeholder";
}

function buildSelectedStaffProfile(selectedRef: string, memberOverride?: StaffMember): StaffFileProfile {
  const exactProfile = staffFileProfiles.find((profile) => profile.ref === selectedRef);
  if (exactProfile) return exactProfile;

  const member: StaffMember = memberOverride ?? (staff.find((staffMember) => staffMember.ref === selectedRef) as StaffMember | undefined) ?? (staff[0] as StaffMember);
  const base = staffFileProfiles[0];
  return {
    ...base,
    ref: member.ref,
    displayName: member.name,
    initials: member.photo,
    profileScore: Number(member.training.replace("%", "")) || base.profileScore,
    coreDetails: base.coreDetails.map(([label, value]) => {
      if (label === "First name") return [label, "Demo"];
      if (label === "Last name") return [label, member.name.replace(/^Demo\s+/, "")];
      if (label === "Preferred name") return [label, member.name.split(" ").slice(-1)[0] ?? "Demo"];
      if (label === "Job title") return [label, member.jobTitle ?? member.role];
      if (label === "Employee reference number") return [label, member.ref];
      if (label === "Employee role") return [label, member.role];
      if (label === "Staff status") return [label, member.status];
      if (label === "Start date") return [label, member.startDate ?? value];
      if (label === "Branch/locality") return [label, member.workArea ?? value];
      return [label, value];
    }),
    contactDetails: base.contactDetails.map(([label, value]) => {
      if (label === "Email address") return [label, member.email ?? value];
      if (label === "Mobile number") return [label, member.mobile ?? value];
      if (label === "Current home address") return [label, member.address ?? value];
      return [label, value];
    }),
    dbsSafeguarding: base.dbsSafeguarding.map(([label, value]) => (label === "DBS outcome/status" ? [label, member.dbs] : [label, value])),
    trainingCompetency: {
      ...base.trainingCompetency,
      mandatory: base.trainingCompetency.mandatory.map((row, index) => (index === 0 ? [row[0], `Profile compliance ${member.training}`, member.dbs === "Amber" ? "amber" : "green"] : row))
    },
    auditTrail: [`13 May 2026 10:05 | Demo HR user opened ${member.name} staff profile`, ...base.auditTrail]
  };
}

