function companySystemJournalPeople(selectedStaff?: StaffMember): StaffJournalTaggedPerson[] {
  const baselinePeople: StaffJournalTaggedPerson[] = [
    ...staff.map((member) => ({ name: member.name, role: member.role })),
    ...additionalCompanyJournalPeople,
    { name: "Demo Registered Manager", role: "Registered Manager" },
    { name: "Demo HR Administrator A", role: "HR Administrator" },
    { name: "Demo Care Coordinator A", role: "Care Coordinator" }
  ];
  if (selectedStaff) baselinePeople.push({ name: selectedStaff.name, role: selectedStaff.role || "Staff member" });
  const seen = new Set<string>();
  return baselinePeople.filter((person) => {
    const key = `${person.name}-${person.role}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function staffJournalTagPeople(selectedStaff: StaffMember): StaffJournalTaggedPerson[] {
  return companySystemJournalPeople(selectedStaff);
}

function defaultStaffJournalTaggedPeople(selectedStaff: StaffMember) {
  const people = staffJournalTagPeople(selectedStaff);
  return people.filter((person) => ["Registered Manager", "HR Administrator", "Care Coordinator"].includes(person.role) || person.name === selectedStaff.name).slice(0, 6);
}

