function staffJournalPermissionForRole(role: string) {
  if (role === "System Owner" || role === "Registered Manager") return "Full access to staff journal entries, restricted notes, actions, export and audit log.";
  if (role === "Deputy Manager") return "Full access unless an entry is marked restricted.";
  if (/HR|Recruitment/i.test(role)) return "Full HR and recruitment access, including staff journal creation and addendums where authorised.";
  if (/Care Coordinator|Rota Coordinator|Field Care Supervisor/i.test(role)) return "Can add operational, rota, availability and care coordination notes where authorised.";
  if (/Training|Trainer/i.test(role)) return "Training-related journal notes only.";
  if (role === "Finance / Payroll") return "Payroll-related journal notes only.";
  if (/Care Worker|Mobile User|Outreach/i.test(role)) return "Can create/view staff-visible information-sharing notes and communications addressed to them.";
  if (/Admin|Administrator|Manager|Officer|Lead/i.test(role)) return "Can create/view journal communications where their company role is authorised.";
  return "Read-only access where authorised; no add, edit, delete, addendum or export controls.";
}

function canCreateStaffJournalEntry(role: string) {
  return !/read-only|auditor|inspector|family portal|external|NHS|local authority/i.test(role);
}

function canViewStaffJournalEntry(role: string, entry: StaffJournalEntry, staffName: string) {
  if (role === "System Owner" || role === "Registered Manager" || /HR|Admin|Administrator|Manager|Officer|Lead/i.test(role)) return true;
  if (role === "Deputy Manager") return entry.restrictedNote !== "Yes";
  if (/Care Worker|Mobile User|Outreach/i.test(role)) return entry.visibleToStaff === "Yes" && entry.linkedStaffMember === staffName;
  if (/Training|Trainer/i.test(role)) return /training|certificate|course|academy/i.test(entry.journalType + entry.subject);
  if (role === "Finance / Payroll") return /payroll|finance|pay/i.test(entry.journalType + entry.subject);
  if (/Care Coordinator|Rota Coordinator|Field Care Supervisor/i.test(role)) return /rota|availability|phone|whatsapp|sms|meeting|care/i.test(entry.journalType + entry.subject);
  return entry.restrictedNote !== "Yes";
}

function staffJournalTimestamp() {
  return new Date().toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" });
}

function staffJournalAuditRowsFor(entries: StaffJournalEntry[]) {
  return entries.flatMap((entry) => [
    [entry.createdAt, entry.writtenBy, entry.writtenByRole, entry.linkedStaffMember, entry.id, "journal created", entry.subject, entry.auditRef],
    ...entry.taggedPeople.map((person) => [entry.createdAt, entry.writtenBy, entry.writtenByRole, entry.linkedStaffMember, entry.id, "person tagged", `${person.name} (${person.role})`, entry.auditRef]),
    ...(entry.emailNotification === "Yes" ? entry.taggedPeople.map((person) => [entry.createdAt, entry.writtenBy, entry.writtenByRole, entry.linkedStaffMember, entry.id, "email notification created", `Demo email notification record for ${person.name}`, entry.auditRef]) : [])
  ]);
}

function staffJournalExportSummary(staffMember: StaffMember) {
  const entries = demoStaffJournalEntriesFor(staffMember);
  const taggedActions = entries.flatMap((entry) => entry.taggedPeople.map((person) => ({
    journalEntryId: entry.id,
    subject: entry.subject,
    taggedPerson: person.name,
    taggedRole: person.role,
    priority: entry.priority,
    status: entry.status,
    actionDueDate: entry.actionDueDate
  })));
  const emailNotificationLog = entries
    .filter((entry) => entry.emailNotification === "Yes")
    .flatMap((entry) => entry.taggedPeople.map((person) => ({
      journalEntryId: entry.id,
      recipient: person.name,
      subject: `CareVerity HR Notification: ${entry.subject}`,
      messageSummary: entry.restrictedNote === "Yes" || entry.internalOnly === "Yes" ? "Restricted summary only. Confidential full notes are not exposed in email." : entry.messageSummary,
      sentBy: entry.writtenBy,
      dateTime: entry.createdAt,
      delivery: "Demo email notification record only"
    })));
  return {
    journalEntries: entries,
    taggedActions,
    emailNotificationLog,
    auditTrail: staffJournalAuditRowsFor(entries)
  };
}

