function staffSlug(member: StaffMember) {
  return member.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function staffRefFromPathSegment(pathSegment: string, staffList: StaffMember[] = staff) {
  const normalised = pathSegment.split("/")[0].toLowerCase();
  return staffList.find((member) => staffSlug(member) === normalised || member.ref.toLowerCase() === normalised)?.ref ?? staffList[0]?.ref ?? staff[0].ref;
}

function staffAvailabilityStatus(member: StaffMember) {
  if (member.availability) return member.availability.includes("09:00") && /coordinator|administrator|manager|finance|payroll|quality|hr/i.test(member.role) ? "Access restricted" : "Available";
  if (member.name === "Demo Care Worker A") return "Available";
  if (member.name === "Demo Outreach Worker B") return "Available";
  if (member.name.includes("Coordinator")) return "Access restricted";
  if (member.status !== "Active") return "Not available";
  return "No availability set";
}

