function makeEditableAudit(recordType: string, recordName: string, fieldChanged: string, oldValue: string, newValue: string, reason: string): EditableAuditEntry {
  return {
    dateTime: new Date().toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" }),
    user: "Demo Registered Manager",
    role: "Registered Manager",
    recordType,
    recordName,
    fieldChanged,
    oldValue,
    newValue,
    reason: reason || "Front-facing profile edit saved."
  };
}

function auditRowsFromEntries(entries: EditableAuditEntry[]) {
  return entries.map((entry) => [entry.dateTime, entry.user, entry.role, entry.recordType, entry.recordName, entry.fieldChanged, entry.oldValue, entry.newValue, entry.reason]);
}

function EditableSelectField({ disabled, label, onChange, options, value }: { disabled: boolean; label: string; onChange: (value: string) => void; options: readonly string[]; value: string }) {
  const sensitive = sensitiveFieldLabels.some((item) => label.toLowerCase().includes(item.toLowerCase()));
  return (
    <label className="block">
      <span className="text-xs font-bold uppercase text-slate-500">{label}</span>
      <select className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-semibold disabled:bg-slate-50 disabled:text-slate-500" disabled={disabled} onChange={(event) => onChange(event.target.value)} value={value}>
        <option disabled value="">Select option</option>
        {options.map((option) => <option key={option}>{option}</option>)}
      </select>
      {sensitive ? <span className="mt-1 block text-[11px] font-bold uppercase text-rose-700">Sensitive/special category - role controlled and audit logged</span> : null}
    </label>
  );
}

function EditableTextField({ disabled, label, onChange, type = "text", value }: { disabled: boolean; label: string; onChange: (value: string) => void; type?: string; value: string }) {
  const sensitive = sensitiveFieldLabels.some((item) => label.toLowerCase().includes(item.toLowerCase()));
  return (
    <label className="block">
      <span className="text-xs font-bold uppercase text-slate-500">{label}</span>
      <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm font-semibold disabled:bg-slate-50 disabled:text-slate-500" disabled={disabled} onChange={(event) => onChange(event.target.value)} type={type} value={value} />
      {sensitive ? <span className="mt-1 block text-[11px] font-bold uppercase text-rose-700">Sensitive/special category - role controlled and audit logged</span> : null}
    </label>
  );
}

function EditableTextareaField({ disabled, label, onChange, value }: { disabled: boolean; label: string; onChange: (value: string) => void; value: string }) {
  return (
    <label className="block md:col-span-2">
      <span className="text-xs font-bold uppercase text-slate-500">{label}</span>
      <textarea className="mt-2 min-h-24 w-full rounded-md border border-slate-200 px-3 py-2 text-sm font-semibold disabled:bg-slate-50 disabled:text-slate-500" disabled={disabled} onChange={(event) => onChange(event.target.value)} value={value} />
    </label>
  );
}

function EditableRecordSection({
  children,
  isEditing,
  lastUpdatedAt,
  lastUpdatedBy,
  onCancel,
  onEdit,
  onSave,
  recordName,
  sectionName,
  subtitle,
  title
}: {
  children: ReactNode;
  isEditing: boolean;
  lastUpdatedAt: string;
  lastUpdatedBy: string;
  onCancel: () => void;
  onEdit: () => void;
  onSave: () => void;
  recordName: string;
  sectionName: string;
  subtitle?: string;
  title: string;
}) {
  return (
    <Card>
      <SectionTitle
        action={
          <div className="flex flex-wrap gap-2">
            <button className="rounded-md bg-teal-600 px-4 py-2 text-sm font-black text-white disabled:bg-slate-300" disabled={isEditing} onClick={onEdit} type="button">Edit</button>
            <button className="rounded-md bg-[#0B1F3A] px-4 py-2 text-sm font-black text-white disabled:bg-slate-300" disabled={!isEditing} onClick={onSave} type="button">Save changes</button>
            <button className="rounded-md bg-slate-100 px-4 py-2 text-sm font-black text-slate-700 ring-1 ring-slate-200 disabled:text-slate-400" disabled={!isEditing} onClick={onCancel} type="button">Cancel</button>
          </div>
        }
        subtitle={subtitle}
        title={title}
      />
      <div className="mb-4 grid gap-3 md:grid-cols-3">
        <ProfileMini label="Section" value={sectionName} />
        <ProfileMini label="Record" value={recordName} />
        <ProfileMini label="Edit mode" value={isEditing ? "Editing" : "Read only"} />
        <ProfileMini label="Last updated by" value={lastUpdatedBy} />
        <ProfileMini label="Last updated date/time" value={lastUpdatedAt} />
        <ProfileMini label="Audit log record" value="Created when saved" />
      </div>
      {children}
    </Card>
  );
}

