function makeLaunchReadinessFixtures() {
  const companies = makeLaunchCompanyRecords();
  const staffRecords = companies.flatMap((company) => makeLaunchStaffForCompany(company.companyId));
  const serviceUsers = companies.flatMap((company) => makeLaunchServiceUsersForCompany(company.companyId));
  const visits = companies.flatMap((company) => makeLaunchVisitsForCompany(company.companyId));
  const medications = companies.flatMap((company) => makeLaunchMarRecordsForCompany(company.companyId));
  const messages = companies.flatMap((company) => makeLaunchMessagesForCompany(company.companyId));
  const tasks = companies.flatMap((company) => makeLaunchTasksForCompany(company.companyId));
  const incidents = companies.flatMap((company) => makeLaunchIncidentsForCompany(company.companyId));
  return { companies, staffRecords, serviceUsers, visits, medications, messages, tasks, incidents };
}

function todayVisitCountForStaff(visits: DemoVisitRecord[], staffRef: string, companyId = launchPrimaryCompanyId) {
  const today = demoDateStampFromOffset(0);
  return visits.filter((visit) => visit.companyId === companyId && visit.staffReference === staffRef && visit.date === today).length;
}

function medicationDueCountForStaff(visits: DemoVisitRecord[], staffRef: string, companyId = launchPrimaryCompanyId) {
  const medicationVisits = todayVisitCountForStaff(visits.filter((visit) => /medication|paracetamol|prompt/i.test(visit.medicationPrompt)), staffRef, companyId);
  return Math.min(2, medicationVisits * 2);
}

function launchTenantSeparationSummary(fixtures: ReturnType<typeof makeLaunchReadinessFixtures>) {
  const companyIds = new Set(fixtures.companies.map((company) => company.companyId));
  const allRecordsHaveCompanyId = [
    fixtures.staffRecords,
    fixtures.serviceUsers,
    fixtures.visits,
    fixtures.medications,
    fixtures.messages,
    fixtures.tasks,
    fixtures.incidents
  ].every((records) => records.every((record) => Boolean(record.companyId && companyIds.has(record.companyId))));
  const primaryLeakageCount = fixtures.staffRecords.filter((member) => member.companyId !== launchPrimaryCompanyId && /Sarah Williams|Ahmed Khan|Mary Johnson/i.test(member.name)).length;
  return {
    companies: fixtures.companies.length,
    allRecordsHaveCompanyId,
    primaryLeakageCount,
    staff: fixtures.staffRecords.length,
    serviceUsers: fixtures.serviceUsers.length,
    visits: fixtures.visits.length,
    medicationRecords: fixtures.medications.length,
    messages: fixtures.messages.length,
    tasks: fixtures.tasks.length
  };
}

