      <SectionTitle action={<button className="rounded-md border border-slate-200 px-3 py-2 text-xs font-bold text-slate-700" onClick={onClose} type="button">Close</button>} subtitle="Use for short periods where staff cannot work." title="Mark Unavailable" />
