type RotaWorkflowMode = "home" | "new-allocation" | "existing" | "unallocated" | "published" | "monthly" | "audit";

export function RotaShiftAllocationPage() {
  const demoStore = useCareVerityDemoStore();
  const allClients = useMemo(() => mergeByKey([...rotaServiceUsers], demoStore.localClients, (client) => client.id), [demoStore.localClients]);
  const allStaffForRota = useMemo(() => mergeByKey([...staff], demoStore.localStaff, (member) => member.ref), [demoStore.localStaff]);
  const [workflowMode, setWorkflowMode] = useState<RotaWorkflowMode>("home");
  const [selectedClientId, setSelectedClientId] = useState(allClients[0].id);
  const [selectedCallTypes, setSelectedCallTypes] = useState<string[]>(["Morning Call"]);
  const [dateRange, setDateRange] = useState("Two weeks");
  const [allocationType, setAllocationType] = useState("Permanent regular carer");
  const [selectedCarer, setSelectedCarer] = useState("Demo Care Worker A");
  const [published, setPublished] = useState(false);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const client = params.get("client");
    const call = params.get("call");
    const calls = params.get("calls");
    const range = params.get("range");
    const allocation = params.get("allocation");
    if (client) {
      setSelectedClientId(clientIdFromPathSegment(client, allClients));
      setWorkflowMode("new-allocation");
    }
    if (calls) {
      setSelectedCallTypes(calls.split(",").map((item) => item.trim()).filter(Boolean));
    }
    if (call) {
      setSelectedCallTypes([call]);
    }
    if (range) {
      setDateRange(range);
    }
    if (allocation) {
      setAllocationType(allocation);
      if (/emergency/i.test(allocation)) {
        setDateRange("One day");
        setSelectedCarer("Ahmed Khan");
      }
      if (/permanent/i.test(allocation)) {
        setDateRange(range ?? "One month");
        setSelectedCarer("Sarah Williams");
      }
    }
  }, [allClients]);

  const selectedClient = allClients.find((user) => user.id === selectedClientId) ?? allClients[0];

  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle
          action={<a className="rounded-md bg-[#0B1F3A] px-4 py-2 text-sm font-bold text-white" href="/careverity-ecm/live-ecm">Open Live ECM Board</a>}
          subtitle="Create client visits, allocate care workers, manage regular carers, temporary cover, unallocated visits and future rota planning."
          title="Rota / Shift Allocation"
        />
        <div className="grid gap-3 md:grid-cols-4">
          <RotaStat label="Start from" tone="blue" value="Service user" />
          <RotaStat label="Unallocated visits" tone="red" value="18" />
          <RotaStat label="Permanent carers" tone="green" value="31 active" />
          <RotaStat label="Publish status" tone={published ? "green" : "amber"} value={published ? "Published" : "Draft"} />
        </div>
      </Card>

      <DemoRotaAllocationConnectionPanel allocations={demoStore.localAllocations} visits={demoStore.localVisits} visit={demoStore.demoVisit} />

      {workflowMode === "home" ? (
        <RotaWorkflowHome setWorkflowMode={setWorkflowMode} />
      ) : workflowMode === "new-allocation" ? (
        <ClientFirstAllocationWorkflow
          allocationType={allocationType}
          dateRange={dateRange}
          onBack={() => setWorkflowMode("home")}
          published={published}
          selectedCallTypes={selectedCallTypes}
          selectedCarer={selectedCarer}
          availableStaff={allStaffForRota}
          availableClients={allClients}
          localCallCards={demoStore.localCalls}
          onCreateAllocation={demoStore.createAllocation}
          selectedClient={selectedClient}
          selectedClientId={selectedClientId}
          setAllocationType={setAllocationType}
          setDateRange={setDateRange}
          setPublished={setPublished}
          setSelectedCallTypes={setSelectedCallTypes}
          setSelectedCarer={setSelectedCarer}
          setSelectedClientId={setSelectedClientId}
        />
      ) : workflowMode === "existing" ? (
        <ExistingAllocationsWorkflow onBack={() => setWorkflowMode("home")} />
      ) : workflowMode === "unallocated" ? (
        <UnallocatedRotaPlannerView setSelectedShift={() => undefined} />
      ) : workflowMode === "published" ? (
        <PublishedRotaWorkflow onBack={() => setWorkflowMode("home")} />
      ) : workflowMode === "monthly" ? (
        <MonthlyPlanningWorkflow onBack={() => setWorkflowMode("home")} />
      ) : (
        <RotaAuditTrailPanel />
      )}
    </div>
  );
}

function DemoRotaAllocationConnectionPanel({ allocations, visit, visits }: { allocations: DemoAllocationRecord[]; visit: DemoVisitRecord | null; visits: DemoVisitRecord[] }) {
  const allocation = allocations.find((item) => item.id === "UAT-ALLOC-PERM-MARY-001") ?? allocations.find((item) => item.id === "DEMO-ALLOC-001");
  const emergencyAllocation = allocations.find((item) => item.id === "UAT-ALLOC-EMERGENCY-MARY-001");
  const permanentVisitCount = visits.filter((item) => item.serviceUserName === "Mary Johnson" && item.staffName === "Sarah Williams").length;
  const emergencyVisit = visits.find((item) => item.id === "UAT-MARY-EMERGENCY-001");
  return (
    <Card className="border-l-4 border-l-emerald-500">
      <SectionTitle
        action={<a className="rounded-md bg-teal-600 px-4 py-2 text-sm font-bold text-white" href="/careverity-ecm/mobile/demo-visit">Open Staff Visit View</a>}
        subtitle="Saved demo allocations link service user call packages, staff allocation, mobile visits and the Live ECM expected visit board."
        title="Demo Visit Allocation"
      />
      <div className="grid gap-3 md:grid-cols-4">
        <DemoResultTile label="Service user" value={allocation?.clientName ?? "Create demo allocation first"} />
        <DemoResultTile label="Staff" value={allocation?.carer ?? "Pending"} />
        <DemoResultTile label="Call" value={allocation?.callTypes.join(", ") ?? "Morning Call"} />
        <DemoResultTile label="Date" value={allocation?.dateRange ?? demoDateStamp()} />
        <DemoResultTile label="Time" value={visit ? `${visit.expectedStart} to ${visit.expectedEnd}` : "08:00 to 08:45"} />
        <DemoResultTile label="Status" value={visit?.status ?? "Not logged in"} />
        <DemoResultTile label="Allocation type" value={allocation?.allocationType ?? "Temporary for test"} />
        <DemoResultTile label="Funding / priority" value="Local Authority / High risk" />
        <DemoResultTile label="Mary/Sarah month visits" value={permanentVisitCount ? `${permanentVisitCount} visits created` : "Pending"} />
        <DemoResultTile label="Ahmed emergency call" value={emergencyAllocation ? `${emergencyAllocation.callTypes.join(", ")} / ${emergencyVisit?.status ?? "Allocated"}` : "Pending"} />
      </div>
      {allocations.length ? (
        <div className="mt-4 overflow-x-auto rounded-lg border border-slate-200">
          <table className="w-full min-w-[760px] text-left text-sm">
            <thead className="bg-slate-50 text-xs uppercase text-slate-500">
              <tr>{["Allocation ID", "Service user", "Call", "Staff", "Date range", "Type", "Visits", "Published"].map((heading) => <th className="p-3" key={heading}>{heading}</th>)}</tr>
            </thead>
            <tbody className="divide-y divide-slate-100 bg-white">
              {allocations.map((item) => (
                <tr key={item.id}>
                  <td className="p-3 font-mono text-xs font-bold text-slate-700">{item.id}</td>
                  <td className="p-3 font-bold text-slate-900">{item.clientName}</td>
                  <td className="p-3 text-slate-700">{item.callTypes.join(", ")}</td>
                  <td className="p-3 text-slate-700">{item.carer}</td>
                  <td className="p-3 text-slate-700">{item.dateRange}</td>
                  <td className="p-3"><PillBadge tone={item.allocationType.includes("Emergency") || item.allocationType.includes("emergency") ? "red" : item.allocationType.includes("Permanent") ? "green" : "amber"}>{item.allocationType}</PillBadge></td>
                  <td className="p-3 font-bold text-slate-700">{item.visitsCreated}</td>
                  <td className="p-3">{item.published ? "Yes" : "Draft"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : null}
    </Card>
  );
}

function RotaWorkflowHome({ setWorkflowMode }: { setWorkflowMode: (mode: RotaWorkflowMode) => void }) {
  const options: Array<[RotaWorkflowMode, string, string, IconName, Tone]> = [
    ["new-allocation", "Start New Allocation", "Select service user, one or more calls, date range, suitable carer, permanent/temporary allocation and publish.", "plus", "teal"],
    ["existing", "View Existing Allocations", "Open a filtered allocation register only after choosing this view.", "calendar", "blue"],
    ["unallocated", "Unallocated Visits", "Find calls without carers and allocate suitable cover.", "alert", "red"],
    ["published", "Published Rota", "View published future visits and staff notifications.", "check", "green"],
    ["monthly", "Monthly Planning", "Plan next 30 days, copy previous week and validate conflicts.", "bar-chart", "purple"],
    ["audit", "Rota Audit", "View allocation, publish, override and notification audit records.", "file-text", "slate"]
  ];
  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle subtitle="Choose a rota workflow first. The screen no longer starts with all carers and all clients mixed together." title="Rota workflow" />
        <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
          {options.map(([mode, title, description, icon, tone]) => (
            <button className="rounded-lg border border-slate-200 bg-white p-5 text-left transition hover:border-teal-300 hover:bg-teal-50" key={mode} onClick={() => setWorkflowMode(mode)} type="button">
              <span className={iconToneClass(tone)}><Icon className="h-5 w-5" name={icon} /></span>
              <div className="mt-4 text-xl font-black text-slate-900">{title}</div>
              <p className="mt-2 text-sm leading-6 text-slate-600">{description}</p>
            </button>
          ))}
        </div>
      </Card>
      <Card>
        <SectionTitle subtitle="Client calls are created in Client Files, then published rota becomes expected Live ECM visits." title="Data flow" />
        <div className="grid gap-3 md:grid-cols-3 xl:grid-cols-6">
          {["Client calls created in Client Files", "Select client in Rota", "Allocate suitable carer", "Publish expected visits", "Live ECM monitors today", "Payroll, invoices, KPI and CQC update"].map((step, index) => (
            <div className="rounded-lg border border-slate-200 bg-slate-50 p-3" key={step}>
              <div className="flex h-8 w-8 items-center justify-center rounded-full bg-teal-600 text-sm font-black text-white">{index + 1}</div>
              <div className="mt-3 text-sm font-bold leading-5 text-slate-800">{step}</div>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}

function ClientFirstAllocationWorkflow({
  allocationType,
  availableStaff,
  availableClients,
  dateRange,
  localCallCards,
  onCreateAllocation,
  onBack,
  published,
  selectedCallTypes,
  selectedCarer,
  selectedClient,
  selectedClientId,
  setAllocationType,
  setDateRange,
  setPublished,
  setSelectedCallTypes,
  setSelectedCarer,
  setSelectedClientId
}: {
  allocationType: string;
  availableStaff: StaffMember[];
  availableClients: ServiceUserRecord[];
  dateRange: string;
  localCallCards: Record<string, RotaCallCard[]>;
  onCreateAllocation: (allocation: DemoAllocationRecord) => DemoAllocationRecord;
  onBack: () => void;
  published: boolean;
  selectedCallTypes: string[];
  selectedCarer: string;
  selectedClient: ServiceUserRecord;
  selectedClientId: string;
  setAllocationType: (value: string) => void;
  setDateRange: (value: string) => void;
  setPublished: (value: boolean) => void;
  setSelectedCallTypes: (value: string[]) => void;
  setSelectedCarer: (value: string) => void;
  setSelectedClientId: (value: string) => void;
}) {
  const [carerAssignmentMode, setCarerAssignmentMode] = useState<"same" | "different">("same");
  const [careWorker2, setCareWorker2] = useState("Demo Care Worker B");
  const activeCallBase = localCallCards[selectedClientId] ?? getServiceUserCallCards(selectedClientId);
  const selectedMissingCalls: RotaCallCard[] = selectedCallTypes
    .filter((callType) => !activeCallBase.some((call) => call.callType === callType))
    .map((callType) => callType === "Emergency Welfare Call"
      ? makeUatCallPackage()[1]
      : { callType, start: "08:00", end: "08:45", duration: "45m", carerMode: "Single carer", requiredSkills: "Configured for UAT", riskLevel: "High", status: "Unallocated", permanentCarer: "Not assigned", funding: selectedClient.funding });
  const activeCalls = [...activeCallBase, ...selectedMissingCalls];
  const availableCallTypes = activeCalls.map((call) => call.callType);
  const selectedCalls = activeCalls.filter((call) => selectedCallTypes.includes(call.callType));
  const selectedCoreCalls = ["Morning Call", "Lunch Call", "Tea Call", "Bed Call"].filter((callType) => availableCallTypes.includes(callType));
  const selectedVisitsCount = visitsCreatedForRange(dateRange, selectedCalls.length);
  const requiresDoubleUp = selectedCalls.some((call) => call.carerMode === "Double-up");
  const importedCarers = availableStaff
    .filter((member) => !rotaPlannerCarers.some((carer) => carer.name === member.name))
    .map((member) => ({
      name: member.name,
      initials: member.photo,
      role: member.role,
      locality: "Imported provider",
      availability: member.status === "Active" ? "Available" : "Review status",
      leave: "No imported absence",
      training: member.training || "Import review",
      skills: [member.jobTitle ?? member.role, member.rightToWork ?? "Right-to-work review"].filter(Boolean).join(" + "),
      dbs: `${member.dbs || "DBS review"}/${member.rightToWork || "right-to-work review"}`,
      dayHours: "To confirm",
      weekHours: "To confirm",
      overtime: "Import review",
      travel: "Locality to map",
      continuity: "New imported staff",
      preference: "Imported",
      score: member.status === "Active" ? "Imported" : "Review"
    }));
  const suitableCarers = [...rotaPlannerCarers, ...importedCarers];
  const allocationTone: Tone = allocationType === "Permanent regular carer" ? "green" : allocationType === "Temporary cover" ? "amber" : /Emergency|emergency/.test(allocationType) ? "red" : "blue";
  const demoDifferentCarers = ["Demo Care Worker A", "Demo Care Worker B", "Demo Float Worker C", "Demo Outreach Worker A", ...importedCarers.map((carer) => carer.name)];
  const selectCalls = (callTypes: string[]) => {
    setSelectedCallTypes(callTypes.filter((callType) => availableCallTypes.includes(callType)));
    setPublished(false);
  };
  const toggleCall = (callType: string) => {
    setSelectedCallTypes(selectedCallTypes.includes(callType) ? selectedCallTypes.filter((item) => item !== callType) : [...selectedCallTypes, callType]);
    setPublished(false);
  };
  const handleClientChange = (clientId: string) => {
    const firstCall = (localCallCards[clientId] ?? getServiceUserCallCards(clientId))[0]?.callType;
    setSelectedClientId(clientId);
    setSelectedCallTypes(firstCall ? [firstCall] : []);
    setPublished(false);
  };
  const saveAllocation = (publish: boolean) => {
    const allocation = onCreateAllocation({
      id: `alloc-${selectedClientId}-${Date.now()}`,
      clientId: selectedClientId,
      clientName: selectedClient.name,
      callTypes: selectedCalls.map((call) => call.callType),
      carer: selectedCarer,
      dateRange,
      allocationType,
      visitsCreated: selectedVisitsCount,
      published: publish
    });
    setPublished(allocation.published || publish);
  };
  const carerForSelectedCall = (index: number) => (carerAssignmentMode === "same" ? selectedCarer : demoDifferentCarers[index % demoDifferentCarers.length]);
  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle action={<button className="rounded-md border border-slate-200 px-4 py-2 text-sm font-bold text-slate-700" onClick={onBack} type="button">Back</button>} subtitle="Select service user -> select one or more calls -> select date range -> select suitable carer -> choose permanent or temporary -> save/publish." title="Start New Allocation" />
        <div className="grid gap-3 md:grid-cols-2">
          <FilterSelect label="Step 1 - Select Service User" onChange={handleClientChange} options={availableClients.map((user) => user.id)} value={selectedClientId} />
          <ProfileMini label="Workflow" value="Client first, then calls, date range, carer, allocation type and publish" />
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-4">
          <ProfileMini label="Selected client" value={selectedClient.name} />
          <ProfileMini label="Package" value={selectedClient.package} />
          <ProfileMini label="Funding" value={selectedClient.funding} />
          <ProfileMini label="Required skills" value={selectedClient.regularTeam.skills.join(", ")} />
        </div>
      </Card>

      <Card>
        <SectionTitle subtitle="Select one or more active calls for the selected service user. The same allocation can then be applied to all selected calls." title="Step 2 - Select Call(s)" />
        <div className="mb-4 flex flex-wrap gap-2">
          <button className="rounded-md bg-[#0B1F3A] px-3 py-2 text-xs font-bold text-white" onClick={() => selectCalls(availableCallTypes)} type="button">Select All Calls</button>
          <button className="rounded-md bg-teal-50 px-3 py-2 text-xs font-bold text-teal-800 ring-1 ring-teal-200" onClick={() => selectCalls(selectedCoreCalls)} type="button">Select Morning / Lunch / Tea / Bed</button>
          <button className="rounded-md bg-slate-50 px-3 py-2 text-xs font-bold text-slate-700 ring-1 ring-slate-200" onClick={() => selectCalls([])} type="button">Clear Selection</button>
          <button className="rounded-md bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-800 ring-1 ring-emerald-200" onClick={() => selectCalls(["Morning Call", "Lunch Call", "Tea Call"])} type="button">Demo: Morning + Lunch + Tea</button>
          <button className="rounded-md bg-amber-50 px-3 py-2 text-xs font-bold text-amber-800 ring-1 ring-amber-200" onClick={() => selectCalls(["Morning Call", "Bed Call"])} type="button">Demo: Morning + Bed</button>
        </div>
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          {activeCalls.map((call) => {
            const selected = selectedCallTypes.includes(call.callType);
            return (
              <button className={`rounded-lg border p-4 text-left transition ${selected ? "border-teal-400 bg-teal-50 shadow-sm" : "border-slate-200 bg-white hover:border-teal-200"}`} key={call.callType} onClick={() => toggleCall(call.callType)} type="button">
                <div className="flex items-start justify-between gap-3">
                  <span className="flex min-w-0 items-start gap-3">
                    <input checked={selected} className="mt-1 h-4 w-4 rounded border-slate-300 text-teal-600" onChange={() => toggleCall(call.callType)} onClick={(event) => event.stopPropagation()} type="checkbox" />
                    <span className="min-w-0">
                      <span className="block font-black text-slate-900">{call.callType}</span>
                      <span className="mt-1 block text-xs font-semibold text-slate-500">{call.start} to {call.end} | {call.duration}</span>
                    </span>
                  </span>
                  <PillBadge tone={rotaCallStatusTone(call.status)}>{call.status}</PillBadge>
                </div>
                <div className="mt-3 grid gap-2 text-xs sm:grid-cols-2">
                  <ProfileMini label="Carers" value={call.carerMode} />
                  <ProfileMini label="Risk" value={call.riskLevel} />
                  <ProfileMini label="Skills" value={call.requiredSkills} />
                  <ProfileMini label="Regular carer" value={call.permanentCarer} />
                </div>
              </button>
            );
          })}
        </div>
        {selectedCalls.length ? (
          <div className="mt-4 rounded-lg bg-slate-50 p-3 text-sm font-bold text-slate-700 ring-1 ring-slate-100">
            Selected calls: {selectedCalls.map((call) => call.callType).join(", ")}
          </div>
        ) : (
          <div className="mt-4 rounded-lg bg-rose-50 p-3 text-sm font-bold text-rose-800 ring-1 ring-rose-100">Select at least one call before choosing carers.</div>
        )}
      </Card>

      <Card>
        <SectionTitle subtitle="Choose how far ahead the selected calls should be created and allocated." title="Step 3 - Select Date Range" />
        <div className="grid gap-3 md:grid-cols-4">
          {["One day", "Two weeks", "One month", "Custom date range"].map((range) => (
            <button className={`rounded-lg border p-4 text-left transition ${dateRange === range ? "border-teal-400 bg-teal-50" : "border-slate-200 bg-white hover:border-teal-200"}`} key={range} onClick={() => { setDateRange(range); setPublished(false); }} type="button">
              <div className="text-sm font-black text-slate-900">{range}</div>
              <div className="mt-2 text-xs font-semibold text-slate-500">{visitsCreatedForRange(range, selectedCalls.length)} visit records for selected calls</div>
            </button>
          ))}
        </div>
      </Card>

      <Card>
        <SectionTitle subtitle="Carers appear after a service user and at least one call are selected. Use filters to narrow the suitable list." title="Step 4 - Select Suitable Carer" />
        <div className="mb-4 flex flex-wrap gap-2">
          {["Show available only", "Show preferred carers", "Show regular carers", "Show float pool", "Show same area only", "Show medication trained", "Show moving and handling trained", "Show dementia trained", "Show double-up suitable", "Show no overtime warning"].map((filter, index) => (
            <label className="flex items-center gap-2 rounded-md bg-slate-50 px-3 py-2 text-xs font-bold text-slate-700 ring-1 ring-slate-200" key={filter}>
              <input defaultChecked={index === 0 || index === 4} type="checkbox" />
              {filter}
            </label>
          ))}
        </div>
        <div className="grid gap-4 xl:grid-cols-2">
          {suitableCarers.map((carer) => (
            <div className={`rounded-lg border p-4 ${selectedCarer === carer.name ? "border-teal-400 bg-teal-50" : "border-slate-200 bg-white"}`} key={carer.name}>
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="flex items-center gap-3">
                  <div className="grid h-10 w-10 place-items-center rounded-full bg-teal-100 font-black text-teal-800">{carer.initials}</div>
                  <div><div className="font-black text-slate-900">{carer.name}</div><div className="text-xs text-slate-500">{carer.role} | {carer.locality}</div></div>
                </div>
                <PillBadge tone={carer.score === "Blocked" ? "red" : carer.score === "97%" || carer.score === "94%" ? "green" : "amber"}>{carer.score} suitability</PillBadge>
              </div>
              <div className="mt-3 grid gap-2 text-xs md:grid-cols-3">
                <ProfileMini label="Availability" value={carer.availability} />
                <ProfileMini label="Training match" value={carer.training} />
                <ProfileMini label="DBS/right-to-work" value={carer.dbs} />
                <ProfileMini label="Skills match" value={carer.skills} />
                <ProfileMini label="Continuity score" value={carer.continuity} />
                <ProfileMini label="Preference" value={carer.preference} />
                <ProfileMini label="Weekly hours" value={carer.weekHours} />
                <ProfileMini label="Overtime warning" value={carer.overtime} />
                <ProfileMini label="Travel warning" value={carer.travel} />
              </div>
              {carer.score === "Blocked" ? (
                <div className="mt-3 rounded-md bg-rose-50 p-3 text-xs font-bold text-rose-900 ring-1 ring-rose-100">
                  Staff member is unavailable due to leave/absence. Allocation is blocked unless manager override is used, a reason is recorded and an audit log is created.
                </div>
              ) : carer.availability !== "Available" ? (
                <div className="mt-3 rounded-md bg-amber-50 p-3 text-xs font-bold text-amber-900 ring-1 ring-amber-100">
                  Staff member is not available during this visit time. Manager override requires reason and audit.
                </div>
              ) : null}
              <button className="mt-3 rounded-md bg-[#0B1F3A] px-3 py-2 text-xs font-bold text-white disabled:bg-slate-300" disabled={carer.score === "Blocked"} onClick={() => setSelectedCarer(carer.name)} type="button">Assign</button>
            </div>
          ))}
        </div>
      </Card>

      <Card>
        <SectionTitle subtitle="Choose permanent regular carer or temporary cover, then decide whether the same carer applies to every selected call." title="Step 5 - Choose Permanent or Temporary" />
        <div className="grid gap-3 lg:grid-cols-2">
          <label className={`rounded-lg border p-4 ${carerAssignmentMode === "same" ? "border-teal-400 bg-teal-50" : "border-slate-200 bg-white"}`}>
            <input checked={carerAssignmentMode === "same"} className="mr-2" onChange={() => setCarerAssignmentMode("same")} type="radio" />
            <span className="font-black text-slate-900">Option A: Apply same carer to all selected calls</span>
            <p className="mt-2 text-sm text-slate-600">{selectedCarer} will be Care Worker 1 for every selected call.</p>
          </label>
          <label className={`rounded-lg border p-4 ${carerAssignmentMode === "different" ? "border-teal-400 bg-teal-50" : "border-slate-200 bg-white"}`}>
            <input checked={carerAssignmentMode === "different"} className="mr-2" onChange={() => setCarerAssignmentMode("different")} type="radio" />
            <span className="font-black text-slate-900">Option B: Choose different carers per call</span>
            <p className="mt-2 text-sm text-slate-600">Demo assignments split Morning, Lunch and Tea across suitable carers.</p>
          </label>
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          <ProfileMini label="Care Worker 1" value={selectedCarer} />
          <FilterSelect label="Care Worker 2 for double-up" onChange={setCareWorker2} options={["Not required", "Demo Care Worker B", "Demo Float Worker C", "Demo Outreach Worker A", ...importedCarers.map((carer) => carer.name)]} value={requiresDoubleUp ? careWorker2 : "Not required"} />
          <FilterSelect label="Allocation type" onChange={(value) => { setAllocationType(value); setPublished(false); }} options={["Permanent regular carer", "Temporary cover", "One-off cover", "One-off / emergency cover", "Leave cover", "Emergency cover", "Replacement cover"]} value={allocationType} />
          <ProfileMini label="Date range" value={dateRange} />
        </div>
        <div className="mt-4 overflow-x-auto rounded-lg border border-slate-200">
          <table className="w-full min-w-[900px] text-left text-sm">
            <thead className="bg-slate-50 text-xs uppercase text-slate-500">
              <tr>{["Selected call", "Time", "Care Worker 1", "Care Worker 2", "Allocation", "Status colour"].map((heading) => <th className="p-3" key={heading}>{heading}</th>)}</tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {selectedCalls.map((call, index) => (
                <tr className="bg-white" key={call.callType}>
                  <td className="p-3 font-bold text-slate-900">{call.callType}</td>
                  <td className="p-3 text-slate-700">{call.start} to {call.end}</td>
                  <td className="p-3 text-slate-700">{carerForSelectedCall(index)}</td>
                  <td className="p-3 text-slate-700">{call.carerMode === "Double-up" ? careWorker2 : "Not required"}</td>
                  <td className="p-3"><PillBadge tone={allocationTone}>{allocationType}</PillBadge></td>
                  <td className="p-3"><PillBadge tone={allocationTone}>{allocationType.includes("Permanent") ? "Green" : allocationType.includes("Temporary") ? "Amber" : "Blue"}</PillBadge></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <label className="mt-4 block">
          <span className="text-xs font-bold uppercase text-slate-500">Reason/comment</span>
          <textarea className="mt-2 min-h-20 w-full rounded-md border border-slate-200 px-3 py-2 text-sm" defaultValue={allocationType === "Temporary cover" ? "Temporary cover reason required. Regular carer retained unless replacement is confirmed." : "Continuity priority and rota compliance checked. Manager override required if warnings remain."} />
        </label>
      </Card>

      <Card>
        <SectionTitle subtitle="Review all selected calls before saving or publishing. Warnings remain visible for manager override and audit." title="Step 6 - Save / Publish" />
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          <ProfileMini label="Service user" value={selectedClient.name} />
          <ProfileMini label="Selected calls" value={selectedCalls.length ? selectedCalls.map((call) => call.callType).join(", ") : "None selected"} />
          <ProfileMini label="Date range" value={dateRange} />
          <ProfileMini label="Visits to be created" value={`${selectedVisitsCount}`} />
          <ProfileMini label="Carer mode" value={carerAssignmentMode === "same" ? "Same carer for all calls" : "Different carers per call"} />
          <ProfileMini label="Selected carer" value={selectedCarer} />
          <ProfileMini label="Allocation type" value={allocationType} />
          <ProfileMini label="Double-up" value={requiresDoubleUp ? `Care Worker 2: ${careWorker2}` : "Not required"} />
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-3">
          {["Availability checked", "Training and competency checked", "Overtime and travel warning checked", "Leave/absence checked", "Conflict warning checked", "Double-up requirement checked"].map((item, index) => (
            <div className="rounded-md bg-slate-50 p-3 text-sm font-bold text-slate-700 ring-1 ring-slate-100" key={item}>
              <PillBadge tone={index === 2 || (requiresDoubleUp && index === 5) ? "amber" : "green"}>{item}</PillBadge>
            </div>
          ))}
        </div>
        <div className="mt-4 flex flex-wrap gap-2">
          <button className="rounded-md bg-teal-600 px-4 py-2 text-sm font-bold text-white disabled:bg-slate-300" disabled={!selectedCalls.length} onClick={() => saveAllocation(false)} type="button">Save Allocation</button>
          <button className="rounded-md bg-slate-100 px-4 py-2 text-sm font-bold text-slate-700" onClick={() => saveAllocation(false)} type="button">Save as Draft</button>
          <button className="rounded-md bg-[#0B1F3A] px-4 py-2 text-sm font-bold text-white disabled:bg-slate-300" disabled={!selectedCalls.length} onClick={() => saveAllocation(true)} type="button">Publish Rota</button>
          <button className="rounded-md border border-slate-200 px-4 py-2 text-sm font-bold text-slate-700" onClick={onBack} type="button">Cancel</button>
          <a className="rounded-md bg-slate-100 px-4 py-2 text-sm font-bold text-slate-700" href={`/careverity-ecm/clients/${clientSlug(selectedClient)}`}>View Client Rota</a>
          <a className="rounded-md bg-slate-100 px-4 py-2 text-sm font-bold text-slate-700" href="/careverity-ecm/live-ecm">View in Live ECM</a>
        </div>
        {published ? (
          <div className="mt-3 rounded-md bg-emerald-50 p-3 text-sm font-bold text-emerald-800 ring-1 ring-emerald-100">
            Published: {selectedClient.name} {selectedCalls.map((call) => call.callType).join(", ")} allocated for {dateRange}. Staff notification placeholder queued.
          </div>
        ) : null}
      </Card>

      <Card>
        <SectionTitle subtitle="Status colours: green permanent, amber temporary, red unallocated, blue allocated, grey cancelled/stopped, red/pink warnings." title="Selected service user allocation display" />
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          {activeCalls.map((call) => {
            const isSelected = selectedCallTypes.includes(call.callType);
            const tone = published && isSelected ? allocationTone : rotaCallStatusTone(call.status);
            const label = published && isSelected ? allocationType : call.status;
            return (
              <div className={`rounded-lg border p-4 ${isSelected ? "border-teal-300 bg-teal-50" : "border-slate-200 bg-white"}`} key={call.callType}>
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <div className="font-black text-slate-900">{call.callType}</div>
                    <div className="mt-1 text-xs font-semibold text-slate-500">{call.start} to {call.end}</div>
                  </div>
                  <PillBadge tone={tone}>{label}</PillBadge>
                </div>
                <div className="mt-3 text-xs font-semibold text-slate-600">{published && isSelected ? `${selectedCarer} allocated` : call.permanentCarer}</div>
              </div>
            );
          })}
        </div>
      </Card>
    </div>
  );
}

function ExistingAllocationsWorkflow({ onBack }: { onBack: () => void }) {
  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle action={<button className="rounded-md border border-slate-200 px-4 py-2 text-sm font-bold text-slate-700" onClick={onBack} type="button">Back</button>} subtitle="Separate allocation register with filters. This is not the first rota screen." title="View Existing Allocations" />
        <div className="grid gap-3 md:grid-cols-3 xl:grid-cols-5">
          {["Service user", "Carer", "Date", "Call type", "Funding source"].map((filter) => <FilterSelect key={filter} label={filter} onChange={() => undefined} options={["All", "Demo Service User 101", "Demo Care Worker A", "Morning Call", "Local Authority"]} value="All" />)}
        </div>
        <div className="mt-3 flex flex-wrap gap-2">
          {["Unallocated", "Permanent", "Temporary", "High risk", "Double-up"].map((item) => <button className="rounded-md bg-slate-50 px-3 py-2 text-xs font-bold text-slate-700 ring-1 ring-slate-200" key={item} type="button">{item}</button>)}
        </div>
      </Card>
      <MedicationSimpleTable headings={["Service user", "Call type", "Date", "Time", "Care Worker 1", "Care Worker 2", "Allocation", "Risk", "Funding"]} rows={rotaPlannerShifts.map((shift) => [shift.serviceUser, shift.callType, shift.date, `${shift.time}-${shift.end}`, shift.carer, shift.carer2, shift.status, shift.risk, shift.funding])} title="Existing allocation register" />
    </div>
  );
}

function PublishedRotaWorkflow({ onBack }: { onBack: () => void }) {
  return (
    <Card>
      <SectionTitle action={<button className="rounded-md border border-slate-200 px-4 py-2 text-sm font-bold text-slate-700" onClick={onBack} type="button">Back</button>} subtitle="Published future visits and staff notification placeholders." title="Published Rota" />
      <MedicationSimpleTable headings={["Date", "Service user", "Call", "Time", "Assigned staff", "Notification", "Status"]} rows={rotaPlannerShifts.filter((shift) => shift.status !== "Cancelled").map((shift) => [shift.date, shift.serviceUser, shift.callType, `${shift.time}-${shift.end}`, shift.carer, "Queued/sent placeholder", shift.status])} title="Published rota view" />
    </Card>
  );
}

function MonthlyPlanningWorkflow({ onBack }: { onBack: () => void }) {
  const [monthPublished, setMonthPublished] = useState(false);
  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle action={<button className="rounded-md border border-slate-200 px-4 py-2 text-sm font-bold text-slate-700" onClick={onBack} type="button">Back</button>} subtitle="Plan next 30 days without mixing all carers and clients on the opening screen." title="Monthly Planning" />
      </Card>
      <OneMonthAdvancePanel monthPublished={monthPublished} setMonthPublished={setMonthPublished} />
      <BulkAllocationToolsPanel />
    </div>
  );
}

const rotaPlannerViews = ["Client View", "Carer View", "Day View", "Week View", "Month Planning View", "Unallocated Visits View", "Permanent Allocation View", "Float Pool / Cover View"] as const;
type RotaPlannerView = (typeof rotaPlannerViews)[number];

const rotaPlannerRoutes = ["/rota", "/rota/planner", "/rota/client-view", "/rota/carer-view", "/rota/unallocated", "/rota/shift/[shiftId]", "/rota/bulk-allocation", "/rota/permanent-allocations"];

function rotaPlannerViewFromPath(pathname: string): RotaPlannerView {
  if (pathname.includes("/rota/carer-view")) return "Carer View";
  if (pathname.includes("/rota/unallocated")) return "Unallocated Visits View";
  if (pathname.includes("/rota/permanent-allocations")) return "Permanent Allocation View";
  if (pathname.includes("/rota/shift/")) return "Day View";
  return "Client View";
}

