function RotaPlannerShiftAllocationModule() {
  const [plannerView, setPlannerView] = useState<RotaPlannerView>("Client View");
  const [shiftSaved, setShiftSaved] = useState(false);
  const [allocationSaved, setAllocationSaved] = useState(false);
  const [permanentAllocation, setPermanentAllocation] = useState(true);
  const [stopSaved, setStopSaved] = useState(false);
  const [monthPublished, setMonthPublished] = useState(false);
  const [selectedShift, setSelectedShift] = useState(rotaPlannerShifts[0]);

  useEffect(() => {
    setPlannerView(rotaPlannerViewFromPath(window.location.pathname));
  }, []);

  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle
          action={<button className="inline-flex items-center gap-2 rounded-md bg-teal-600 px-4 py-2 text-sm font-bold text-white" onClick={() => setShiftSaved(false)} type="button"><Icon className="h-4 w-4" name="plus" />Add Shift</button>}
          subtitle="Allocate staff to service-user shifts, stop shifts, manage permanent or temporary cover, and publish up to one month in advance."
          title="Rota Planner / Shift Allocation"
        />
        <div className="grid gap-3 md:grid-cols-4">
          <RotaStat label="Next 30 days" tone="teal" value="412 shifts" />
          <RotaStat label="Unallocated" tone="red" value="18" />
          <RotaStat label="Conflicts" tone="amber" value="7 warnings" />
          <RotaStat label="Published status" tone={monthPublished ? "green" : "blue"} value={monthPublished ? "Published" : "Draft"} />
        </div>
        <div className="mt-4 grid gap-2 md:grid-cols-4">
          {rotaPlannerRoutes.map((route) => <div className="rounded-md bg-slate-50 p-2 font-mono text-xs font-bold text-slate-700 ring-1 ring-slate-100" key={route}>{route}</div>)}
        </div>
      </Card>

      <Card>
        <SectionTitle subtitle="Switch between client rows, carer rows, day/week/month planning, unallocated work, permanent allocations and float pool cover." title="Rota views" />
        <div className="flex flex-wrap gap-2">
          {rotaPlannerViews.map((view) => (
            <button className={`rounded-md px-3 py-2 text-xs font-bold ${plannerView === view ? "bg-[#0B1F3A] text-white" : "bg-slate-50 text-slate-700 ring-1 ring-slate-200"}`} key={view} onClick={() => setPlannerView(view)} type="button">
              {view}
            </button>
          ))}
        </div>
      </Card>

      <RotaPlannerViewPanel plannerView={plannerView} selectedShift={selectedShift} setSelectedShift={setSelectedShift} />

      <div className="grid gap-6 xl:grid-cols-[1fr_0.9fr]">
        <AddShiftWorkflowPanel shiftSaved={shiftSaved} setShiftSaved={setShiftSaved} />
        <AllocateCarerWorkflowPanel allocationSaved={allocationSaved} permanentAllocation={permanentAllocation} setAllocationSaved={setAllocationSaved} setPermanentAllocation={setPermanentAllocation} />
      </div>

      <div className="grid gap-6 xl:grid-cols-[0.9fr_1.1fr]">
        <PermanentTemporaryAllocationPanel permanentAllocation={permanentAllocation} setPermanentAllocation={setPermanentAllocation} />
        <StopEndShiftPanel selectedShift={selectedShift} setStopSaved={setStopSaved} stopSaved={stopSaved} />
      </div>

      <OneMonthAdvancePanel monthPublished={monthPublished} setMonthPublished={setMonthPublished} />
      <BulkAllocationToolsPanel />
      <RotaStatusColoursPanel />
      <RotaSafetyChecksPanel />
      <RotaAuditTrailPanel />
    </div>
  );
}

function RotaPlannerViewPanel({ plannerView, selectedShift, setSelectedShift }: { plannerView: RotaPlannerView; selectedShift: (typeof rotaPlannerShifts)[number]; setSelectedShift: (shift: (typeof rotaPlannerShifts)[number]) => void }) {
  if (plannerView === "Client View") return <ClientRotaPlannerView selectedShift={selectedShift} setSelectedShift={setSelectedShift} />;
  if (plannerView === "Carer View") return <CarerRotaPlannerView />;
  if (plannerView === "Unallocated Visits View") return <UnallocatedRotaPlannerView setSelectedShift={setSelectedShift} />;
  if (plannerView === "Permanent Allocation View") return <PermanentAllocationPlannerView />;
  if (plannerView === "Float Pool / Cover View") return <FloatPoolCoverPlannerView />;
  return <CalendarPlanningView plannerView={plannerView} setSelectedShift={setSelectedShift} />;
}

function ClientRotaPlannerView({ selectedShift, setSelectedShift }: { selectedShift: (typeof rotaPlannerShifts)[number]; setSelectedShift: (shift: (typeof rotaPlannerShifts)[number]) => void }) {
  return (
    <Card>
      <SectionTitle subtitle="Rows are service users/clients; columns are time slots. Click a shift to view details." title="Client View" />
      <div className="overflow-x-auto rounded-lg border border-slate-200">
        <table className="w-full min-w-[1180px] text-left text-sm">
          <thead className="bg-slate-50 text-xs uppercase text-slate-500">
            <tr><th className="p-3">Service user/client</th>{rotaPlannerTimeSlots.map((slot) => <th className="p-3" key={slot}>{slot}</th>)}</tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {rotaServiceUsers.map((user) => (
              <tr key={user.id}>
                <td className="p-3 font-black text-slate-900">{user.name}<div className="mt-1 text-xs font-semibold text-slate-500">{user.package}</div></td>
                {rotaPlannerTimeSlots.map((slot) => {
                  const shift = rotaPlannerShifts.find((row) => row.serviceUser === user.name && row.slot === slot);
                  return <td className="p-2 align-top" key={`${user.id}-${slot}`}>{shift ? <ShiftMiniCard shift={shift} selected={selectedShift.id === shift.id} setSelectedShift={setSelectedShift} /> : <button className="w-full rounded-md border border-dashed border-slate-300 p-3 text-xs font-bold text-slate-500" type="button">Add new shift</button>}</td>;
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <SelectedShiftActions shift={selectedShift} />
    </Card>
  );
}

function ShiftMiniCard({ shift, selected, setSelectedShift }: { shift: (typeof rotaPlannerShifts)[number]; selected: boolean; setSelectedShift: (shift: (typeof rotaPlannerShifts)[number]) => void }) {
  return (
    <button className={`w-full rounded-md p-3 text-left text-xs font-semibold ring-2 ${selected ? "ring-[#0B1F3A]" : "ring-transparent"} ${planningStatusClass(shift.status)}`} onClick={() => setSelectedShift(shift)} type="button">
      <div className="font-black">{shift.time} {shift.callType}</div>
      <div className="mt-1">{shift.carer}{shift.doubleUp ? ` + ${shift.carer2}` : ""}</div>
      <div className="mt-2 flex flex-wrap gap-1">
        <span className="rounded-full bg-white/70 px-2 py-0.5">{shift.status}</span>
        {shift.doubleUp ? <span className="rounded-full bg-white/70 px-2 py-0.5">Double-up</span> : null}
        {shift.risk.includes("High") || shift.risk.includes("Critical") ? <span className="rounded-full bg-red-700 px-2 py-0.5 text-white">{shift.risk}</span> : null}
      </div>
    </button>
  );
}

function SelectedShiftActions({ shift }: { shift: (typeof rotaPlannerShifts)[number] }) {
  return (
    <div className="mt-4 rounded-lg bg-slate-50 p-4 ring-1 ring-slate-100">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <div className="font-black text-slate-900">Selected shift: {shift.id}</div>
          <div className="mt-1 text-sm text-slate-600">{shift.serviceUser} | {shift.callType} | {shift.date} {shift.time}-{shift.end}</div>
          <div className="mt-1 text-sm text-slate-600">{shift.instructions}</div>
        </div>
        <PillBadge tone={shift.status === "Unallocated" ? "red" : shift.status === "Temporary cover" ? "amber" : "green"}>{shift.status}</PillBadge>
      </div>
      <div className="mt-4 flex flex-wrap gap-2">
        {["View shift details", "Allocate one or more carers", "Stop/end shift", "Cancel with reason", "Reallocate shift", "Make allocation permanent", "Make allocation temporary", "Copy shifts forward"].map((action) => <button className="rounded-md bg-white px-3 py-2 text-xs font-bold text-slate-700 ring-1 ring-slate-200" key={action} type="button">{action}</button>)}
      </div>
    </div>
  );
}

function CarerRotaPlannerView() {
  return (
    <Card>
      <SectionTitle subtitle="Rows are staff/carers; columns are time slots with gaps, conflicts, travel pressure, overtime, leave and compliance blocks." title="Carer View" />
      <div className="overflow-x-auto rounded-lg border border-slate-200">
        <table className="w-full min-w-[1120px] text-left text-sm">
          <thead className="bg-slate-50 text-xs uppercase text-slate-500">
            <tr><th className="p-3">Staff/carer</th>{rotaPlannerTimeSlots.map((slot) => <th className="p-3" key={slot}>{slot}</th>)}<th className="p-3">Warnings</th></tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {rotaPlannerCarers.map((carer) => (
              <tr key={carer.name}>
                <td className="p-3 font-black text-slate-900"><span className="mr-2 inline-grid h-8 w-8 place-items-center rounded-full bg-teal-100 text-teal-800">{carer.initials}</span>{carer.name}<div className="mt-1 text-xs font-semibold text-slate-500">{carer.role} | {carer.locality}</div></td>
                {rotaPlannerTimeSlots.map((slot) => {
                  const shift = rotaPlannerShifts.find((row) => (row.carer === carer.name || row.carer2 === carer.name) && row.slot === slot);
                  return <td className="p-2 align-top" key={`${carer.name}-${slot}`}>{shift ? <div className={`rounded-md p-2 text-xs font-bold ${planningStatusClass(shift.status)}`}>{shift.serviceUser}<div>{shift.callType}</div></div> : <div className="rounded-md bg-white p-2 text-xs font-semibold text-slate-400 ring-1 ring-slate-100">Gap</div>}</td>;
                })}
                <td className="p-3 text-xs font-semibold text-slate-700">{carer.leave}; {carer.overtime}; {carer.travel}; {carer.score}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </Card>
  );
}

