function ScheduleBuilder({
  selectedUserId,
  setSelectedUserId,
  serviceType,
  setServiceType,
  scheduleMode,
  setScheduleMode,
  calendarMode,
  setCalendarMode
}: {
  selectedUserId: string;
  setSelectedUserId: (id: string) => void;
  serviceType: string;
  setServiceType: (service: string) => void;
  scheduleMode: ScheduleMode;
  setScheduleMode: (mode: ScheduleMode) => void;
  calendarMode: CalendarMode;
  setCalendarMode: (mode: CalendarMode) => void;
}) {
  const scheduleModes: ScheduleMode[] = ["One date", "Multiple dates", "Date range", "Recurring"];
  const calendarModes: CalendarMode[] = ["Day", "Week", "Calendar"];

  return (
    <Card>
      <SectionTitle subtitle="Select a demo service user, service type, date pattern and planner view." title="Create rota visits" />
      <div className="grid gap-4 lg:grid-cols-2">
        <label className="block">
          <span className="text-xs font-bold uppercase text-slate-500">Service user selector</span>
          <select
            className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-semibold text-slate-900 outline-none focus:border-teal-400"
            onChange={(event) => setSelectedUserId(event.target.value)}
            value={selectedUserId}
          >
            {rotaServiceUsers.map((user) => (
              <option key={user.id} value={user.id}>
                {user.name} - {user.package}
              </option>
            ))}
          </select>
        </label>
        <label className="block">
          <span className="text-xs font-bold uppercase text-slate-500">Service type</span>
          <select
            className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-semibold text-slate-900 outline-none focus:border-teal-400"
            onChange={(event) => setServiceType(event.target.value)}
            value={serviceType}
          >
            {rotaServiceTypes.map((service) => (
              <option key={service}>{service}</option>
            ))}
          </select>
        </label>
      </div>

      <div className="mt-5">
        <div className="mb-2 text-xs font-bold uppercase text-slate-500">Date pattern</div>
        <div className="grid gap-2 sm:grid-cols-4">
          {scheduleModes.map((mode) => (
            <button
              className={`rounded-md border px-3 py-2 text-sm font-bold transition ${
                scheduleMode === mode ? "border-teal-500 bg-teal-50 text-teal-800" : "border-slate-200 bg-white text-slate-700 hover:border-teal-200"
              }`}
              key={mode}
              onClick={() => setScheduleMode(mode)}
              type="button"
            >
              {mode}
            </button>
          ))}
        </div>
      </div>

      <div className="mt-4 rounded-lg border border-slate-200 bg-slate-50 p-4">
        {scheduleMode === "One date" ? (
          <label className="block">
            <span className="text-xs font-bold uppercase text-slate-500">Visit date</span>
            <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm" defaultValue="2026-05-18" type="date" />
          </label>
        ) : null}
        {scheduleMode === "Multiple dates" ? (
          <div>
            <div className="text-xs font-bold uppercase text-slate-500">Selected dates</div>
            <div className="mt-2 grid gap-2 sm:grid-cols-3">
              {["18 May", "20 May", "22 May", "25 May", "27 May", "29 May"].map((date, index) => (
                <label className="flex items-center gap-2 rounded-md bg-white p-2 text-sm font-semibold ring-1 ring-slate-200" key={date}>
                  <input defaultChecked={index < 3} type="checkbox" />
                  {date}
                </label>
              ))}
            </div>
          </div>
        ) : null}
        {scheduleMode === "Date range" ? (
          <div className="grid gap-3 sm:grid-cols-2">
            <label>
              <span className="text-xs font-bold uppercase text-slate-500">Start date</span>
              <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm" defaultValue="2026-05-18" type="date" />
            </label>
            <label>
              <span className="text-xs font-bold uppercase text-slate-500">End date</span>
              <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm" defaultValue="2026-06-12" type="date" />
            </label>
          </div>
        ) : null}
        {scheduleMode === "Recurring" ? (
          <div className="space-y-3">
            <div className="grid gap-3 sm:grid-cols-3">
              <label>
                <span className="text-xs font-bold uppercase text-slate-500">Repeats</span>
                <select className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-semibold">
                  <option>Weekly</option>
                  <option>Fortnightly</option>
                  <option>Every weekday</option>
                </select>
              </label>
              <label>
                <span className="text-xs font-bold uppercase text-slate-500">Duration</span>
                <select className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-semibold">
                  <option>30 minutes</option>
                  <option>45 minutes</option>
                  <option>1 hour</option>
                  <option>3 hours</option>
                </select>
              </label>
              <label>
                <span className="text-xs font-bold uppercase text-slate-500">Double-up care</span>
                <select className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-semibold">
                  <option>Use care profile rule</option>
                  <option>Always required</option>
                  <option>Not required</option>
                </select>
              </label>
            </div>
            <div>
              <div className="text-xs font-bold uppercase text-slate-500">Recurring days</div>
              <div className="mt-2 grid gap-2 sm:grid-cols-7">
                {["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((day, index) => (
                  <label className="flex items-center justify-center gap-2 rounded-md bg-white p-2 text-sm font-bold ring-1 ring-slate-200" key={day}>
                    <input defaultChecked={index < 5} type="checkbox" />
                    {day}
                  </label>
                ))}
              </div>
            </div>
          </div>
        ) : null}
      </div>

      <div className="mt-5">
        <div className="mb-2 text-xs font-bold uppercase text-slate-500">Planner view</div>
        <div className="flex flex-wrap gap-2">
          {calendarModes.map((mode) => (
            <button
              className={`rounded-md border px-3 py-2 text-sm font-bold ${
                calendarMode === mode ? "border-[#0B1F3A] bg-[#0B1F3A] text-white" : "border-slate-200 bg-white text-slate-700"
              }`}
              key={mode}
              onClick={() => setCalendarMode(mode)}
              type="button"
            >
              {mode} view
            </button>
          ))}
        </div>
      </div>
    </Card>
  );
}

