function AllocationPanel({
  selectedUser,
  suggestions,
  autoAllocated,
  setAutoAllocated
}: {
  selectedUser: (typeof rotaServiceUsers)[number];
  suggestions: (typeof allocationSuggestions)[string];
  autoAllocated: boolean;
  setAutoAllocated: (allocated: boolean) => void;
}) {
  return (
    <Card>
      <SectionTitle
        action={
          <button className="rounded-md bg-[#0B1F3A] px-4 py-2 text-sm font-bold text-white transition hover:bg-slate-800" onClick={() => setAutoAllocated(true)} type="button">
            Auto-allocate
          </button>
        }
        subtitle="Regular carers are checked first, then secondary, preferred, float pool and skilled carers."
        title="Regular carer auto-allocation"
      />
      <div className="rounded-lg bg-slate-50 p-4 ring-1 ring-slate-200">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <div className="text-sm font-bold text-slate-900">{selectedUser.name}</div>
            <div className="text-xs text-slate-500">Primary regular carer checked before fallback ranking.</div>
          </div>
          <PillBadge tone={autoAllocated ? "green" : "amber"}>{autoAllocated ? "Suggested allocation ready" : "Awaiting auto-allocation"}</PillBadge>
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-2">
          {autoAllocationChecks.map(([label, value, tone]) => (
            <div className="flex items-start gap-3 rounded-md bg-white p-3 ring-1 ring-slate-100" key={label}>
              <span className={iconToneClass(tone)}>
                <Icon className="h-4 w-4" name={tone === "amber" ? "alert" : "check"} />
              </span>
              <div>
                <div className="font-semibold text-slate-900">{label}</div>
                <div className="text-xs leading-5 text-slate-500">{value}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="mt-4 space-y-3">
        {suggestions.map((suggestion) => (
          <div className="rounded-lg border border-slate-200 p-4" key={`${suggestion.priority}-${suggestion.carer}`}>
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div>
                <div className="flex flex-wrap items-center gap-2">
                  <PillBadge tone={suggestion.tone}>Step {suggestion.priority}</PillBadge>
                  <span className="text-sm font-bold text-slate-900">{suggestion.source}</span>
                </div>
                <div className="mt-2 text-base font-black text-slate-900">{suggestion.carer}</div>
                <div className="text-sm text-slate-500">{suggestion.role}</div>
              </div>
              <PillBadge tone={suggestion.priority === "1" ? "green" : suggestion.tone}>{suggestion.fit}</PillBadge>
            </div>
            <div className="mt-3 flex flex-wrap gap-2">
              {suggestion.checks.map((check) => (
                <PillBadge key={check} tone="slate">
                  {check}
                </PillBadge>
              ))}
            </div>
            {suggestion.warning ? <div className="mt-3 rounded-md bg-amber-50 p-2 text-xs font-semibold text-amber-800 ring-1 ring-amber-200">{suggestion.warning}</div> : null}
          </div>
        ))}
      </div>
    </Card>
  );
}

function ManualOverridePanel({
  manualReason,
  setManualReason,
  manualOverrideSaved,
  setManualOverrideSaved
}: {
  manualReason: string;
  setManualReason: (reason: string) => void;
  manualOverrideSaved: boolean;
  setManualOverrideSaved: (saved: boolean) => void;
}) {
  return (
    <Card>
      <SectionTitle subtitle="Manual allocations require a reason for audit and manager review." title="Manual allocation with reason" />
      <div className="space-y-4">
        <label className="block">
          <span className="text-xs font-bold uppercase text-slate-500">Select carer</span>
          <select className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-semibold">
            <option>Demo Carer F</option>
            <option>Demo Float Worker A</option>
            <option>Demo Outreach Worker D</option>
          </select>
        </label>
        <label className="block">
          <span className="text-xs font-bold uppercase text-slate-500">Override reason</span>
          <textarea
            className="mt-2 min-h-28 w-full rounded-md border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-400"
            onChange={(event) => {
              setManualReason(event.target.value);
              setManualOverrideSaved(false);
            }}
            value={manualReason}
          />
        </label>
        <button className="w-full rounded-md bg-teal-600 px-4 py-2 text-sm font-bold text-white transition hover:bg-teal-700" onClick={() => setManualOverrideSaved(true)} type="button">
          Save manual override
        </button>
        {manualOverrideSaved ? <div className="rounded-md bg-emerald-50 p-3 text-sm font-semibold text-emerald-800 ring-1 ring-emerald-200">Manual override reason saved to rota audit log.</div> : null}
      </div>

      <div className="mt-5 rounded-lg bg-rose-50 p-4 ring-1 ring-rose-100">
        <div className="flex items-center gap-2 font-bold text-rose-800">
          <Icon className="h-5 w-5" name="alert" />
          Conflict and skills warnings
        </div>
        <ul className="mt-3 space-y-2 text-sm text-rose-800">
          <li>Primary regular carer has an existing rota conflict at 21:00.</li>
          <li>Medication competency is mandatory for lunch and tea calls.</li>
          <li>Double-up visits cannot be dispatched with one worker missing.</li>
        </ul>
      </div>
    </Card>
  );
}

function CalendarPanel({ calendarMode, dispatchSent, setDispatchSent }: { calendarMode: CalendarMode; dispatchSent: boolean; setDispatchSent: (sent: boolean) => void }) {
  const dayVisits = calendarMode === "Day" ? rotaVisits.slice(0, 2) : rotaVisits;

  return (
    <Card>
      <SectionTitle
        action={
          <button className="inline-flex items-center gap-2 rounded-md bg-blue-600 px-4 py-2 text-sm font-bold text-white transition hover:bg-blue-700" onClick={() => setDispatchSent(true)} type="button">
            <Icon className="h-4 w-4" name="message" />
            Dispatch message
          </button>
        }
        subtitle={`${calendarMode} view with allocated, unallocated and warning states.`}
        title="Calendar / day / week view"
      />
      {dispatchSent ? <div className="mb-4 rounded-md bg-blue-50 p-3 text-sm font-semibold text-blue-800 ring-1 ring-blue-200">Demo dispatch message queued for allocated carers.</div> : null}
      <div className="overflow-x-auto">
        <div className={calendarMode === "Calendar" ? "grid min-w-[860px] grid-cols-7 gap-3" : "grid min-w-[760px] gap-3"}>
          {dayVisits.map((visit) => (
            <div className="rounded-lg border border-slate-200 bg-white p-4 shadow-sm" key={visit.id}>
              <div className="flex items-start justify-between gap-3">
                <div>
                  <div className="text-xs font-bold uppercase text-slate-500">
                    {visit.day} {visit.date} | {visit.time}
                  </div>
                  <div className="mt-1 font-black text-slate-900">{visit.serviceUser}</div>
                  <div className="text-sm text-slate-500">
                    {visit.serviceType} | {visit.duration}
                  </div>
                </div>
                <PillBadge tone={visit.status === "Allocated" ? "green" : visit.status === "Unallocated" ? "red" : "amber"}>{visit.status}</PillBadge>
              </div>
              <div className="mt-3 flex flex-wrap gap-2">
                {visit.carers.map((carer) => (
                  <PillBadge key={`${visit.id}-${carer}`} tone={carer === "Unallocated" ? "red" : "teal"}>
                    {carer}
                  </PillBadge>
                ))}
              </div>
              <div className="mt-3 space-y-2">
                {visit.warnings.map((warning) => (
                  <div className="rounded-md bg-slate-50 p-2 text-xs font-semibold text-slate-600" key={warning}>
                    {warning}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </Card>
  );
}

