function MedicationDatabasePage() {
  const [searchTerm, setSearchTerm] = useState("Demo");
  const [selectedCode, setSelectedCode] = useState(medicationDatabaseRecords[0].code);
  const [importRun, setImportRun] = useState(false);
  const [manualSaved, setManualSaved] = useState(false);
  const filteredRecords = medicationDatabaseRecords.filter((record) => `${record.code} ${record.name} ${record.category} ${record.source}`.toLowerCase().includes(searchTerm.toLowerCase()));
  const selectedRecord = medicationDatabaseRecords.find((record) => record.code === selectedCode) ?? medicationDatabaseRecords[0];

  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle
          subtitle="Authorised reference/search module for NHS Dictionary of Medicines and Devices (dm+d) demo data and local manual entries."
          title="Medication Database"
        />
        <div className="rounded-lg bg-amber-50 p-4 text-sm font-semibold leading-6 text-amber-900 ring-1 ring-amber-200">{medicationSafetyWarning}</div>
        <div className="mt-4 grid gap-3 md:grid-cols-4">
          <RotaStat label="Demo records" tone="teal" value={String(medicationDatabaseRecords.length)} />
          <RotaStat label="Current release" tone="green" value="2026-05" />
          <RotaStat label="Manual entries" tone="amber" value="1" />
          <RotaStat label="Review flags" tone="red" value="2" />
        </div>
      </Card>

      <Card>
        <SectionTitle subtitle="Search by demo dm+d identifier, medicine/device name, category or source." title="Medication database search" />
        <div className="grid gap-4 lg:grid-cols-[0.7fr_1.3fr]">
          <div className="space-y-4">
            <label className="block">
              <span className="text-xs font-bold uppercase text-slate-500">Search dm+d medication database</span>
              <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm" onChange={(event) => setSearchTerm(event.target.value)} value={searchTerm} />
            </label>
            <FilterSelect label="Select medicine/product" onChange={setSelectedCode} options={filteredRecords.map((record) => record.code)} value={selectedCode} />
            <div className="rounded-md bg-slate-50 p-4 ring-1 ring-slate-100">
              <div className="font-bold text-slate-900">{selectedRecord.name}</div>
              <div className="mt-2 flex flex-wrap gap-2">
                <PillBadge tone={selectedRecord.source === "Local Manual Entry" ? "amber" : "blue"}>{selectedRecord.source}</PillBadge>
                <PillBadge tone={selectedRecord.status === "Active" ? "green" : "slate"}>{selectedRecord.status}</PillBadge>
                <PillBadge tone="teal">{selectedRecord.category}</PillBadge>
              </div>
              <p className="mt-3 text-sm leading-6 text-slate-600">Selection fills reference fields only. Dose, timing and care instructions must be entered from authorised medication documentation.</p>
            </div>
          </div>
          <MedicationDatabaseTable records={filteredRecords} setSelectedCode={setSelectedCode} />
        </div>
      </Card>

      <MedicationDatabaseImportPanel importRun={importRun} setImportRun={setImportRun} />
      <MedicationProfileSearchPanel contextTitle="Medication search in service user profile" selectedRecord={selectedRecord} />
      <ManualMedicationEntryPanel manualSaved={manualSaved} setManualSaved={setManualSaved} />
      <MedicationGovernanceAuditPanel />
    </div>
  );
}

function MedicationDatabaseTable({ records, setSelectedCode }: { records: typeof medicationDatabaseRecords; setSelectedCode: (code: string) => void }) {
  return (
    <div className="overflow-x-auto rounded-lg border border-slate-200">
      <table className="w-full min-w-[1450px] text-left text-sm">
        <thead className="bg-slate-50 text-xs uppercase text-slate-500">
          <tr>
            {["dm+d code / identifier", "Medicine/device name", "Product type/category", "Strength", "Form", "Route", "Pack information", "BNF code", "Status", "Source", "dm+d release", "Last imported", "Action"].map((heading) => (
              <th className="p-3" key={heading}>
                {heading}
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
          {records.map((record) => (
            <tr className="bg-white" key={record.code}>
              {[record.code, record.name, record.category, record.strength, record.form, record.route, record.pack, record.bnf].map((value, index) => (
                <td className={`p-3 ${index === 1 ? "font-bold text-slate-900" : "text-slate-700"}`} key={`${record.code}-${index}`}>
                  {value}
                </td>
              ))}
              <td className="p-3">
                <PillBadge tone={record.status === "Active" ? "green" : "slate"}>{record.status}</PillBadge>
              </td>
              <td className="p-3">
                <PillBadge tone={record.source === "Local Manual Entry" ? "amber" : "blue"}>{record.source}</PillBadge>
              </td>
              <td className="p-3">{record.release}</td>
              <td className="p-3">{record.imported}</td>
              <td className="p-3">
                <button className="rounded-md bg-[#0B1F3A] px-3 py-2 text-xs font-bold text-white" onClick={() => setSelectedCode(record.code)} type="button">
                  Select
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

