function marStatusLabel(status: MarAdministrationStatus) {
  if (status === "taken") return "Taken";
  if (status === "not-given") return "Not given";
  if (status === "not-applicable") return "Not applicable";
  return "Not scheduled";
}

function MarStatusDot({ status }: { status: MarAdministrationStatus }) {
  const classes: Record<MarAdministrationStatus, string> = {
    taken: "border-emerald-500 bg-white",
    "not-given": "border-rose-500 bg-rose-50",
    "not-applicable": "border-slate-300 bg-slate-100",
    "not-scheduled": "border-slate-300 bg-white"
  };
  return (
    <span aria-label={marStatusLabel(status)} className={`inline-flex h-3.5 w-3.5 items-center justify-center rounded-full border-2 ${classes[status]}`}>
      {status === "not-given" ? <span className="h-1.5 w-1.5 rounded-full bg-rose-500" /> : null}
      {status === "not-applicable" ? <span className="h-1.5 w-1.5 rounded-full bg-slate-400" /> : null}
      {status === "not-scheduled" ? <span className="h-px w-2 bg-slate-400" /> : null}
    </span>
  );
}

function MarLegend() {
  return (
    <div className="flex flex-wrap items-center gap-4 text-xs font-semibold text-slate-600">
      {(["taken", "not-given", "not-applicable", "not-scheduled"] as MarAdministrationStatus[]).map((status) => (
        <span className="inline-flex items-center gap-2" key={status}>
          <MarStatusDot status={status} />
          {marStatusLabel(status)}
        </span>
      ))}
    </div>
  );
}

