function controlledMedicationBalance(records: DemoMarRecord[]) {
  const latestControlled = records.find((record) => record.medicationType === "Controlled Medication" && typeof record.newStockMl === "number");
  return latestControlled?.newStockMl ?? 100;
}

function MedicationMarTransactionPanel({
  mode,
  records,
  onRecord
}: {
  mode: MedicationScheduleType;
  records: DemoMarRecord[];
  onRecord: (outcome: DemoMarOutcome, reason: string, notes: string, witnessNameOrInitials?: string) => void;
}) {
  const controlled = mode === "Controlled";
  const [reason, setReason] = useState(controlled ? "Administered as prescribed" : "Medication support completed");
  const [notes, setNotes] = useState(controlled ? "TEST CONTROLLED MEDICATION ONLY: Dummy controlled medication administered for system testing." : "Medication recorded on MAR in demo mode.");
  const [witness, setWitness] = useState("HA");
  const balance = controlledMedicationBalance(records);
  const scopedRecords = records.filter((record) => controlled ? record.medicationType === "Controlled Medication" : record.medicationType === "Normal Medication");

  return (
    <Card className={controlled ? "border-l-4 border-l-purple-500" : "border-l-4 border-l-blue-500"}>
      <SectionTitle
        action={<PillBadge tone={controlled ? "purple" : "blue"}>{controlled ? "Controlled drug MAR" : "Normal MAR"}</PillBadge>}
        subtitle={controlled ? "Record controlled medication with witness/sign-off and stock balance history." : "Record normal medication outcomes with reason, notes, staff, date/time and audit trail."}
        title={controlled ? "Controlled Medication Administration" : "Normal Medication Administration"}
      />
      <div className="grid gap-3 md:grid-cols-3">
        <ProfileMini label="Service user" value="Mary Johnson" />
        <ProfileMini label="Medication" value={controlled ? "Morphine Sulphate Oral Solution 10mg/5ml - TEST ONLY" : "Paracetamol 500mg"} />
        <ProfileMini label="Dose / route" value={controlled ? "2.5ml / Oral" : "Two tablets / Oral"} />
        <ProfileMini label="Frequency" value={controlled ? "As prescribed / PRN test" : "Morning and evening"} />
        <ProfileMini label="Staff name" value={controlled ? "Sarah Williams" : "Sarah Williams"} />
        <ProfileMini label="Audit trail" value="Every outcome saved locally for UAT" />
        {controlled ? <ProfileMini label="Opening stock" value="100ml" /> : null}
        {controlled ? <ProfileMini label="Current stock balance" value={`${balance}ml`} /> : null}
        {controlled ? <ProfileMini label="Witness required" value="Yes" /> : null}
      </div>
      <div className="mt-4 grid gap-3 md:grid-cols-3">
        <label className="block">
          <span className="text-xs font-bold uppercase text-slate-500">Reason</span>
          <select className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-semibold" onChange={(event) => setReason(event.target.value)} value={reason}>
            {["Administered as prescribed", "Medication support completed", "Refused by service user", "Missed / not given - service user unavailable", "Missed / not given - medication unavailable", "Clinical advice / manager review required"].map((item) => <option key={item}>{item}</option>)}
          </select>
        </label>
        {controlled ? (
          <label className="block">
            <span className="text-xs font-bold uppercase text-slate-500">Witness name or initials</span>
            <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm font-semibold" onChange={(event) => setWitness(event.target.value)} value={witness} />
          </label>
        ) : null}
        <label className="block md:col-span-2">
          <span className="text-xs font-bold uppercase text-slate-500">Notes</span>
          <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm font-semibold" onChange={(event) => setNotes(event.target.value)} value={notes} />
        </label>
      </div>
      <div className="mt-4 flex flex-wrap gap-2">
        <button className="rounded-md bg-emerald-600 px-4 py-2 text-sm font-black text-white" onClick={() => onRecord("Given", reason, notes, witness)} type="button">
          {controlled ? "Record Morphine Given" : "Record Paracetamol Given"}
        </button>
        <button className="rounded-md bg-amber-500 px-4 py-2 text-sm font-black text-white" onClick={() => onRecord("Refused", "Refused by service user", notes, witness)} type="button">
          {controlled ? "Record Morphine Refused" : "Record Paracetamol Refused"}
        </button>
        <button className="rounded-md bg-rose-600 px-4 py-2 text-sm font-black text-white" onClick={() => onRecord("Missed / Not Given", "Missed / not given - service user unavailable", notes, witness)} type="button">
          {controlled ? "Record Morphine Missed / Not Given" : "Record Paracetamol Missed / Not Given"}
        </button>
      </div>
      <div className="mt-4 overflow-x-auto rounded-lg border border-slate-200">
        <table className="w-full min-w-[980px] text-left text-sm">
          <thead className="bg-slate-50 text-xs uppercase text-slate-500">
            <tr>{["Date/time", "Medication", "Outcome", "Reason", "Notes", "Staff", "Witness", "Opening/previous", "New balance", "Audit trail"].map((heading) => <th className="p-3" key={heading}>{heading}</th>)}</tr>
          </thead>
          <tbody className="divide-y divide-slate-100 bg-white">
            {scopedRecords.length ? scopedRecords.map((record) => (
              <tr key={record.id}>
                <td className="p-3 font-bold text-slate-700">{record.dateTime}</td>
                <td className="p-3 font-bold text-slate-900">{record.medicationName}</td>
                <td className="p-3"><PillBadge tone={record.outcome === "Given" ? "green" : record.outcome === "Refused" ? "amber" : "red"}>{record.outcome}</PillBadge></td>
                <td className="p-3 text-slate-700">{record.reason}</td>
                <td className="p-3 text-slate-700">{record.notes}</td>
                <td className="p-3 text-slate-700">{record.staffName}</td>
                <td className="p-3 text-slate-700">{record.witnessNameOrInitials ?? "Not required"}</td>
                <td className="p-3 text-slate-700">{typeof record.previousStockMl === "number" ? `${record.previousStockMl}ml` : "-"}</td>
                <td className="p-3 text-slate-700">{typeof record.newStockMl === "number" ? `${record.newStockMl}ml` : "-"}</td>
                <td className="p-3 text-slate-700">{record.auditTrail}</td>
              </tr>
            )) : (
              <tr>
                <td className="p-4 text-sm font-bold text-slate-500" colSpan={10}>No {controlled ? "controlled" : "normal"} MAR transactions recorded in this demo session yet.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
      {controlled ? (
        <div className="mt-3 rounded-md bg-purple-50 p-3 text-sm font-bold text-purple-900 ring-1 ring-purple-100">
          Stock balance rule: Given reduces the dummy stock by 2.5ml. Refused or missed/not given records leave stock unchanged and still create an audit entry.
        </div>
      ) : null}
    </Card>
  );
}

function MedicationMarDashboard({ mode = "overview" }: { mode?: MedicationMarDashboardMode }) {
  const demoStore = useCareVerityDemoStore();
  const initialSelected = mode === "controlled" ? "morphine-sulfate" : "paracetamol-500mg";
  const [selectedMedicationId, setSelectedMedicationId] = useState(initialSelected);
  const [searchTerm, setSearchTerm] = useState("");
  const [showActive, setShowActive] = useState(true);
  const [showStopped, setShowStopped] = useState(false);
  const [fullSheet, setFullSheet] = useState<MedicationScheduleType | null>(mode === "normal" ? "Normal" : mode === "controlled" ? "Controlled" : null);

  const visibleSchedules = medicationScheduleRecords.filter((record) => {
    const matchesSearch = `${record.medication} ${record.description} ${record.type}`.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = (record.status === "Active" && showActive) || (record.status === "Stopped" && showStopped);
    const matchesMode = mode === "normal" ? record.type === "Normal" : mode === "controlled" ? record.type === "Controlled" : true;
    return matchesSearch && matchesStatus && matchesMode;
  });
  const selectedMedication = medicationScheduleRecords.find((record) => record.id === selectedMedicationId) ?? visibleSchedules[0] ?? medicationScheduleRecords[0];
  const normalRows = fullSheet === "Normal" ? normalMedicationMarRows : normalMedicationMarRows.slice(0, 6);
  const controlledRows = fullSheet === "Controlled" ? controlledMedicationMarRows : controlledMedicationMarRows.slice(0, 4);
  const normalCount = medicationScheduleRecords.filter((record) => record.type === "Normal").length;
  const controlledCount = medicationScheduleRecords.filter((record) => record.type === "Controlled").length;
  const recordMarOutcome = (recordMode: MedicationScheduleType, outcome: DemoMarOutcome, reason: string, notes: string, witnessNameOrInitials?: string) => {
    const controlled = recordMode === "Controlled";
    const previousStockMl = controlled ? controlledMedicationBalance(demoStore.localMarRecords) : undefined;
    const doseAdministeredMl = controlled ? 2.5 : undefined;
    const newStockMl = controlled && outcome === "Given" && typeof previousStockMl === "number" ? Number((previousStockMl - 2.5).toFixed(1)) : previousStockMl;
    const record: DemoMarRecord = {
      companyId: launchPrimaryCompanyId,
      providerId: launchProviderId,
      locationId: launchLocationId,
      id: `MAR-UAT-${recordMode.toUpperCase()}-${Date.now()}`,
      medicationName: controlled ? "Morphine Sulphate Oral Solution 10mg/5ml - TEST ONLY" : "Paracetamol 500mg",
      medicationType: controlled ? "Controlled Medication" : "Normal Medication",
      serviceUserName: "Mary Johnson",
      dose: controlled ? "2.5ml" : "Two tablets",
      route: "Oral",
      outcome,
      reason,
      notes,
      staffName: "Sarah Williams",
      dateTime: demoDateTimeStamp(),
      auditTrail: controlled ? "Controlled MAR audit: staff sign-off, witness and balance history recorded." : "Normal MAR audit: outcome, reason, note, staff and date/time recorded.",
      controlledDrug: controlled,
      witnessNameOrInitials: controlled ? witnessNameOrInitials || "HA" : undefined,
      staffSignOff: controlled ? "Sarah Williams" : undefined,
      openingStockMl: controlled ? 100 : undefined,
      previousStockMl,
      doseAdministeredMl,
      newStockMl
    };
    demoStore.saveMarRecords([record, ...demoStore.localMarRecords]);
    appendDemoVisitAudit(
      controlled ? "controlled MAR outcome recorded" : "normal MAR outcome recorded",
      controlled ? "controlled_drugs_mar_records" : "normal_mar_records",
      record.id,
      "No MAR outcome",
      JSON.stringify({ medication: record.medicationName, outcome, newStockMl }),
      record.auditTrail,
      record.staffName,
      "Permanent Care Worker"
    );
  };

  return (
    <div className="space-y-6">
      <Card className="bg-gradient-to-r from-blue-50 to-slate-50">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="flex h-14 w-14 items-center justify-center rounded-full bg-blue-700 text-lg font-black text-white">{medicationDashboardClient.initials}</div>
            <div>
              <div className="text-xs font-black uppercase tracking-wide text-blue-700">Medication monitoring UI</div>
              <h1 className="mt-1 text-2xl font-black text-slate-950">Manage {medicationDashboardClient.name}&apos;s medication</h1>
              <p className="mt-1 text-sm font-semibold text-slate-600">View, schedule and monitor medication for safe, effective care.</p>
            </div>
          </div>
          <div className="grid gap-2 text-sm md:grid-cols-3">
            <ProfileMini label="Client ID" value={medicationDashboardClient.clientId} />
            <ProfileMini label="Provider" value={medicationDashboardClient.provider} />
            <ProfileMini label="MAR status" value={`${normalCount} normal / ${controlledCount} controlled`} />
          </div>
        </div>
      </Card>

      <div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_360px]">
        <div className="space-y-6">
          <MedicationSearchBar searchTerm={searchTerm} setSearchTerm={setSearchTerm} />

          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
            <MedicationActionCard action="View schedules" icon="clipboard" subtitle="View and update medication schedules." title="Medication scheduling" tone="teal" />
            <MedicationActionCard action="Go to MAR sheets" icon="shield" subtitle="Access Normal and Controlled Medication MAR sheets." title="Medication monitoring" tone="green" />
            <MedicationActionCard action="Update details" icon="user-check" subtitle="Update allergies, medical notes and medication support needs." title="Personal details" tone="blue" />
            <MedicationActionCard action="Go to help centre" icon="message" subtitle="Medication tools guidance, policy prompts and best practice help." title="Help and support" tone="slate" />
          </div>

          <MedicationSchedulesTable
            records={visibleSchedules}
            selectedMedicationId={selectedMedication.id}
            setSelectedMedicationId={setSelectedMedicationId}
            setShowActive={setShowActive}
            setShowStopped={setShowStopped}
            showActive={showActive}
            showStopped={showStopped}
          />

          <div className="grid gap-4 xl:grid-cols-2">
            {(mode === "overview" || mode === "normal") ? (
              <MedicationActionCard action="Open normal MAR sheet" icon="file-text" subtitle="View and record administration of normal medications." title="Normal Medication MAR Sheet" tone="blue" />
            ) : null}
            {(mode === "overview" || mode === "controlled") ? (
              <MedicationActionCard action="Open controlled MAR sheet" icon="lock" subtitle="View and record administration of controlled medications." title="Controlled Medication MAR Sheet" tone="purple" />
            ) : null}
          </div>

          {(mode === "overview" || mode === "normal") ? (
            <MedicationMarSheetPreview onOpenFull={() => setFullSheet("Normal")} rows={normalRows} subtitle={fullSheet === "Normal" ? "Full normal medication MAR sheet" : "Next 7 days"} title="Normal Medication MAR Sheet Preview" type="Normal" />
          ) : null}
          {(mode === "overview" || mode === "normal") ? (
            <MedicationMarTransactionPanel mode="Normal" onRecord={(outcome, reason, notes) => recordMarOutcome("Normal", outcome, reason, notes)} records={demoStore.localMarRecords} />
          ) : null}
          {(mode === "overview" || mode === "controlled") ? (
            <MedicationMarSheetPreview onOpenFull={() => setFullSheet("Controlled")} rows={controlledRows} subtitle={fullSheet === "Controlled" ? "Full controlled medication MAR sheet" : "Next 7 days"} title="Controlled Medication MAR Sheet Preview" type="Controlled" />
          ) : null}
          {(mode === "overview" || mode === "controlled") ? (
            <MedicationMarTransactionPanel mode="Controlled" onRecord={(outcome, reason, notes, witness) => recordMarOutcome("Controlled", outcome, reason, notes, witness)} records={demoStore.localMarRecords} />
          ) : null}
        </div>

        <MedicationDetailDrawer medication={selectedMedication} onClose={() => setSelectedMedicationId(visibleSchedules[0]?.id ?? medicationScheduleRecords[0].id)} />
      </div>
    </div>
  );
}

