type DemoClientDocumentRecord = {
  id: string;
  companyId: string;
  serviceUserId: string;
  documentCategory: string;
  documentTitle: string;
  documentDescription: string;
  originalFileName: string;
  safeFileName: string;
  fileType: string;
  fileSizeBytes: number;
  storagePath: string;
  version: number;
  status: "Active" | "Archived" | "Deleted";
  restricted: boolean;
  mobileVisible: boolean;
  uploadedBy: string;
  uploadedByRole: string;
  uploadedAt: string;
  replacedDocumentId?: string;
  archiveReason?: string;
  objectUrl?: string;
};

function getClientDocumentExtension(fileName: string) {
  const dotIndex = fileName.lastIndexOf(".");
  return dotIndex >= 0 ? fileName.slice(dotIndex).toLowerCase() : "";
}

function createSafeClientDocumentFileName(fileName: string) {
  return fileName.replace(/[^a-zA-Z0-9._-]/g, "-").replace(/-+/g, "-");
}

function formatClientDocumentSize(bytes: number) {
  if (bytes < 1024 * 1024) return `${Math.max(1, Math.round(bytes / 1024))} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

