function clientSlug(user: ServiceUserRecord) {
  return user.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function clientIdFromPathSegment(segment: string, clientList: ServiceUserRecord[] = rotaServiceUsers) {
  const normalised = segment.split("/")[0].toLowerCase();
  return clientList.find((user) => user.id.toLowerCase() === normalised || clientSlug(user) === normalised)?.id ?? clientList[0]?.id ?? rotaServiceUsers[0].id;
}

function clientInitialTabFromPath(initialClientPath: string): ClientPrivateTab {
  if (initialClientPath.toLowerCase().includes("/journal")) return "Journal / Communication Log";
  if (initialClientPath.toLowerCase().includes("/ai-care-review")) return "AI Care Review & Referral Assistant";
  return "Overview";
}

function clientSummaryRow(user: ServiceUserRecord) {
  const highRisk = user.regularTeam.continuity === "Critical" || user.regularTeam.continuity === "High";
  return {
    user,
    preferredName: user.preferredName ?? user.name.replace("Demo Service User ", "Demo "),
    postcodeArea: user.postcode ? `${user.postcode.split(" ")[0]} area` : user.id === "demo-su-101" ? "UB4 area" : user.id === "demo-su-620" ? "HA4 area" : "Demo locality",
    packageType: user.package.includes("double") ? "Double-up" : user.package.includes("outreach") ? "Outreach only" : "Single carer",
    fundingSource: user.funding,
    riskLevel: user.riskLevel ?? (highRisk ? "High" : "Medium"),
    continuity: user.regularTeam.continuity,
    reviewStatus: user.id === "demo-su-318" ? "Due soon" : "Current",
    documentStatus: user.id === "demo-su-620" ? "Manager review" : "Complete",
    serviceType: user.package.includes("outreach") ? "Outreach" : "Personal Care",
    location: user.id === "demo-su-204" ? "Demo Central Locality" : "Demo North Locality",
    status: "Active"
  };
}

export function ServiceUsersPage({ initialClientPath = "" }: { initialClientPath?: string }) {
  const demoStore = useCareVerityDemoStore();
  const allClients = useMemo(() => mergeByKey([...rotaServiceUsers], demoStore.localClients, (client) => client.id), [demoStore.localClients]);
  const initialMode: ClientPageMode = initialClientPath === "existing" ? "existing" : initialClientPath === "new" ? "new" : initialClientPath ? "profile" : "landing";
  const [mode, setMode] = useState<ClientPageMode>(initialMode);
  const [selectedUserId, setSelectedUserId] = useState(initialClientPath && !["existing", "new"].includes(initialClientPath) ? clientIdFromPathSegment(initialClientPath, allClients) : allClients[0].id);
  const [activeTab, setActiveTab] = useState<ClientPrivateTab>(clientInitialTabFromPath(initialClientPath));
  const [existingSearch, setExistingSearch] = useState("");
  const [existingFunding, setExistingFunding] = useState("All");
  const [existingRisk, setExistingRisk] = useState("All");
  const [existingReview, setExistingReview] = useState("All");
  const [addStep, setAddStep] = useState(addServiceUserSteps[0].title);
  const [createdClient, setCreatedClient] = useState(false);
  const [savedDraft, setSavedDraft] = useState(false);

  useEffect(() => {
    const path = window.location.pathname;
    if (path.endsWith("/clients/existing")) {
      setMode("existing");
      return;
    }
    if (path.endsWith("/clients/new")) {
      setMode("new");
      return;
    }
    if (path.includes("/clients/") && !path.endsWith("/clients")) {
      const segment = decodeURIComponent(path.split("/clients/")[1]?.split("/")[0] ?? "");
      setSelectedUserId(clientIdFromPathSegment(segment, allClients));
      if (path.includes("/journal")) setActiveTab("Journal / Communication Log");
      setMode("profile");
      return;
    }
    setMode("landing");
  }, [allClients]);

  const selectedUser = allClients.find((user) => user.id === selectedUserId) ?? allClients[0];
  const summaries = allClients.map(clientSummaryRow);
  const filteredSummaries = summaries.filter((row) => {
    const query = existingSearch.trim().toLowerCase();
    const matchesSearch = !query || [row.user.name, row.preferredName, row.packageType, row.fundingSource, row.postcodeArea, row.location].join(" ").toLowerCase().includes(query);
    const matchesFunding = existingFunding === "All" || row.fundingSource.toLowerCase().includes(existingFunding.toLowerCase().replace(" / icb", ""));
    const matchesRisk = existingRisk === "All" || row.riskLevel === existingRisk;
    const matchesReview = existingReview === "All" || row.reviewStatus === existingReview;
    return matchesSearch && matchesFunding && matchesRisk && matchesReview;
  });

  const openLanding = () => {
    setMode("landing");
    setCreatedClient(false);
    if (typeof window !== "undefined") window.history.pushState(null, "", "/careverity-ecm/clients");
  };

  const openExisting = () => {
    setMode("existing");
    setCreatedClient(false);
    if (typeof window !== "undefined") window.history.pushState(null, "", "/careverity-ecm/clients/existing");
  };

  const openNew = () => {
    setMode("new");
    setSavedDraft(false);
    setCreatedClient(false);
    if (typeof window !== "undefined") window.history.pushState(null, "", "/careverity-ecm/clients/new");
  };

  const openClientFile = (user: (typeof rotaServiceUsers)[number]) => {
    setSelectedUserId(user.id);
    setActiveTab("Overview");
    setMode("profile");
    setCreatedClient(false);
    if (typeof window !== "undefined") window.history.pushState(null, "", `/careverity-ecm/clients/${clientSlug(user)}`);
  };

  const createDemoClient = () => {
    const client = demoStore.createTestServiceUser();
    demoStore.createTestCallPackage();
    setSelectedUserId(client.id);
    setActiveTab("Overview");
    setCreatedClient(true);
    setMode("profile");
    if (typeof window !== "undefined") window.history.pushState(null, "", "/careverity-ecm/clients/demo-service-user-101");
  };

  const createClientFromForm = (client: ServiceUserRecord) => {
    demoStore.createServiceUser(client);
    setSelectedUserId(client.id);
    setActiveTab("Overview");
    setCreatedClient(true);
    setMode("profile");
    if (typeof window !== "undefined") window.history.pushState(null, "", `/careverity-ecm/clients/${clientSlug(client)}`);
  };

  const updateSelectedClientPhoto = (client: ServiceUserRecord, avatarDataUrl?: string) => {
    const updated = demoStore.updateServiceUserAvatar(client, avatarDataUrl);
    setSelectedUserId(updated.id);
    setCreatedClient(false);
  };

  if (mode === "existing") {
    return (
      <ExistingServiceUsersPage
        existingFunding={existingFunding}
        existingReview={existingReview}
        existingRisk={existingRisk}
        filteredSummaries={filteredSummaries}
        onBack={openLanding}
        onOpenClientFile={openClientFile}
        search={existingSearch}
        setExistingFunding={setExistingFunding}
        setExistingReview={setExistingReview}
        setExistingRisk={setExistingRisk}
        setSearch={setExistingSearch}
      />
    );
  }

  if (mode === "new") {
    return <AddNewServiceUserPage activeStep={addStep} createdDraft={savedDraft} onCancel={openLanding} onCreateClient={createClientFromForm} onCreateDemoClient={createDemoClient} onSaveDraft={() => setSavedDraft(true)} setActiveStep={setAddStep} />;
  }

  if (mode === "profile") {
    return <ClientFilePage activeTab={activeTab} createdClient={createdClient} onBack={openExisting} onSetTab={setActiveTab} onUpdatePhoto={updateSelectedClientPhoto} selectedUser={selectedUser} />;
  }

  return <ServiceUsersLandingPage onCreateDemoClient={createDemoClient} onExisting={openExisting} onNew={openNew} />;
}

function ServiceUsersLandingPage({ onCreateDemoClient, onExisting, onNew }: { onCreateDemoClient: () => void; onExisting: () => void; onNew: () => void }) {
  const demoStore = useCareVerityDemoStore();
  const demoActions: Record<string, () => void> = {
    "Create Demo Service User": onCreateDemoClient,
    "Create Demo Staff": () => demoStore.createTestStaff(),
    "Create Demo Call Package": () => demoStore.createTestCallPackage(),
    "Allocate Demo Staff for 2 Weeks": () => demoStore.createAllocation({ id: `alloc-demo-2w-${Date.now()}`, clientId: "demo-su-101", clientName: "Demo Service User 101", callTypes: ["Morning Call", "Lunch Call", "Tea Call"], carer: "Demo Care Worker A", dateRange: "Two weeks", allocationType: "Permanent regular carer", visitsCreated: 42, published: false }),
    "Allocate Demo Staff for 1 Month": () => demoStore.createAllocation({ id: `alloc-demo-1m-${Date.now()}`, clientId: "demo-su-101", clientName: "Demo Service User 101", callTypes: ["Morning Call", "Lunch Call", "Tea Call"], carer: "Demo Care Worker A", dateRange: "One month", allocationType: "Permanent regular carer", visitsCreated: 93, published: true }),
    "View in Rota": () => { window.location.href = "/careverity-ecm/rota?client=demo-su-101&calls=Morning Call,Lunch Call,Tea Call&range=Two weeks"; },
    "View in Live ECM": () => { window.location.href = "/careverity-ecm/live-ecm"; },
    "Reset Demo Data": demoStore.resetDemoData
  };
  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle subtitle="Add, search and manage individual service user records, care plans, risk assessments, call packages, documents and communication records." title="Service Users / Client Files" />
        <div className="grid gap-4 md:grid-cols-2">
          <button className="rounded-lg border border-teal-200 bg-teal-50 p-6 text-left transition hover:bg-teal-100" onClick={onNew} type="button">
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-teal-600 text-white"><Icon className="h-6 w-6" name="plus" /></div>
            <div className="mt-4 text-2xl font-black text-slate-900">Add New Service User</div>
            <p className="mt-2 text-sm leading-6 text-slate-600">Open the guided form with dropdowns, checkboxes, templates, call package setup and document placeholders.</p>
          </button>
          <button className="rounded-lg border border-blue-200 bg-blue-50 p-6 text-left transition hover:bg-blue-100" onClick={onExisting} type="button">
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-blue-600 text-white"><Icon className="h-6 w-6" name="users" /></div>
            <div className="mt-4 text-2xl font-black text-slate-900">Existing Service Users</div>
            <p className="mt-2 text-sm leading-6 text-slate-600">Search and select one service user, then open their private client file with tabbed sections.</p>
          </button>
        </div>
      </Card>

      <div className="grid gap-3 md:grid-cols-3 xl:grid-cols-6">
        <RotaStat label="Active service users" tone="green" value="42" />
        <RotaStat label="High-risk service users" tone="red" value="8" />
        <RotaStat label="Reviews due" tone="amber" value="6" />
        <RotaStat label="Documents due" tone="amber" value="11" />
        <RotaStat label="Funding types" tone="blue" value="5" />
        <RotaStat label="Unallocated packages" tone="red" value="4" />
      </div>

      <Card>
        <SectionTitle subtitle="Use fake demo data only. This lets you test client creation, call packages, rota allocation, Live ECM and reset behaviour." title="Demo test flow" />
        <div className="grid gap-3 md:grid-cols-4">
          {["Create Demo Service User", "Create Demo Staff", "Create Demo Call Package", "Allocate Demo Staff for 2 Weeks", "Allocate Demo Staff for 1 Month", "View in Rota", "View in Live ECM", "Reset Demo Data"].map((action, index) => (
            <button className={`rounded-md px-3 py-3 text-sm font-bold ${index === 0 ? "bg-teal-600 text-white" : "bg-slate-50 text-slate-700 ring-1 ring-slate-200"}`} key={action} onClick={demoActions[action]} type="button">
              {action}
            </button>
          ))}
        </div>
      </Card>
    </div>
  );
}

function ExistingServiceUsersPage({
  existingFunding,
  existingReview,
  existingRisk,
  filteredSummaries,
  onBack,
  onOpenClientFile,
  search,
  setExistingFunding,
  setExistingReview,
  setExistingRisk,
  setSearch
}: {
  existingFunding: string;
  existingReview: string;
  existingRisk: string;
  filteredSummaries: ReturnType<typeof clientSummaryRow>[];
  onBack: () => void;
  onOpenClientFile: (user: ServiceUserRecord) => void;
  search: string;
  setExistingFunding: (value: string) => void;
  setExistingReview: (value: string) => void;
  setExistingRisk: (value: string) => void;
  setSearch: (value: string) => void;
}) {
  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle action={<button className="rounded-md border border-slate-200 px-4 py-2 text-sm font-bold text-slate-700" onClick={onBack} type="button">Back</button>} subtitle="Select one service user to open their private client file." title="Existing Service Users" />
        <div className="grid gap-3 lg:grid-cols-[1fr_repeat(3,220px)]">
          <label>
            <span className="text-xs font-bold uppercase text-slate-500">Search</span>
            <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm" onChange={(event) => setSearch(event.target.value)} placeholder="Search by name, area, package or funding" value={search} />
          </label>
          <FilterSelect label="Funding source" onChange={setExistingFunding} options={clientExistingFilters.funding} value={existingFunding} />
          <FilterSelect label="Risk level" onChange={setExistingRisk} options={clientExistingFilters.risk} value={existingRisk} />
          <FilterSelect label="Review due" onChange={setExistingReview} options={clientExistingFilters.review} value={existingReview} />
        </div>
        <div className="mt-3 grid gap-3 md:grid-cols-4">
          <FilterSelect label="Status" onChange={() => undefined} options={clientExistingFilters.status} value="All" />
          <FilterSelect label="Service type" onChange={() => undefined} options={clientExistingFilters.service} value="All" />
          <FilterSelect label="Area/location" onChange={() => undefined} options={clientExistingFilters.area} value="All" />
          <FilterSelect label="Document due" onChange={() => undefined} options={clientExistingFilters.document} value="All" />
        </div>
      </Card>
      <Card>
        <SectionTitle subtitle="Summary only. Sensitive records stay inside the selected client file." title="Client list" />
        <div className="overflow-x-auto rounded-lg border border-slate-200">
          <table className="w-full min-w-[1120px] text-left text-sm">
            <thead className="bg-slate-50 text-xs uppercase text-slate-500">
              <tr>{["Service user", "Preferred name", "Postcode/area", "Package type", "Funding", "Risk", "Continuity", "Review", "Documents", "Action"].map((heading) => <th className="p-3" key={heading}>{heading}</th>)}</tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredSummaries.map((row) => (
                <tr className="bg-white" key={row.user.id}>
                  <td className="p-3">
                    <div className="flex items-center gap-3">
                      {row.user.avatarDataUrl ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img alt={`${row.user.name} avatar`} className="h-10 w-10 rounded-full object-cover ring-1 ring-blue-200" src={row.user.avatarDataUrl} />
                      ) : (
                        <div className="grid h-10 w-10 place-items-center rounded-full bg-blue-100 font-black text-blue-800">{initialsFromName(row.user.name)}</div>
                      )}
                      <div><div className="font-black text-slate-900">{row.user.name}</div><div className="text-xs text-slate-500">{row.status}</div></div>
                    </div>
                  </td>
                  <td className="p-3 text-slate-700">{row.preferredName}</td>
                  <td className="p-3 text-slate-700">{row.postcodeArea}</td>
                  <td className="p-3 text-slate-700">{row.packageType}</td>
                  <td className="p-3"><PillBadge tone={row.fundingSource.includes("NHS") ? "blue" : "slate"}>{row.fundingSource}</PillBadge></td>
                  <td className="p-3"><PillBadge tone={row.riskLevel === "High" ? "red" : "amber"}>{row.riskLevel}</PillBadge></td>
                  <td className="p-3 text-slate-700">{row.continuity}</td>
                  <td className="p-3"><PillBadge tone={documentStatusTone(row.reviewStatus)}>{row.reviewStatus}</PillBadge></td>
                  <td className="p-3"><PillBadge tone={documentStatusTone(row.documentStatus)}>{row.documentStatus}</PillBadge></td>
                  <td className="p-3"><button className="rounded-md bg-[#0B1F3A] px-3 py-2 text-xs font-bold text-white" onClick={() => onOpenClientFile(row.user)} type="button">Open Client File</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
}

function AddNewServiceUserPage({
  activeStep,
  createdDraft,
  onCancel,
  onCreateClient,
  onCreateDemoClient,
  onSaveDraft,
  setActiveStep
}: {
  activeStep: string;
  createdDraft: boolean;
  onCancel: () => void;
  onCreateClient: (client: ServiceUserRecord) => void;
  onCreateDemoClient: () => void;
  onSaveDraft: () => void;
  setActiveStep: (step: string) => void;
}) {
  const formRef = useRef<HTMLFormElement>(null);
  const [previewImage, setPreviewImage] = useState("");
  const [callTemplates, setCallTemplates] = useState<string[]>([]);
  const step = addServiceUserSteps.find((item) => item.title === activeStep) ?? addServiceUserSteps[0];
  const addTemplateCall = (label: string) => {
    const callType = label === "Save Call Package" ? "Call package saved" : label.replace(/^Add /, "");
    setCallTemplates((current) => (current.includes(callType) ? current : [...current, callType]));
  };
  const createFromForm = () => {
    const formData = formRef.current ? new FormData(formRef.current) : new FormData();
    const firstName = String(formData.get("firstName") || "Demo");
    const lastName = String(formData.get("lastName") || "Service User 101");
    const riskLevel = String(formData.get("riskLevel") || "High") as ServiceUserRecord["riskLevel"];
    const packageType = String(formData.get("packageType") || "Personal care double-up");
    onCreateClient({
      id: `demo-client-${Date.now()}`,
      name: `${firstName} ${lastName}`.trim(),
      preferredName: String(formData.get("preferredName") || "Demo User"),
      package: packageType,
      funding: String(formData.get("fundingSource") || "Local Authority"),
      avatarDataUrl: previewImage || undefined,
      address: String(formData.get("address") || "Demo House, 1 Care Street, Hayes"),
      postcode: String(formData.get("postcode") || "UB4 0SD"),
      riskLevel,
      regularTeam: {
        primary: "Not assigned",
        additional: "Not assigned",
        outreach: "Not assigned",
        additionalOutreach: "Not assigned",
        preferred: [],
        excluded: [],
        skills: ["Medication support", "Moving and handling", "Dementia awareness"],
        preference: "Created from Add New Service User form. Restricted fields are role controlled.",
        usualTimes: ["08:00 Morning Call", "12:30 Lunch Call", "17:00 Tea Call", "21:00 Bed Call"],
        duration: "30 to 45 minutes",
        doubleUp: packageType.toLowerCase().includes("double") ? "Double-up required" : "Single carer",
        continuity: riskLevel === "High" || riskLevel === "Critical" ? "High" : "Medium"
      }
    });
  };
  return (
    <form ref={formRef} className="space-y-6">
      <Card>
        <SectionTitle action={<button className="rounded-md border border-slate-200 px-4 py-2 text-sm font-bold text-slate-700" onClick={onCancel} type="button">Cancel</button>} subtitle="Use dropdowns, checkboxes and templates to reduce manual typing." title="Add New Service User" />
        <div className="flex flex-wrap gap-2">
          {addServiceUserSteps.map((item) => (
            <button className={`rounded-md px-3 py-2 text-xs font-bold ${activeStep === item.title ? "bg-[#0B1F3A] text-white" : "bg-slate-50 text-slate-700 ring-1 ring-slate-200"}`} key={item.title} onClick={() => setActiveStep(item.title)} type="button">
              {item.title}
            </button>
          ))}
        </div>
        {createdDraft ? <div className="mt-4 rounded-lg bg-teal-50 p-3 text-sm font-bold text-teal-800 ring-1 ring-teal-100">Draft saved for demo service user setup.</div> : null}
      </Card>
      <Card>
        <SectionTitle subtitle="Prototype picture upload stores a local preview only." title="Profile picture" />
        <ProfilePictureEditor
          alt="Uploaded service user preview"
          currentImage={previewImage}
          initials="DU"
          onChange={setPreviewImage}
          onRemove={() => setPreviewImage("")}
          removeLabel="Remove selected picture"
          tone="blue"
          uploadLabel={previewImage ? "Change selected picture" : "Add picture"}
        />
        <p className="mt-3 text-xs font-semibold text-slate-500">You can add, change or remove the photo before creating the service-user file.</p>
      </Card>
      <Card>
        <SectionTitle subtitle={activeStep === "Step 6 — Call Package Setup" ? "Add Morning, Lunch, Tea, Bed, Outreach or custom calls from templates." : "Complete this step, then move to the next guided section."} title={step.title} />
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          {step.fields.map(([label, options]) => {
            const fieldName = label === "First name" ? "firstName" : label === "Last name" ? "lastName" : label === "Preferred name" ? "preferredName" : label === "Address" ? "address" : label === "Postcode" ? "postcode" : label === "Funding source" ? "fundingSource" : label === "Risk level" ? "riskLevel" : label === "Package type" ? "packageType" : label;
            return (
              <label className={label.includes("Medical history") || label.includes("Access instructions") ? "block xl:col-span-2" : "block"} key={label}>
                <span className="text-xs font-bold uppercase text-slate-500">{label}</span>
                {options.length ? (
                  <select className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-semibold" name={fieldName}>
                    {options.map((option) => <option key={option}>{option}</option>)}
                  </select>
                ) : label.toLowerCase().includes("upload") || label.toLowerCase().includes("document") || label.toLowerCase().includes("assessment") ? (
                  <button className="mt-2 w-full rounded-md border border-dashed border-slate-300 bg-slate-50 px-3 py-2 text-left text-sm font-semibold text-slate-600" type="button">Upload placeholder</button>
                ) : (
                  <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm" defaultValue={label === "First name" ? "Demo" : label === "Last name" ? "Service User 101" : label === "Preferred name" ? "Demo User" : label === "Address" ? "Demo House, 1 Care Street, Hayes" : label === "Postcode" ? "UB4 0SD" : ""} name={fieldName} placeholder={label.includes("restricted") || label.includes("NHS") || label.includes("Key safe") ? "Restricted field" : "Enter demo value"} />
                )}
              </label>
            );
          })}
        </div>
        {activeStep === "Step 6 — Call Package Setup" ? (
          <>
            <div className="mt-4 flex flex-wrap gap-2">
              {["Add Morning Call", "Add Lunch Call", "Add Tea Call", "Add Bed Call", "Add Outreach Call", "Add Custom Call", "Save Call Package"].map((button) => (
                <button className="rounded-md bg-teal-600 px-3 py-2 text-xs font-bold text-white" key={button} onClick={() => addTemplateCall(button)} type="button">
                  {button}
                </button>
              ))}
            </div>
            {callTemplates.length ? (
              <div className="mt-4 rounded-lg bg-teal-50 p-3 text-sm font-bold text-teal-800 ring-1 ring-teal-100">
                Prototype call package updated: {callTemplates.join(", ")}
              </div>
            ) : null}
          </>
        ) : null}
      </Card>
      <Card>
        <SectionTitle subtitle="Create the private client file or keep it as a draft." title="Save" />
        <div className="flex flex-wrap gap-3">
          <button className="rounded-md border border-slate-200 px-4 py-2 text-sm font-bold text-slate-700" onClick={onSaveDraft} type="button">Save Draft</button>
          <button className="rounded-md bg-teal-600 px-4 py-2 text-sm font-bold text-white" onClick={createFromForm} type="button">Create Service User File</button>
          <button className="rounded-md bg-blue-600 px-4 py-2 text-sm font-bold text-white" onClick={onCreateDemoClient} type="button">Create Test Service User</button>
          <button className="rounded-md border border-slate-200 px-4 py-2 text-sm font-bold text-slate-700" onClick={onCancel} type="button">Cancel</button>
        </div>
      </Card>
    </form>
  );
}

function ClientFilePage({
  activeTab,
  createdClient,
  onBack,
  onSetTab,
  onUpdatePhoto,
  selectedUser
}: {
  activeTab: ClientPrivateTab;
  createdClient: boolean;
  onBack: () => void;
  onSetTab: (tab: ClientPrivateTab) => void;
  onUpdatePhoto: (client: ServiceUserRecord, avatarDataUrl?: string) => void;
  selectedUser: ServiceUserRecord;
}) {
  const summary = clientSummaryRow(selectedUser);
  const [clientDetails, setClientDetails] = useState<ClientEditableDetails>(() => clientEditableDetailsFromUser(selectedUser));
  const [clientDraft, setClientDraft] = useState<ClientEditableDetails>(() => clientEditableDetailsFromUser(selectedUser));
  const [editingTab, setEditingTab] = useState<ClientPrivateTab | null>(null);
  const [lastUpdatedBy, setLastUpdatedBy] = useState("Demo Care Coordinator");
  const [lastUpdatedAt, setLastUpdatedAt] = useState("16 May 2026 09:05");
  const [clientAuditEntries, setClientAuditEntries] = useState<EditableAuditEntry[]>([]);
  const currentDemoUser = useDemoCurrentUser("Registered Manager");
  const adminCanOpenBehaviourModule = /System Owner|Registered Manager|Manager|Care Coordinator|Quality|Compliance|Admin/i.test(currentDemoUser.role);
  const showBehaviourTab = behaviourSupportEnabledFor(selectedUser) || adminCanOpenBehaviourModule;
  const visibleClientTabs = clientPrivateTabs.filter((tab) => tab !== "Behaviour Monitoring" || showBehaviourTab);

  const startEditing = (tab: ClientPrivateTab) => {
    if (tab === "Personal Details") setClientDraft(clientDetails);
    setEditingTab(tab);
  };

  const cancelEditing = () => {
    setClientDraft(clientDetails);
    setEditingTab(null);
  };

  const saveEditing = (tab: ClientPrivateTab) => {
    const before = tab === "Personal Details" ? clientDetails : { section: tab, status: "Opened for controlled edit" };
    const after = tab === "Personal Details" ? clientDraft : { section: tab, status: "Section save confirmed" };
    if (tab === "Personal Details") setClientDetails(clientDraft);
    const now = new Date().toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" });
    setLastUpdatedBy("Demo Care Coordinator");
    setLastUpdatedAt(now);
    setClientAuditEntries((rows) => [makeEditableAudit("Service user", selectedUser.name, tab, JSON.stringify(before), JSON.stringify(after), "Client file section updated from editable service user profile."), ...rows]);
    setEditingTab(null);
  };

  const updateProfilePicture = (avatarDataUrl?: string) => {
    const oldValue = selectedUser.avatarDataUrl ? "Photo uploaded" : "No photo";
    const newValue = avatarDataUrl ? "Photo uploaded" : "No photo";
    onUpdatePhoto(selectedUser, avatarDataUrl);
    const now = new Date().toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" });
    setLastUpdatedBy("Demo Care Coordinator");
    setLastUpdatedAt(now);
    setClientAuditEntries((rows) => [makeEditableAudit("Service user", selectedUser.name, "Overview", oldValue, newValue, avatarDataUrl ? "Service user profile picture changed." : "Service user profile picture removed."), ...rows]);
  };

  return (
    <div className="space-y-6">
      {createdClient ? <div className="rounded-lg bg-emerald-50 p-4 text-sm font-bold text-emerald-800 ring-1 ring-emerald-100">Demo Service User 101 created and opened as a private client file.</div> : null}
      <Card>
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex flex-wrap items-center gap-4">
            <ProfilePictureEditor
              alt={`${selectedUser.name} avatar`}
              currentImage={selectedUser.avatarDataUrl}
              initials={initialsFromName(selectedUser.name)}
              onChange={updateProfilePicture}
              onRemove={() => updateProfilePicture(undefined)}
              tone="blue"
            />
            <div>
              <div className="text-xs font-black uppercase tracking-wide text-blue-700">Private client file</div>
              <h2 className="mt-1 text-3xl font-black text-slate-900">{selectedUser.name} — Client File</h2>
              <div className="mt-3 flex flex-wrap gap-2">
                <PillBadge tone="blue">{summary.packageType}</PillBadge>
                <PillBadge tone={summary.fundingSource.includes("NHS") ? "blue" : "slate"}>{summary.fundingSource}</PillBadge>
                <PillBadge tone={summary.riskLevel === "High" ? "red" : "amber"}>{summary.riskLevel} risk</PillBadge>
                <PillBadge tone={documentStatusTone(summary.reviewStatus)}>Review {summary.reviewStatus}</PillBadge>
                <PillBadge tone={documentStatusTone(summary.documentStatus)}>Documents {summary.documentStatus}</PillBadge>
              </div>
            </div>
          </div>
          <button className="rounded-md border border-slate-200 px-4 py-2 text-sm font-bold text-slate-700" onClick={onBack} type="button">Back to existing users</button>
        </div>
      </Card>
      <Card>
        <SectionTitle subtitle="Only one client section opens at a time." title="Client file tabs" />
        <div className="flex flex-wrap gap-2">
          {visibleClientTabs.map((tab) => (
            <button className={`rounded-md px-3 py-2 text-xs font-bold ${activeTab === tab ? "bg-[#0B1F3A] text-white" : "bg-slate-50 text-slate-700 ring-1 ring-slate-200"}`} key={tab} onClick={() => onSetTab(tab)} type="button">
              {tab}
            </button>
          ))}
        </div>
      </Card>
      <ClientFileTabContent
        activeTab={activeTab}
        auditEntries={clientAuditEntries}
        clientDetails={clientDetails}
        clientDraft={clientDraft}
        editingTab={editingTab}
        lastUpdatedAt={lastUpdatedAt}
        lastUpdatedBy={lastUpdatedBy}
        onCancelEdit={cancelEditing}
        onSaveEdit={saveEditing}
        onStartEdit={startEditing}
        selectedUser={selectedUser}
        setClientDraft={setClientDraft}
      />
    </div>
  );
}

function ClientFileTabContent({
  activeTab,
  auditEntries,
  clientDetails,
  clientDraft,
  editingTab,
  lastUpdatedAt,
  lastUpdatedBy,
  onCancelEdit,
  onSaveEdit,
  onStartEdit,
  selectedUser,
  setClientDraft
}: {
  activeTab: ClientPrivateTab;
  auditEntries: EditableAuditEntry[];
  clientDetails: ClientEditableDetails;
  clientDraft: ClientEditableDetails;
  editingTab: ClientPrivateTab | null;
  lastUpdatedAt: string;
  lastUpdatedBy: string;
  onCancelEdit: () => void;
  onSaveEdit: (tab: ClientPrivateTab) => void;
  onStartEdit: (tab: ClientPrivateTab) => void;
  selectedUser: ServiceUserRecord;
  setClientDraft: (details: ClientEditableDetails) => void;
}) {
  const demoStore = useCareVerityDemoStore();
  const team = selectedUser.regularTeam;
  const fundingProfile = clientFundingProfiles[selectedUser.id] ?? [];
  const isNhsFundedClient = selectedUser.funding.toLowerCase().includes("nhs") || fundingProfile.some(([label, value]) => `${label} ${value}`.toLowerCase().includes("nhs"));
  const selectedUserCallCards = demoStore.localCalls[selectedUser.id] ?? getServiceUserCallCards(selectedUser.id);
  const defaultMultiCallSelection = selectedUserCallCards.filter((call) => ["Morning Call", "Lunch Call", "Tea Call"].includes(call.callType)).map((call) => call.callType).join(",");
  const allClientCallSelection = selectedUserCallCards.map((call) => call.callType).join(",");
  const isEditing = editingTab === activeTab;
  const fieldDisabled = !isEditing;
  const shell = (subtitle: string, children: ReactNode) => (
    <EditableRecordSection
      isEditing={isEditing}
      lastUpdatedAt={lastUpdatedAt}
      lastUpdatedBy={lastUpdatedBy}
      onCancel={onCancelEdit}
      onEdit={() => onStartEdit(activeTab)}
      onSave={() => onSaveEdit(activeTab)}
      recordName={selectedUser.name}
      sectionName={activeTab}
      subtitle={subtitle}
      title={activeTab}
    >
      {children}
    </EditableRecordSection>
  );

  if (activeTab === "Overview") {
    return shell("Client summary only; sensitive details stay behind restricted tabs.", (
      <div className="space-y-5">
        <StaffDetailGrid items={[["Preferred name", clientDetails.preferredName], ["Package type", selectedUser.package], ["Funding source", clientDetails.fundingSource], ["Risk level", clientDetails.riskLevel], ["Continuity priority", team.continuity], ["Review status", clientSummaryRow(selectedUser).reviewStatus], ["Document status", clientSummaryRow(selectedUser).documentStatus], ["Unallocated call packages", selectedUser.id === "demo-su-101" ? "1 Bed Call second carer" : "None open"]]} />
        <div className="grid gap-3 md:grid-cols-3">
          <RotaStat label="Open care actions" tone="amber" value="4" />
          <RotaStat label="Current audit edits" tone="blue" value={String(auditEntries.length)} />
          <RotaStat label="Tenant separation" tone="green" value="On" />
        </div>
      </div>
    ));
  }

  if (activeTab === "Personal Details") {
    return shell("Editable demographic, communication, health-risk and funding fields with dropdowns for controlled values.", (
      <div className="space-y-5">
        <div className="rounded-lg bg-amber-50 p-4 text-sm font-bold text-amber-900 ring-1 ring-amber-200">
          Sensitive warning: religion, ethnicity, NHS number, health/medical information, medication support and moving/handling details require role permission. Every save creates an audit log entry.
        </div>
        <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
          <EditableSelectField disabled={fieldDisabled} label="Title" onChange={(value) => setClientDraft({ ...clientDraft, title: value })} options={titleDropdownOptions} value={clientDraft.title} />
          <EditableTextField disabled={fieldDisabled} label="First name" onChange={(value) => setClientDraft({ ...clientDraft, firstName: value })} value={clientDraft.firstName} />
          <EditableTextField disabled={fieldDisabled} label="Middle name" onChange={(value) => setClientDraft({ ...clientDraft, middleName: value })} value={clientDraft.middleName} />
          <EditableTextField disabled={fieldDisabled} label="Surname" onChange={(value) => setClientDraft({ ...clientDraft, surname: value })} value={clientDraft.surname} />
          <EditableTextField disabled={fieldDisabled} label="Preferred name" onChange={(value) => setClientDraft({ ...clientDraft, preferredName: value })} value={clientDraft.preferredName} />
          <EditableTextField disabled={fieldDisabled} label="Date of birth" onChange={(value) => setClientDraft({ ...clientDraft, dateOfBirth: value })} type="date" value={clientDraft.dateOfBirth} />
          <EditableSelectField disabled={fieldDisabled} label="Gender / sex" onChange={(value) => setClientDraft({ ...clientDraft, genderSex: value })} options={genderSexDropdownOptions} value={clientDraft.genderSex} />
          <EditableSelectField disabled={fieldDisabled} label="Religion" onChange={(value) => setClientDraft({ ...clientDraft, religion: value })} options={religionDropdownOptions} value={clientDraft.religion} />
          <EditableSelectField disabled={fieldDisabled} label="Ethnicity" onChange={(value) => setClientDraft({ ...clientDraft, ethnicity: value })} options={ethnicityDropdownOptions} value={clientDraft.ethnicity} />
          <EditableTextField disabled={fieldDisabled} label="Main language" onChange={(value) => setClientDraft({ ...clientDraft, mainLanguage: value })} value={clientDraft.mainLanguage} />
          <EditableTextField disabled={fieldDisabled} label="Communication needs" onChange={(value) => setClientDraft({ ...clientDraft, communicationNeeds: value })} value={clientDraft.communicationNeeds} />
          <EditableTextField disabled={fieldDisabled} label="Address line 1" onChange={(value) => setClientDraft({ ...clientDraft, addressLine1: value })} value={clientDraft.addressLine1} />
          <EditableTextField disabled={fieldDisabled} label="Address line 2" onChange={(value) => setClientDraft({ ...clientDraft, addressLine2: value })} value={clientDraft.addressLine2} />
          <EditableTextField disabled={fieldDisabled} label="Town / city" onChange={(value) => setClientDraft({ ...clientDraft, townCity: value })} value={clientDraft.townCity} />
          <EditableTextField disabled={fieldDisabled} label="Postcode" onChange={(value) => setClientDraft({ ...clientDraft, postcode: value })} value={clientDraft.postcode} />
          <EditableTextField disabled={fieldDisabled} label="Telephone" onChange={(value) => setClientDraft({ ...clientDraft, telephone: value })} value={clientDraft.telephone} />
          <EditableTextField disabled={fieldDisabled} label="Mobile" onChange={(value) => setClientDraft({ ...clientDraft, mobile: value })} value={clientDraft.mobile} />
          <EditableTextField disabled={fieldDisabled} label="Email" onChange={(value) => setClientDraft({ ...clientDraft, email: value })} type="email" value={clientDraft.email} />
          <EditableTextField disabled={fieldDisabled} label="NHS number" onChange={(value) => setClientDraft({ ...clientDraft, nhsNumber: value })} value={clientDraft.nhsNumber} />
          <EditableTextField disabled={fieldDisabled} label="GP surgery" onChange={(value) => setClientDraft({ ...clientDraft, gpSurgery: value })} value={clientDraft.gpSurgery} />
          <EditableTextField disabled={fieldDisabled} label="GP telephone" onChange={(value) => setClientDraft({ ...clientDraft, gpTelephone: value })} value={clientDraft.gpTelephone} />
          <EditableSelectField disabled={fieldDisabled} label="Funding source" onChange={(value) => setClientDraft({ ...clientDraft, fundingSource: value })} options={fundingSourceDropdownOptions} value={clientDraft.fundingSource} />
          <EditableSelectField disabled={fieldDisabled} label="Risk level" onChange={(value) => setClientDraft({ ...clientDraft, riskLevel: value })} options={riskLevelDropdownOptions} value={clientDraft.riskLevel} />
          <EditableSelectField disabled={fieldDisabled} label="Lives alone yes/no" onChange={(value) => setClientDraft({ ...clientDraft, livesAlone: value })} options={yesNoDropdownOptions} value={clientDraft.livesAlone} />
          <EditableSelectField disabled={fieldDisabled} label="Dementia yes/no" onChange={(value) => setClientDraft({ ...clientDraft, dementia: value })} options={yesNoDropdownOptions} value={clientDraft.dementia} />
          <EditableSelectField disabled={fieldDisabled} label="Mental health yes/no" onChange={(value) => setClientDraft({ ...clientDraft, mentalHealth: value })} options={yesNoDropdownOptions} value={clientDraft.mentalHealth} />
          <EditableSelectField disabled={fieldDisabled} label="Challenging behaviour yes/no" onChange={(value) => setClientDraft({ ...clientDraft, challengingBehaviour: value })} options={yesNoDropdownOptions} value={clientDraft.challengingBehaviour} />
          <EditableSelectField disabled={fieldDisabled} label="Medication support required yes/no" onChange={(value) => setClientDraft({ ...clientDraft, medicationSupportRequired: value })} options={yesNoDropdownOptions} value={clientDraft.medicationSupportRequired} />
          <EditableSelectField disabled={fieldDisabled} label="Moving and handling required yes/no" onChange={(value) => setClientDraft({ ...clientDraft, movingAndHandlingRequired: value })} options={yesNoDropdownOptions} value={clientDraft.movingAndHandlingRequired} />
        </div>
      </div>
    ));
  }

  if (activeTab === "Contacts & Next of Kin") {
    return shell("Family and representative details are role-restricted and audited.", (
      <StaffDetailGrid
        items={[
          ["Next of kin name", "Demo Next of Kin"],
          ["Next of kin relationship", "Daughter"],
          ["Next of kin telephone", "Demo telephone withheld"],
          ["Family representative", "Demo family representative"],
          ["Emergency contact", "Demo emergency contact"],
          ["Family portal access", "Enabled only after approval"],
          ["Approved shared notes", "Care summary only"],
          ["Restricted family dispute notes", "Hidden and role-controlled"]
        ]}
        maskRestricted
      />
    ));
  }

  if (activeTab === "Health & Medical") {
    return shell("Sensitive health, NHS number, mental health, medication and safeguarding items are restricted.", (
      <StaffDetailGrid items={[["GP surgery", clientDetails.gpSurgery], ["GP contact", clientDetails.gpTelephone], ["NHS number", clientDetails.nhsNumber], ["Medical history", "Restricted summary"], ["Allergies", "Demo allergy status recorded"], ["Medication support", clientDetails.medicationSupportRequired], ["Mobility level", clientDetails.movingAndHandlingRequired], ["Equipment used", "Hoist, commode placeholder"], ["Dementia", clientDetails.dementia], ["Mental health concern", clientDetails.mentalHealth], ["Falls risk", clientDetails.riskLevel], ["Pressure sore risk", "High"]]} maskRestricted />
    ));
  }

  if (activeTab === "Care Plan") {
    return shell("Care plan documents are versioned and mobile visibility is manager controlled.", (
      <StaffDetailGrid items={[["Current care plan PDF", "Versioned document placeholder"], ["Visit instructions", "Morning/lunch/tea/bed call instructions"], ["Communication plan", clientDetails.communicationNeeds], ["Nutrition/hydration guidance", "Demo guidance recorded"], ["Pressure area guidance", "High-risk review active"], ["Read acknowledgement history", "Mobile carer acknowledgements tracked"]]} />
    ));
  }

  if (activeTab === "Risk Assessments") {
    return shell("Risk documents are versioned, review-dated and role-restricted where needed.", (
      <StaffDetailGrid items={[["Current risk assessment", "Active"], ["Moving and handling assessment", clientDetails.movingAndHandlingRequired], ["Medication risk assessment", clientDetails.medicationSupportRequired], ["Mental capacity assessment", "Restricted placeholder"], ["Best interest decision record", "Restricted placeholder"], ["Restricted safeguarding risk document", "Manager-only access"]]} maskRestricted />
    ));
  }

  if (activeTab === "Call Package / Visits") {
    return shell("This is where the care coordinator sets up the selected client's active calls.", (
      <div className="space-y-4">
        <MedicationSimpleTable headings={["Call type", "Start", "End", "Duration", "Recurrence", "Single/double-up", "Required skills", "Risk", "Funding", "Status", "Regular carer", "Temporary cover"]} rows={clientCallPackageRows} title="Selected client call package" />
        <div className="rounded-lg bg-teal-50 p-4 ring-1 ring-teal-100">
          <div className="text-sm font-black text-slate-900">Multi-call allocation from this client file</div>
          <p className="mt-1 text-sm text-slate-600">Select multiple calls, then open Rota / Shift Allocation with this service user and those calls already loaded.</p>
          <div className="mt-3 grid gap-2 md:grid-cols-2 xl:grid-cols-4">
            {selectedUserCallCards.slice(0, 12).map((call) => (
              <label className="flex items-center gap-2 rounded-md bg-white px-3 py-2 text-xs font-bold text-slate-700 ring-1 ring-teal-100" key={call.callType}>
                <input defaultChecked={["Morning Call", "Lunch Call", "Tea Call"].includes(call.callType)} type="checkbox" />
                {call.callType}
              </label>
            ))}
          </div>
        </div>
        <div className="mt-4 flex flex-wrap gap-2">
          {["Add Call", "Edit Call", "Pause Call", "Stop Call"].map((button) => <button className="rounded-md bg-slate-100 px-3 py-2 text-xs font-bold text-slate-700" key={button} type="button">{button}</button>)}
          <a className="rounded-md bg-teal-600 px-3 py-2 text-xs font-bold text-white" href={`/careverity-ecm/rota?client=${selectedUser.id}&calls=${encodeURIComponent(defaultMultiCallSelection)}`}>Allocate selected calls</a>
          <a className="rounded-md bg-teal-600 px-3 py-2 text-xs font-bold text-white" href={`/careverity-ecm/rota?client=${selectedUser.id}&calls=${encodeURIComponent(defaultMultiCallSelection)}&range=Two+weeks`}>Create 2 Week Rota</a>
          <a className="rounded-md bg-teal-600 px-3 py-2 text-xs font-bold text-white" href={`/careverity-ecm/rota?client=${selectedUser.id}&calls=${encodeURIComponent(allClientCallSelection)}&range=One+month`}>Create 1 Month Rota</a>
          <a className="rounded-md bg-emerald-600 px-3 py-2 text-xs font-bold text-white" href={`/careverity-ecm/rota?client=${selectedUser.id}&calls=${encodeURIComponent(defaultMultiCallSelection)}&allocation=Permanent+regular+carer`}>Assign Regular Carer</a>
          <a className="rounded-md bg-amber-500 px-3 py-2 text-xs font-bold text-slate-950" href={`/careverity-ecm/rota?client=${selectedUser.id}&calls=${encodeURIComponent(defaultMultiCallSelection)}&allocation=Temporary+cover`}>Assign Temporary Cover</a>
          <a className="rounded-md bg-slate-800 px-3 py-2 text-xs font-bold text-white" href={`/careverity-ecm/rota?client=${selectedUser.id}&calls=${encodeURIComponent(allClientCallSelection)}`}>View Client Rota</a>
        </div>
      </div>
    ));
  }

  if (activeTab === "Rota & Regular Carers") {
    return (
      <div className="space-y-6">
        {shell("Care package, call schedule and regular staffing rules.", (
          <>
            <div className="space-y-3">
              <ProfileLine label="Call schedule" value={team.usualTimes.join(" | ")} />
              <ProfileLine label="Required skills" value={team.skills.join(", ")} />
              <ProfileLine label="Double-up rule" value={team.doubleUp} />
              <ProfileLine label="Documented language/preference need" value={team.preference} />
            </div>
            <div className="mt-4 grid gap-3 sm:grid-cols-2">
              <InfoTile label="Primary Care Worker" value={team.primary} />
              <InfoTile label="Additional Care Worker" value={team.additional} />
              <InfoTile label="Outreach Care Worker" value={team.outreach} />
              <InfoTile label="Additional Outreach Care Worker" value={team.additionalOutreach} />
            </div>
            <div className="mt-4 grid gap-4 md:grid-cols-2">
              <CarerChips label="Preferred carers" tone="green" values={team.preferred} />
              <CarerChips label="Excluded carers" tone="red" values={team.excluded} />
            </div>
          </>
        ))}
        <PermanentAllocationTable />
      </div>
    );
  }

  if (activeTab === "Medication / eMAR") {
    return (
      <div className="space-y-6">
        {shell("Medication and eMAR profile controls are role-restricted and audit logged.", (
          <StaffDetailGrid items={[["Medication support required", clientDetails.medicationSupportRequired], ["eMAR status", clientDetails.medicationSupportRequired === "Yes" ? "Required" : "Not required"], ["Controlled drugs", "Restricted placeholder"], ["Medication audit", "Enabled"]]} maskRestricted />
        ))}
        <MedicationMarDashboard mode="overview" />
        <MedicationGovernanceAuditPanel />
      </div>
    );
  }

  if (activeTab === "Documents") {
    return (
      <div className="space-y-6">
        {shell("Every client document upload, replacement, view and download is audited.", (
          <StaffDetailGrid items={[["Client document folder", `/clients/${selectedUser.id}/documents`], ["Restricted documents", "Safeguarding, health, medication and key-safe records"], ["Mobile visibility", "Manager controlled"], ["Audit logging", "Required for every access"]]} maskRestricted />
        ))}
        <ClientDocumentsArea selectedUserName={selectedUser.name} serviceUserId={selectedUser.id} />
      </div>
    );
  }

  if (activeTab === "Messages / Notes") {
    return shell("Restricted note types are locked after saving. Corrections must be addendums.", (
      <div className="space-y-4">
        <div className="flex flex-wrap gap-2">
          {["Add General Note", "Add Family Communication", "Add Professional Communication", "Add Concern", "Add Complaint", "Add Incident", "Add Accident", "Add Safeguarding Concern", "Add Medication Concern", "Add Skin Integrity Concern", "Add Review Note"].map((button) => <button className="rounded-md bg-slate-100 px-3 py-2 text-xs font-bold text-slate-700" key={button} type="button">{button}</button>)}
        </div>
        <MedicationSimpleTable headings={["Note type", "Date/time", "Written by", "Role", "Linked visit", "Priority", "Action required", "Manager review", "Locking rule"]} rows={clientMessageRows} title="Client notes and messages" />
      </div>
    ));
  }

  if (activeTab === "Journal / Communication Log") {
    return (
      <div className="space-y-6">
        {shell("Journal entries are permanent records. Corrections must be by addendum only.", (
          <div className="rounded-lg bg-amber-50 p-4 text-sm font-bold text-amber-900 ring-1 ring-amber-200">
            Permanent record: saved journal entries must not be deleted or overwritten. Use Addendum / Correction to preserve the original record and create a new audit event.
          </div>
        ))}
        <ClientJournalCommunicationLog selectedUser={selectedUser} />
      </div>
    );
  }

  if (activeTab === "Behaviour Monitoring") {
    return shell("Shown when behaviourSupportRequired is Yes, or when an authorised admin opens it for setup/review.", (
      <BehaviourMonitoringPositiveSupportModule embeddedServiceUser={selectedUser} />
    ));
  }

  if (activeTab === "AI Care Review & Referral Assistant") {
    return shell("AI suggestions and generated drafts are review-only until approved by an authorised manager or care coordinator.", (
      <AICareReviewReferralAssistant selectedUserName={selectedUser.name} serviceUserId={selectedUser.id} />
    ));
  }

  if (activeTab === "Incidents / Complaints / Safeguarding") {
    return shell("Sensitive governance records are role-restricted and locked after saving.", (
      <StaffDetailGrid items={[["Open complaint", "One demo complaint"], ["Medication concern", "Manager review"], ["Skin integrity concern", "Active monitoring"], ["Safeguarding chronology", "Restricted"], ["Incident evidence", "Evidence register enabled"], ["CQC mapping", "Safe, responsive and well-led"]]} maskRestricted />
    ));
  }

  if (activeTab === "Reviews") {
    return shell("Review records track care plan, risk, medication and package review actions.", (
      <MedicationSimpleTable headings={["Review type", "Last review", "Next review", "Owner", "Status", "Notes"]} rows={clientReviewRows} title="Client reviews" />
    ));
  }

  if (activeTab === "Family Portal") {
    return shell("Family users only see information approved for them.", (
      <StaffDetailGrid items={[["Family portal enabled", "Yes - demo placeholder"], ["Visit summary approved", "Yes"], ["Care notes limited", "Yes"], ["Documents selected", "Care plan summary only"], ["Sensitive notes restricted", "Safeguarding, health and key-safe details hidden"], ["Audit family views", "Every view is logged"]]} maskRestricted />
    ));
  }

  if (activeTab === "Audit Log") {
    return shell("Every view, edit, restricted access, note and document action is logged.", (
      <div className="space-y-5">
        <MedicationSimpleTable headings={["Date/time", "User", "Role", "Record type", "Record name", "Field changed", "Old value", "New value", "Reason/comment"]} rows={auditRowsFromEntries(auditEntries)} title="Saved editable client audit entries" />
        <MedicationSimpleTable headings={["Date/time", "User", "Role", "Action", "Affected section", "Reason/comment", "IP/location placeholder"]} rows={clientAuditRows} title="Client file audit log" />
      </div>
    ));
  }

  return shell("Funding, commissioner and billing details are role-controlled and audit logged.", (
    <FundingCommissionerPanel fundingRows={fundingProfile} isNhsFunded={isNhsFundedClient} selectedUserName={selectedUser.name} />
  ));
}

function ClientDocumentsArea({ selectedUserName, serviceUserId }: { selectedUserName: string; serviceUserId: string }) {
  const currentDemoUser = useDemoCurrentUser("Care Coordinator");
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const replacementInputRef = useRef<HTMLInputElement | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [replacementTargetId, setReplacementTargetId] = useState("");
  const [documentCategory, setDocumentCategory] = useState(clientDocumentCategories[0]);
  const [documentTitle, setDocumentTitle] = useState("");
  const [documentDescription, setDocumentDescription] = useState("");
  const [replacementReason, setReplacementReason] = useState("");
  const [restricted, setRestricted] = useState(false);
  const [mobileVisible, setMobileVisible] = useState(true);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [uploadMessage, setUploadMessage] = useState("");
  const [uploadError, setUploadError] = useState("");
  const [showArchived, setShowArchived] = useState(false);
  const [documentAuditEvents, setDocumentAuditEvents] = useState<string[]>([
    "Demo audit: Current care plan viewed by Demo Care Coordinator.",
    "Demo audit: Restricted medication document access checked."
  ]);
  const [uploadedDocuments, setUploadedDocuments] = useState<DemoClientDocumentRecord[]>([]);

  const canUploadClientDocument = [
    "Registered Manager",
    "Company Admin",
    "Care Coordinator",
    "Supervisor",
    "Compliance Manager"
  ].includes(currentDemoUser.role);
  const activeDocuments = uploadedDocuments.filter((documentRecord) => showArchived || documentRecord.status === "Active");

  const addDocumentAuditEvent = (message: string) => {
    setDocumentAuditEvents((events) => [`${new Date().toLocaleString("en-GB")} - ${message}`, ...events].slice(0, 12));
  };

  const validateClientDocumentFile = (file: File | null) => {
    if (!file) return "Please choose a file before uploading.";
    const extension = getClientDocumentExtension(file.name);
    if (!clientAllowedDocumentExtensions.includes(extension as (typeof clientAllowedDocumentExtensions)[number])) {
      return "File type not allowed. Allowed file types: PDF, Word, image and Excel files only.";
    }
    if (file.size > clientDocumentMaxUploadMb * 1024 * 1024) {
      return `File is too large. Maximum upload size is ${clientDocumentMaxUploadMb} MB.`;
    }
    return "";
  };

  const handleClientDocumentFile = (file: File | null) => {
    setUploadMessage("");
    setUploadError("");
    const error = validateClientDocumentFile(file);
    if (error) {
      setSelectedFile(null);
      setUploadError(error);
      return;
    }
    setSelectedFile(file);
    if (file && !documentTitle.trim()) {
      setDocumentTitle(file.name.replace(/\.[^.]+$/, "").replace(/[-_]+/g, " "));
    }
  };

  const handleClientDocumentDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    handleClientDocumentFile(event.dataTransfer.files[0] ?? null);
  };

  const resetUploadForm = () => {
    setSelectedFile(null);
    setDocumentTitle("");
    setDocumentDescription("");
    setReplacementTargetId("");
    setReplacementReason("");
    setRestricted(false);
    setMobileVisible(true);
    setUploadProgress(0);
    if (fileInputRef.current) fileInputRef.current.value = "";
    if (replacementInputRef.current) replacementInputRef.current.value = "";
  };

  const uploadClientDocument = () => {
    setUploadMessage("");
    setUploadError("");
    if (!canUploadClientDocument) {
      setUploadError("You are not authorised to upload client documents.");
      return;
    }
    if (!documentTitle.trim()) {
      setUploadError("Document title is required.");
      return;
    }
    const fileError = validateClientDocumentFile(selectedFile);
    if (fileError || !selectedFile) {
      setUploadError(fileError || "Please choose a file before uploading.");
      return;
    }
    if (replacementTargetId && !replacementReason.trim()) {
      setUploadError("Replacement reason is required when replacing an existing document.");
      return;
    }

    setUploadProgress(55);
    const documentId = `client-doc-${Date.now()}`;
    const safeFileName = createSafeClientDocumentFileName(selectedFile.name);
    const objectUrl = URL.createObjectURL(selectedFile);
    const replacedDocument = uploadedDocuments.find((documentRecord) => documentRecord.id === replacementTargetId);
    const nextRecord: DemoClientDocumentRecord = {
      id: documentId,
      companyId: "demo-company-001",
      serviceUserId,
      documentCategory,
      documentTitle: documentTitle.trim(),
      documentDescription: documentDescription.trim(),
      originalFileName: selectedFile.name,
      safeFileName,
      fileType: getClientDocumentExtension(selectedFile.name).replace(".", "").toUpperCase(),
      fileSizeBytes: selectedFile.size,
      storagePath: `companies/demo-company-001/service-users/${serviceUserId}/documents/${documentId}/${safeFileName}`,
      version: replacedDocument ? replacedDocument.version + 1 : 1,
      status: "Active",
      restricted,
      mobileVisible,
      uploadedBy: currentDemoUser.name,
      uploadedByRole: currentDemoUser.role,
      uploadedAt: new Date().toLocaleString("en-GB"),
      replacedDocumentId: replacedDocument?.id,
      objectUrl
    };

    setUploadedDocuments((documents) => [
      nextRecord,
      ...documents.map((documentRecord) =>
        documentRecord.id === replacementTargetId
          ? { ...documentRecord, status: "Archived" as const, archiveReason: replacementReason || "Replaced by newer version" }
          : documentRecord
      )
    ]);
    setUploadProgress(100);
    setUploadMessage(replacedDocument ? "Document replaced successfully. Previous version archived and audit logged." : "Document uploaded successfully.");
    addDocumentAuditEvent(
      replacedDocument
        ? `${currentDemoUser.name} replaced ${replacedDocument.documentTitle} with ${nextRecord.documentTitle}; reason: ${replacementReason}.`
        : `${currentDemoUser.name} uploaded ${nextRecord.documentTitle} for ${selectedUserName}.`
    );
    resetUploadForm();
    setUploadProgress(100);
  };

  const replaceClientDocument = (documentRecord: DemoClientDocumentRecord) => {
    setReplacementTargetId(documentRecord.id);
    setDocumentCategory(documentRecord.documentCategory);
    setDocumentTitle(documentRecord.documentTitle);
    setDocumentDescription(documentRecord.documentDescription);
    setRestricted(documentRecord.restricted);
    setMobileVisible(documentRecord.mobileVisible);
    setUploadMessage(`Replacing ${documentRecord.documentTitle}. Choose the new file and enter a replacement reason.`);
    replacementInputRef.current?.focus();
  };

  const archiveClientDocument = (documentId: string, reason = "Archived from demo document register") => {
    setUploadedDocuments((documents) =>
      documents.map((documentRecord) =>
        documentRecord.id === documentId ? { ...documentRecord, status: "Archived" as const, archiveReason: reason } : documentRecord
      )
    );
    addDocumentAuditEvent(`${currentDemoUser.name} archived a client document. Reason: ${reason}.`);
  };

  const deleteClientDocument = (documentId: string) => {
    setUploadedDocuments((documents) =>
      documents.map((documentRecord) =>
        documentRecord.id === documentId ? { ...documentRecord, status: "Deleted" as const, archiveReason: "Deleted in demo mode by authorised user" } : documentRecord
      )
    );
    addDocumentAuditEvent(`${currentDemoUser.name} deleted a demo client document record.`);
  };

  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle subtitle="Service user/client evidence is separate from staff/HR evidence." title={`${selectedUserName} Client Documents`} />
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          {["/clients", "/clients/[clientId]", "/clients/[clientId]/documents", "/clients/[clientId]/care-plan", "/clients/[clientId]/risk-assessments", "/clients/[clientId]/messages", "/clients/[clientId]/audit"].map((route) => (
            <div className="rounded-md bg-slate-50 p-3 font-mono text-xs font-bold text-slate-700 ring-1 ring-slate-100" key={route}>
              {route}
            </div>
          ))}
        </div>
      </Card>

      <Card>
        <SectionTitle
          subtitle="Upload client documents into the private service-user file. Demo mode keeps metadata locally; production requires private storage, tenant checks, role permissions and audit logging."
          title="Upload Document"
        />
        <div className="mb-4 rounded-lg bg-amber-50 p-4 text-sm font-bold leading-6 text-amber-900 ring-1 ring-amber-200">
          Demo mode active. Do not upload live care records until private storage, authentication, tenant separation and audit logging are enabled. Production API guard: {clientDocumentStorageNotConfiguredMessage}
        </div>
        <div className="mb-4 rounded-lg bg-blue-50 p-4 text-sm font-bold leading-6 text-blue-900 ring-1 ring-blue-200">
          Document upload is in demo/scaffold mode. Private storage and database persistence must be configured before uploading live client documents.
        </div>
        {!canUploadClientDocument ? (
          <div className="mb-4 rounded-lg bg-rose-50 p-4 text-sm font-bold text-rose-900 ring-1 ring-rose-200">
            Your current demo role is {currentDemoUser.role}. Only Registered Manager, Company Admin, Care Coordinator, Supervisor and Compliance Manager roles can upload client documents.
          </div>
        ) : null}
        <div
          className="rounded-xl border-2 border-dashed border-teal-200 bg-teal-50/60 p-6 text-center"
          onClick={() => fileInputRef.current?.click()}
          onDragOver={(event) => event.preventDefault()}
          onDrop={handleClientDocumentDrop}
          role="button"
          tabIndex={0}
        >
          <input
            accept={clientDocumentAccept}
            className="hidden"
            onChange={(event) => handleClientDocumentFile(event.target.files?.[0] ?? null)}
            ref={fileInputRef}
            type="file"
          />
          <div className="text-base font-black text-slate-900">Drag and drop a document here, or click to choose a file</div>
          <div className="mt-2 text-sm font-semibold text-slate-600">Allowed: PDF, Word, images and Excel files. Maximum {clientDocumentMaxUploadMb} MB.</div>
          {selectedFile ? (
            <div className="mt-4 inline-flex rounded-full bg-white px-4 py-2 text-sm font-bold text-teal-800 ring-1 ring-teal-200">
              Selected: {selectedFile.name} ({formatClientDocumentSize(selectedFile.size)})
            </div>
          ) : null}
        </div>

        <div className="mt-5 grid gap-4 lg:grid-cols-2">
          <FilterSelect label="Document category" onChange={setDocumentCategory} options={clientDocumentCategories} value={documentCategory} />
          <label className="block">
            <span className="text-xs font-bold uppercase text-slate-500">Document title</span>
            <input className="mt-2 w-full rounded-md border border-slate-200 px-4 py-3 text-sm font-semibold" onChange={(event) => setDocumentTitle(event.target.value)} placeholder="Enter clear document title" value={documentTitle} />
          </label>
          <label className="block lg:col-span-2">
            <span className="text-xs font-bold uppercase text-slate-500">Description / notes</span>
            <textarea className="mt-2 min-h-28 w-full rounded-md border border-slate-200 px-4 py-3 text-sm leading-6" onChange={(event) => setDocumentDescription(event.target.value)} placeholder="Add short notes, review context, source or document purpose" value={documentDescription} />
          </label>
          <label className="block">
            <span className="text-xs font-bold uppercase text-slate-500">Replacement reason</span>
            <input
              className="mt-2 w-full rounded-md border border-slate-200 px-4 py-3 text-sm font-semibold"
              onChange={(event) => setReplacementReason(event.target.value)}
              placeholder={replacementTargetId ? "Required for replacement" : "Only needed when replacing a document"}
              ref={replacementInputRef}
              value={replacementReason}
            />
          </label>
          <div className="grid gap-3 sm:grid-cols-2">
            <ToggleFilter checked={restricted} label="Restricted document" onChange={setRestricted} />
            <ToggleFilter checked={mobileVisible} label="Visible in mobile app" onChange={setMobileVisible} />
          </div>
        </div>

        <div className="mt-5">
          <div className="h-3 overflow-hidden rounded-full bg-slate-100">
            <div className="h-full rounded-full bg-teal-500 transition-all" style={{ width: `${uploadProgress}%` }} />
          </div>
          <div className="mt-2 text-xs font-bold text-slate-500">Upload progress: {uploadProgress}%</div>
        </div>

        {uploadError ? <div className="mt-4 rounded-md bg-rose-50 p-3 text-sm font-bold text-rose-900 ring-1 ring-rose-200">{uploadError}</div> : null}
        {uploadMessage ? <div className="mt-4 rounded-md bg-emerald-50 p-3 text-sm font-bold text-emerald-900 ring-1 ring-emerald-200">{uploadMessage}</div> : null}

        <div className="mt-5 flex flex-wrap gap-3">
          <button className="rounded-md bg-teal-600 px-5 py-3 text-sm font-black text-white disabled:cursor-not-allowed disabled:bg-slate-300" disabled={!canUploadClientDocument} onClick={uploadClientDocument} type="button">
            {replacementTargetId ? "Replace Document" : "Upload Document"}
          </button>
          <button className="rounded-md border border-slate-200 px-5 py-3 text-sm font-bold text-slate-700" onClick={resetUploadForm} type="button">Cancel upload</button>
          <label className="flex items-center gap-2 rounded-md bg-slate-50 px-4 py-3 text-sm font-bold text-slate-700 ring-1 ring-slate-100">
            <input checked={showArchived} onChange={(event) => setShowArchived(event.target.checked)} type="checkbox" />
            Show archived/deleted versions
          </label>
        </div>
      </Card>

      <Card>
        <SectionTitle subtitle="Uploaded documents are versioned, tenant-scoped and audited. Restricted files are hidden from unauthorised users." title="Uploaded Documents" />
        {activeDocuments.length === 0 ? (
          <div className="rounded-lg bg-slate-50 p-6 text-sm font-bold text-slate-700 ring-1 ring-slate-100">
            No documents uploaded yet. Use Upload Document to add client documents.
          </div>
        ) : (
          <div className="overflow-x-auto rounded-lg border border-slate-200">
            <table className="w-full min-w-[1300px] text-left text-sm">
              <thead className="bg-slate-50 text-xs uppercase text-slate-500">
                <tr>
                  {["Document title", "Category", "File name", "Type", "Size", "Version", "Uploaded by", "Uploaded date/time", "Status", "Restricted", "Mobile", "Actions"].map((heading) => (
                    <th className="p-3" key={heading}>{heading}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {activeDocuments.map((documentRecord) => (
                  <tr className={documentRecord.status === "Active" ? "bg-white" : "bg-slate-50"} key={documentRecord.id}>
                    <td className="p-3 font-black text-slate-900">{documentRecord.documentTitle}</td>
                    <td className="p-3 text-slate-700">{documentRecord.documentCategory}</td>
                    <td className="p-3 text-slate-700">{documentRecord.originalFileName}</td>
                    <td className="p-3 text-slate-700">{documentRecord.fileType}</td>
                    <td className="p-3 text-slate-700">{formatClientDocumentSize(documentRecord.fileSizeBytes)}</td>
                    <td className="p-3 text-slate-700">v{documentRecord.version}.0</td>
                    <td className="p-3 text-slate-700">{documentRecord.uploadedBy}</td>
                    <td className="p-3 text-slate-700">{documentRecord.uploadedAt}</td>
                    <td className="p-3"><PillBadge tone={documentRecord.status === "Active" ? "green" : "slate"}>{documentRecord.status}</PillBadge></td>
                    <td className="p-3"><PillBadge tone={documentRecord.restricted ? "red" : "green"}>{documentRecord.restricted ? "Yes" : "No"}</PillBadge></td>
                    <td className="p-3"><PillBadge tone={documentRecord.mobileVisible ? "teal" : "slate"}>{documentRecord.mobileVisible ? "Visible" : "Hidden"}</PillBadge></td>
                    <td className="p-3">
                      <div className="flex flex-wrap gap-2">
                        {documentRecord.objectUrl ? (
                          <a className="rounded-md bg-slate-100 px-3 py-2 text-xs font-bold text-slate-700" href={documentRecord.objectUrl} onClick={() => addDocumentAuditEvent(`${currentDemoUser.name} viewed ${documentRecord.documentTitle}.`)} rel="noreferrer" target="_blank">View</a>
                        ) : (
                          <button className="rounded-md bg-slate-100 px-3 py-2 text-xs font-bold text-slate-700" onClick={() => addDocumentAuditEvent(`${currentDemoUser.name} viewed ${documentRecord.documentTitle}.`)} type="button">View</button>
                        )}
                        {documentRecord.objectUrl ? (
                          <a className="rounded-md bg-slate-100 px-3 py-2 text-xs font-bold text-slate-700" download={documentRecord.originalFileName} href={documentRecord.objectUrl} onClick={() => addDocumentAuditEvent(`${currentDemoUser.name} downloaded ${documentRecord.documentTitle}.`)}>Download</a>
                        ) : (
                          <button className="rounded-md bg-slate-100 px-3 py-2 text-xs font-bold text-slate-700" onClick={() => addDocumentAuditEvent(`${currentDemoUser.name} downloaded ${documentRecord.documentTitle}.`)} type="button">Download</button>
                        )}
                        <button className="rounded-md bg-blue-50 px-3 py-2 text-xs font-bold text-blue-800" onClick={() => replaceClientDocument(documentRecord)} type="button">Replace</button>
                        <button className="rounded-md bg-amber-50 px-3 py-2 text-xs font-bold text-amber-800" onClick={() => archiveClientDocument(documentRecord.id)} type="button">Archive</button>
                        <button className="rounded-md bg-rose-50 px-3 py-2 text-xs font-bold text-rose-800" onClick={() => deleteClientDocument(documentRecord.id)} type="button">Delete</button>
                        <button className="rounded-md bg-slate-900 px-3 py-2 text-xs font-bold text-white" onClick={() => addDocumentAuditEvent(`Audit viewed for ${documentRecord.documentTitle}. Storage path: ${documentRecord.storagePath}`)} type="button">Audit</button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
        <div className="mt-4 rounded-lg bg-slate-50 p-4 ring-1 ring-slate-100">
          <div className="text-xs font-bold uppercase text-slate-500">Document audit events</div>
          <div className="mt-3 space-y-2">
            {documentAuditEvents.map((event) => (
              <div className="rounded-md bg-white p-3 text-sm font-semibold text-slate-700 ring-1 ring-slate-100" key={event}>{event}</div>
            ))}
          </div>
        </div>
      </Card>

      <DocumentChecklistPanel
        rows={clientChecklistRows}
        subtitle="Missing or expired client documents feed dashboard alerts, client compliance reports, CQC evidence and rota warnings where relevant."
        title="Client file checklist"
      />

      <Card>
        <SectionTitle subtitle="Upload areas for client-specific care, risk, consent, correspondence, safeguarding, complaint, incident and funding documents." title="Client document upload areas" />
        <div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">
          {clientDocumentCategories.map((category, index) => (
            <div className="rounded-md bg-slate-50 p-3 text-sm font-semibold text-slate-700 ring-1 ring-slate-100" key={category}>
              <PillBadge tone={index < 8 ? "teal" : index < 15 ? "blue" : "amber"}>{index < 8 ? "Care file" : index < 15 ? "Professional" : "Evidence"}</PillBadge>
              <div className="mt-2">{category}</div>
            </div>
          ))}
        </div>
      </Card>

      <DocumentRegisterTable
        headings={["Document title", "Category", "File upload placeholder", "File type", "Version", "Document date", "Review date", "Expiry date", "Uploaded by", "Uploaded date/time", "Status", "Visibility level", "Mobile app visibility", "Carer must read", "Acknowledgement required", "Linked care plan/risk/visit", "Restricted/sensitive", "Audit log"]}
        rows={clientDocumentRows}
        title="Client document register"
      />

      <div className="grid gap-6 xl:grid-cols-[1fr_0.85fr]">
        <CarerMobileDocumentAccessPanel />
        <PdfDocumentViewerPanel />
      </div>
    </div>
  );
}

function ClientJournalCommunicationLog({ selectedUser }: { selectedUser: (typeof rotaServiceUsers)[number] }) {
  const currentDemoUser = useDemoCurrentUser("Care Coordinator");
  const currentUserLabel = `${currentDemoUser.name} (${currentDemoUser.role})`;
  const additionalTaggedOptions = useMemo(() => journalStaffOptions.filter((option) => !option.startsWith("All ") && option !== "Care Coordination Team").slice(0, 12), []);
  const witnessTaggedOptions = useMemo(() => journalStaffOptions.filter((option) => !option.startsWith("All ") && option !== "Care Coordination Team").slice(12, 24), []);
  const tagReasonPreviewRows = useMemo(
    () =>
      additionalTaggedOptions.slice(0, 4).map((staffOption, index) => [
        staffOption,
        ["Action required", "Manager review required", "Quality review required", "For information only"][index] ?? "For information only"
      ]),
    [additionalTaggedOptions]
  );
  const [showForm, setShowForm] = useState(false);
  const [savedEntry, setSavedEntry] = useState(false);
  const [showAiAssist, setShowAiAssist] = useState(false);
  const [showAddendum, setShowAddendum] = useState(false);
  const [actionCompleted, setActionCompleted] = useState(false);
  const [selectedEntryId, setSelectedEntryId] = useState(demoClientJournalEntries[0].id);
  const selectedEntry = demoClientJournalEntries.find((entry) => entry.id === selectedEntryId) ?? demoClientJournalEntries[0];
  const routeHref = `/careverity-ecm/rota?client=${selectedUser.id}&calls=${encodeURIComponent("Lunch Call")}&range=Two+weeks`;
  const reviewActionRequired = ["Health concern", "Medication communication", "Skin integrity concern", "Safeguarding concern"].includes(selectedEntry.type);

  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle
          action={
            <div className="flex flex-wrap gap-2">
              <button className="rounded-md bg-teal-600 px-4 py-2 text-sm font-bold text-white" onClick={() => setShowForm(true)} type="button">Add Journal Entry</button>
              <button className="rounded-md bg-[#0B1F3A] px-4 py-2 text-sm font-bold text-white" onClick={() => setShowAiAssist(true)} type="button">AI Voice Note Assist</button>
            </div>
          }
          subtitle="Record all service user communications, requests, professional updates, family contact, changes, concerns and follow-up actions. Journal entries are locked after saving and corrections must be made by addendum."
          title={`${selectedUser.name} Journal / Communication Log`}
        />
        <div className="grid gap-3 md:grid-cols-4">
          <RotaStat label="Open journal actions" tone="amber" value="3" />
          <RotaStat label="Urgent/restricted" tone="red" value="2" />
          <RotaStat label="Awaiting response" tone="blue" value="2" />
          <RotaStat label="Locked entries" tone="green" value="100%" />
        </div>
        <div className="mt-4 rounded-lg bg-amber-50 p-3 text-sm font-bold text-amber-900 ring-1 ring-amber-200">
          Permanent record: entries cannot be edited, deleted, overwritten or backdated after saving. Corrections must be linked addendums.
        </div>
      </Card>

      {showForm ? (
        <Card>
          <SectionTitle action={<button className="rounded-md border border-slate-200 px-3 py-2 text-xs font-bold text-slate-700" onClick={() => setShowForm(false)} type="button">Close form</button>} subtitle="Complete the fields, review attachments and save. The saved journal entry becomes locked." title="New Journal Entry" />
          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
            <FilterSelect label="Journal type / communication type" onChange={() => undefined} options={journalCommunicationTypes} value="Telephone call from service user" />
            <FilterSelect label="Direction" onChange={() => undefined} options={["Incoming", "Outgoing", "Internal note"]} value="Incoming" />
            <ProfileMini label="Linked service user" value={selectedUser.name} />
            <FilterSelect label="Linked visit / call" onChange={() => undefined} options={["Morning Call", "Lunch Call", "Tea Call", "Bed Call", "Night Call", "Outreach", "Shopping", "Sitting Service", "Cleaning", "Medication Prompt", "Welfare Check", "Other visit"]} value="Lunch Call" />
            <ProfileMini label="Written by" value={currentDemoUser.name} />
            <ProfileMini label="Written by role" value={currentDemoUser.role} />
            {[
              ["Contact name", "Demo Service User 101"],
              ["Relationship / role", "Service user"],
              ["Organisation", "Service user"],
              ["Phone/email", "demo.contact@example.invalid"],
              ["Subject / summary", "Lunch call time change request"]
            ].map(([label, value]) => (
              <label className="block" key={label}>
                <span className="text-xs font-bold uppercase text-slate-500">{label}</span>
                <input className="mt-2 w-full rounded-md border border-slate-200 px-4 py-3 text-base" defaultValue={value} />
              </label>
            ))}
            <label className="block md:col-span-2 xl:col-span-4">
              <span className="text-xs font-bold uppercase text-slate-500">Main journal note</span>
              <textarea className="mt-2 min-h-64 w-full rounded-lg border border-slate-200 px-4 py-3 text-base leading-7" defaultValue="Service user called at 10:15 and requested that the lunch call be changed from 11:00 to 12:30 due to a medical appointment. Care coordinator advised that the request will be reviewed and confirmed once rota impact has been checked." />
            </label>
            <FilterSelect label="Action required" onChange={() => undefined} options={["Yes", "No"]} value="Yes" />
            <FilterSelect label="Action type" onChange={() => undefined} options={journalActionTypes} value="Rota update required" />
            <FilterSelect label="Priority" onChange={() => undefined} options={["Low", "Normal", "High", "Urgent"]} value="Normal" />
            <label className="block">
              <span className="text-xs font-bold uppercase text-slate-500">Due date</span>
              <input className="mt-2 w-full rounded-md border border-slate-200 px-3 py-2 text-sm" defaultValue="2026-05-16" type="date" />
            </label>
            <FilterSelect label="Assigned to" onChange={() => undefined} options={["Care Coordinator", "Registered Manager", "Deputy Manager", "HR/Admin", "Medication Lead", "Safeguarding Lead", "Field Supervisor", "Other"]} value="Care Coordinator" />
            <FilterSelect label="Visibility" onChange={() => undefined} options={["Internal only", "Care team visible", "Manager only", "Safeguarding restricted", "Medication authorised roles only", "Family portal visible only if approved"]} value="Care team visible" />
            <button className="rounded-md border border-dashed border-slate-300 bg-slate-50 px-3 py-2 text-left text-sm font-semibold text-slate-600" type="button">Attachment / evidence upload placeholder</button>
            <ProfileMini label="Auto timestamp" value="16 May 2026, 10:15" />
          </div>
          <div className="mt-5 rounded-lg border border-slate-200 bg-white p-4">
            <div className="text-base font-black text-slate-900">Staff Tagging / Action Assignment</div>
            <p className="mt-1 text-sm leading-6 text-slate-600">Tag one main action owner, additional staff who need to act or review, and information-only witnesses. Tagging creates notifications, tasks and read receipts.</p>
            <div className="mt-4 grid gap-4 lg:grid-cols-2">
              <FilterSelect label="Main action owner" onChange={() => undefined} options={journalStaffOptions} value={currentUserLabel} />
              <FilterSelect label="Tag reason for main owner" onChange={() => undefined} options={journalTagReasons} value="Action required" />
              <div className="rounded-md bg-slate-50 p-3 ring-1 ring-slate-100">
                <div className="text-xs font-bold uppercase text-slate-500">Additional tagged staff</div>
                <div className="mt-2 grid gap-2 sm:grid-cols-2">
                  {additionalTaggedOptions.map((staffOption, index) => (
                    <label className="flex items-center gap-2 text-sm font-semibold text-slate-700" key={staffOption}>
                      <input defaultChecked={index < 3} type="checkbox" />
                      {staffOption}
                    </label>
                  ))}
                </div>
              </div>
              <div className="rounded-md bg-slate-50 p-3 ring-1 ring-slate-100">
                <div className="text-xs font-bold uppercase text-slate-500">Witness / information only staff</div>
                <div className="mt-2 grid gap-2 sm:grid-cols-2">
                  {witnessTaggedOptions.map((staffOption, index) => (
                    <label className="flex items-center gap-2 text-sm font-semibold text-slate-700" key={staffOption}>
                      <input defaultChecked={index < 2} type="checkbox" />
                      {staffOption}
                    </label>
                  ))}
                </div>
              </div>
              <div className="rounded-md bg-slate-50 p-3 ring-1 ring-slate-100 lg:col-span-2">
                <div className="text-xs font-bold uppercase text-slate-500">Department/team tag</div>
                <div className="mt-2 flex flex-wrap gap-2">
                  {journalDepartmentTags.map((teamTag, index) => (
                    <label className="flex items-center gap-2 rounded-md bg-white px-3 py-2 text-xs font-bold text-slate-700 ring-1 ring-slate-200" key={teamTag}>
                      <input defaultChecked={index < 3} type="checkbox" />
                      {teamTag}
                    </label>
                  ))}
                </div>
              </div>
              <div className="rounded-md bg-slate-50 p-3 ring-1 ring-slate-100 lg:col-span-2">
                <div className="text-xs font-bold uppercase text-slate-500">Different tag reasons per person</div>
                <div className="mt-2 grid gap-2 md:grid-cols-2 xl:grid-cols-4">
                  {tagReasonPreviewRows.map(([staff, reason]) => (
                    <ProfileMini key={staff} label={staff} value={reason} />
                  ))}
                </div>
              </div>
            </div>
          </div>
          <div className="mt-5 rounded-lg border border-amber-200 bg-amber-50 p-4">
            <div className="text-base font-black text-amber-950">Notification settings</div>
            <div className="mt-3 grid gap-3 md:grid-cols-3 xl:grid-cols-4">
              <FilterSelect label="Notify tagged staff" onChange={() => undefined} options={["Yes", "No"]} value="Yes" />
              <FilterSelect label="Notification priority" onChange={() => undefined} options={["Normal", "High", "Urgent"]} value="High" />
              {["In-system notification", "Email placeholder", "Mobile app notification placeholder", "Dashboard task alert"].map((method, index) => (
                <label className="flex items-center gap-2 rounded-md bg-white p-3 text-sm font-bold text-slate-700 ring-1 ring-amber-100" key={method}>
                  <input defaultChecked={index === 0 || index === 3} type="checkbox" />
                  {method}
                </label>
              ))}
            </div>
            <div className="mt-3 rounded-md bg-white p-3 text-sm font-bold text-amber-900 ring-1 ring-amber-100">
              Suggested: notify tagged staff automatically because this entry is action required, high priority and linked to social services/rota follow-up.
            </div>
          </div>
          <div className="mt-5 rounded-lg bg-rose-50 p-4 text-sm font-bold text-rose-900 ring-1 ring-rose-100">
            Restricted tagging warning: This journal entry contains restricted information. The selected staff member may not have permission to view the full entry. Use &quot;Send limited task only&quot; where needed.
            <button className="ml-3 rounded-md bg-white px-3 py-2 text-xs font-black text-rose-800 ring-1 ring-rose-200" type="button">Send limited task only</button>
          </div>
          <div className="mt-4 grid gap-3 md:grid-cols-4">
            <ProfileMini label="Created by" value={currentDemoUser.name} />
            <ProfileMini label="Role" value={currentDemoUser.role} />
            <ProfileMini label="Staff/user ID" value="USER-DEMO-CC-001" />
            <ProfileMini label="Entry ID" value="JRN-DEMO-0005" />
            <ProfileMini label="Client ID" value={selectedUser.id} />
            <ProfileMini label="Source module" value="Client Journal" />
            <ProfileMini label="Device/source" value="Office web app placeholder" />
            <ProfileMini label="Audit reference" value="AUD-JRN-0005" />
          </div>
          <div className="mt-4 flex flex-wrap gap-2">
            <button className="rounded-md bg-teal-600 px-4 py-2 text-sm font-bold text-white" onClick={() => { setSavedEntry(true); setShowForm(false); }} type="button">Save Journal Entry</button>
            <button className="rounded-md bg-slate-100 px-4 py-2 text-sm font-bold text-slate-700" type="button">Upload email/document placeholder</button>
          </div>
        </Card>
      ) : null}

      {showAiAssist ? (
        <Card>
          <SectionTitle action={<button className="rounded-md border border-slate-200 px-3 py-2 text-xs font-bold text-slate-700" onClick={() => setShowAiAssist(false)} type="button">Close AI assist</button>} subtitle="Prototype placeholder only. AI-generated notes must be reviewed and approved by the care coordinator before saving." title="AI Voice Note Assist" />
          <div className="rounded-lg bg-amber-50 p-3 text-sm font-bold text-amber-900 ring-1 ring-amber-200">AI draft must be checked by the user before saving. The final saved journal entry is the responsibility of the person approving it.</div>
          <div className="mt-4 flex flex-wrap gap-2">
            {["Start voice note placeholder", "Stop recording placeholder", "Generate journal draft", "Review before saving", "Save approved journal entry"].map((button, index) => (
              <button className={`rounded-md px-3 py-2 text-xs font-bold ${index === 4 ? "bg-teal-600 text-white" : "bg-slate-100 text-slate-700"}`} key={button} type="button">{button}</button>
            ))}
          </div>
          <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">
            {[
              ["Suggested type", "Telephone call from family"],
              ["Subject", "Lunch call time change request"],
              ["Person contacted", "Family member"],
              ["Action required", "Yes"],
              ["Action type", "Rota update required"],
              ["Priority", "Normal"],
              ["Suggested linked call/visit", "Lunch Call"],
              ["Draft note", "Family member called requesting lunch call time to be changed from 11:00 to 12:30 due to hospital appointment."]
            ].map(([label, value]) => <ProfileMini key={label} label={label} value={value} />)}
          </div>
        </Card>
      ) : null}

      <Card>
        <SectionTitle subtitle="Search journal text, contact name, subject, staff member or organisation. Filters are shown for the formal register." title="Journal list and filters" />
        <div className="grid gap-3 lg:grid-cols-[1fr_260px_260px]">
          <input className="rounded-md border border-slate-200 px-3 py-2 text-sm" placeholder="Search journal text, contact name, subject, staff member or organisation" />
          <FilterSelect label="Filter" onChange={() => undefined} options={journalFilters} value="All entries" />
          <FilterSelect label="Status" onChange={() => undefined} options={["Open", "Action required", "Awaiting response", "Completed", "Manager review", "Safeguarding review", "Closed"]} value="Open" />
        </div>
        <div className="mt-4 grid gap-3">
          {savedEntry ? (
            <JournalEntryCard entry={{ ...demoClientJournalEntries[0], id: "JRN-DEMO-0005", createdBy: currentDemoUser.name, role: currentDemoUser.role, mainActionOwner: currentUserLabel, taggedStaff: additionalTaggedOptions.slice(0, 4), witnessStaff: witnessTaggedOptions.slice(0, 3), createdAt: staffJournalTimestamp(), auditRef: "AUD-JRN-0005" }} onSelect={setSelectedEntryId} selected={selectedEntryId === "JRN-DEMO-0005"} />
          ) : null}
          {demoClientJournalEntries.map((entry) => <JournalEntryCard entry={entry} key={entry.id} onSelect={setSelectedEntryId} selected={selectedEntryId === entry.id} />)}
        </div>
      </Card>

      <div className="grid gap-6">
        <Card>
          <SectionTitle subtitle="Selected journal entry details, action tracking, linked actions, addendums and attachments." title="Selected journal entry" />
          <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
            <ProfileLine label="Entry ID" value={selectedEntry.id} />
            <ProfileLine label="Type" value={selectedEntry.type} />
            <ProfileLine label="Subject" value={selectedEntry.subject} />
            <div className="rounded-lg bg-white p-4 ring-1 ring-slate-200 md:col-span-2 xl:col-span-3">
              <div className="text-xs font-bold uppercase text-slate-500">Main note</div>
              <div className="mt-2 whitespace-pre-wrap text-base font-semibold leading-7 text-slate-900">{selectedEntry.note}</div>
            </div>
            <ProfileLine label="Created by" value={`${selectedEntry.createdBy} (${selectedEntry.role})`} />
            <ProfileLine label="Date/time" value={selectedEntry.createdAt} />
            <ProfileLine label="Contact" value={`${selectedEntry.contact} | ${selectedEntry.organisation}`} />
            <ProfileLine label="Main action owner" value={selectedEntry.mainActionOwner} />
            <ProfileLine label="Tagged staff" value={selectedEntry.taggedStaff.join(", ")} />
            <ProfileLine label="Witness / information only staff" value={selectedEntry.witnessStaff.join(", ")} />
            <ProfileLine label="Department/team tags" value={selectedEntry.departmentTags.join(", ")} />
            <ProfileLine label="Notifications sent" value={selectedEntry.notificationsSent} />
            <ProfileLine label="Who has seen it" value={selectedEntry.seenBy.join(", ") || "No one yet"} />
            <ProfileLine label="Who has responded" value={selectedEntry.respondedBy.join(", ") || "No response yet"} />
            <ProfileLine label="Who completed action" value={selectedEntry.completedBy} />
            <ProfileLine label="Completion date/time" value={selectedEntry.completionDateTime} />
            <ProfileLine label="Visibility" value={selectedEntry.visibility} />
            <ProfileLine label="Locked record" value="Yes - original entry cannot be edited or deleted" />
          </div>
          <div className="mt-4 flex flex-wrap gap-2">
            <button className="rounded-md bg-slate-100 px-3 py-2 text-xs font-bold text-slate-700" type="button">View locked entry</button>
            <button className="rounded-md bg-blue-50 px-3 py-2 text-xs font-bold text-blue-700 ring-1 ring-blue-100" onClick={() => setShowAddendum(true)} type="button">Add Addendum / Correction</button>
            <a className="rounded-md bg-teal-600 px-3 py-2 text-xs font-bold text-white" href={routeHref}>Create Rota Action</a>
            {reviewActionRequired ? <button className="rounded-md bg-amber-50 px-3 py-2 text-xs font-bold text-amber-800 ring-1 ring-amber-100" type="button">Create Care Plan Review Action</button> : null}
            {reviewActionRequired ? <button className="rounded-md bg-rose-50 px-3 py-2 text-xs font-bold text-rose-800 ring-1 ring-rose-100" type="button">Create Risk Assessment Review Action</button> : null}
          </div>
          {showAddendum ? (
            <div className="mt-4 rounded-lg bg-blue-50 p-4 ring-1 ring-blue-100">
              <div className="font-black text-blue-950">Addendum / Correction</div>
              <div className="mt-3 grid gap-3 md:grid-cols-2">
                <ProfileMini label="Linked original journal entry" value={selectedEntry.id} />
                <ProfileMini label="Addendum date/time" value="16 May 2026, 10:25" />
                <ProfileMini label="Added by" value={currentDemoUser.name} />
                <label className="block">
                  <span className="text-xs font-bold uppercase text-slate-500">Reason for correction</span>
                  <input className="mt-2 w-full rounded-md border border-slate-200 px-4 py-3 text-base" defaultValue="Clarify requested lunch call time" />
                </label>
                <label className="block md:col-span-2">
                  <span className="text-xs font-bold uppercase text-slate-500">Correction text</span>
                  <textarea className="mt-2 min-h-36 w-full rounded-lg border border-slate-200 px-4 py-3 text-base leading-7" defaultValue="Correction: requested time was 12:30, not 12:00. Original entry remains locked." />
                </label>
              </div>
            </div>
          ) : null}
        </Card>

        <Card>
          <SectionTitle subtitle="Every action-required journal entry carries ownership, status and evidence." title="Action tracker" />
          <div className="grid gap-3">
            <ProfileMini label="Action required" value={selectedEntry.actionRequired} />
            <ProfileMini label="Action type" value={selectedEntry.actionType} />
            <ProfileMini label="Assigned to" value={selectedEntry.assignedTo} />
            <ProfileMini label="Due date" value="16 May 2026" />
            <ProfileMini label="Status" value={actionCompleted ? "Completed" : selectedEntry.status} />
            <ProfileMini label="Completed by" value={actionCompleted ? currentDemoUser.name : "Not completed"} />
            <ProfileMini label="Completed date/time" value={actionCompleted ? "16 May 2026, 11:00" : "Pending"} />
            <ProfileMini label="Evidence attached" value={selectedEntry.attachment} />
          </div>
          <button className="mt-4 rounded-md bg-emerald-600 px-4 py-2 text-sm font-bold text-white" onClick={() => setActionCompleted(true)} type="button">Mark Action Complete</button>
        </Card>
      </div>

      <div className="grid gap-6 xl:grid-cols-2">
        <Card>
          <SectionTitle subtitle="Action-required tags create staff tasks linked to this client and journal entry." title="Tagged staff tasks" />
          <MedicationSimpleTable
            headings={["Linked client", "Linked journal entry", "Task title", "Action required", "Assigned to", "Due date", "Priority", "Status", "Created by", "Created date/time"]}
            rows={journalTaggedTaskRows}
            title="Task register"
          />
          <div className="mt-4 flex flex-wrap gap-2">
            {["Mark as Seen", "Add Response", "Mark In Progress", "Mark Completed", "Escalate", "Add Addendum"].map((button, index) => (
              <button className={`rounded-md px-3 py-2 text-xs font-bold ${index === 3 ? "bg-emerald-600 text-white" : index === 4 ? "bg-rose-50 text-rose-700 ring-1 ring-rose-100" : "bg-slate-100 text-slate-700"}`} key={button} type="button">{button}</button>
            ))}
          </div>
        </Card>
        <Card>
          <SectionTitle subtitle="Tagged staff have notification, opening, acknowledgement, response and completion status." title="Read receipts / acknowledgements" />
          <MedicationSimpleTable
            headings={["Staff member", "Tag type", "Tag reason", "Notified", "Opened", "Acknowledged", "Responded", "Status"]}
            rows={journalReadReceiptRows}
            title="Acknowledgement register"
          />
        </Card>
      </div>

      <Card>
        <SectionTitle subtitle="Tagged staff responses are locked once saved. The original journal entry remains unchanged." title="Response / addendum thread" />
        <MedicationSimpleTable headings={["Response type", "Added by", "Date/time", "Response note", "Status update", "Attachment"]} rows={journalResponseRows} title="Locked response thread" />
      </Card>

      <div className="grid gap-6 xl:grid-cols-2">
        <Card>
          <SectionTitle subtitle="Attachment records are linked to the journal entry and audit trail." title="Journal attachments" />
          <MedicationSimpleTable
            headings={["File name", "File type", "Uploaded by", "Upload date/time", "Linked journal entry", "Restricted", "Visibility", "Audit log"]}
            rows={[
              ["social-services-review-email.pdf", "Email PDF", "Demo Senior Administrator", "16 May 2026 09:42", "JRN-DEMO-0002", "Yes", "Manager only", "Attachment uploaded/viewed audited"],
              ["district-nurse-note-placeholder.pdf", "Professional document", "Demo Care Coordinator", "15 May 2026 14:30", "JRN-DEMO-0003", "No", "Care team visible", "Attachment uploaded/viewed audited"],
              ["voice-note-transcript-placeholder.txt", "Voice note transcript", "Demo Care Coordinator", "16 May 2026 10:17", "JRN-DEMO-0001", "No", "Internal only", "Transcript upload audited"]
            ]}
            title="Attachment register"
          />
        </Card>
        <Card>
          <SectionTitle subtitle="Role-based access controls keep restricted entries away from unauthorised users." title="Journal permissions" />
          <div className="grid gap-2">
            {[
              ["Care Coordinator", "Add/view normal entries, add addendum, no delete/edit locked entries"],
              ["Registered Manager", "Full view, close entries, manager review, restrict visibility"],
              ["General Administrator", "General/admin entries only where permitted"],
              ["Medication Lead", "Medication-related journal entries and eMAR/MAR links"],
              ["Safeguarding Lead", "Safeguarding restricted entries and actions"],
              ["Care Worker / Family Portal", "No full journal; only approved notes/messages"],
              ["Auditor/Inspector", "Read-only evidence access where authorised and time-limited"]
            ].map(([role, rule]) => <ProfileMini key={role} label={role} value={rule} />)}
          </div>
        </Card>
      </div>

      <MedicationSimpleTable headings={["Date/time", "User", "Role", "Client", "Journal entry ID", "Action", "Reason/comment", "Device/source"]} rows={journalAuditRows} title="Journal audit log" />
      <MedicationSimpleTable headings={["Date/time", "Journal entry ID", "Client ID", "Created by", "Tagged staff member", "Tag reason", "Action owner", "Notification status", "Read/ack status", "Old value", "New value", "Reason/comment"]} rows={journalTagAuditRows} title="Journal tagging audit log" />
    </div>
  );
}

