function AllocationWizard({
  selectedUser,
  selectedCallType,
  setSelectedCallType,
  allocationMode,
  setAllocationMode,
  makePermanent,
  setMakePermanent,
  assignedStaff,
  setAssignedStaff,
  allocationConfirmed,
  setAllocationConfirmed
}: {
  selectedUser: (typeof rotaServiceUsers)[number];
  selectedCallType: string;
  setSelectedCallType: (callType: string) => void;
  allocationMode: "Single carer" | "Double-up";
  setAllocationMode: (mode: "Single carer" | "Double-up") => void;
  makePermanent: boolean;
  setMakePermanent: (checked: boolean) => void;
  assignedStaff: string;
  setAssignedStaff: (staff: string) => void;
  allocationConfirmed: boolean;
  setAllocationConfirmed: (confirmed: boolean) => void;
}) {
  return (
    <Card>
      <SectionTitle subtitle="A simplified workflow for creating one-off or permanent regular allocations." title="Allocation wizard" />
      <div className="grid gap-4 xl:grid-cols-[0.8fr_1.2fr]">
        <div className="space-y-4">
          <WizardStep number="1" title="Select service user" value={selectedUser.name} />
          <label className="block rounded-lg bg-slate-50 p-3">
            <span className="text-xs font-bold uppercase text-slate-500">2. Call type</span>
            <select className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm font-semibold" onChange={(event) => setSelectedCallType(event.target.value)} value={selectedCallType}>
              {["Morning Call", "Lunch Call", "Tea Call", "Bed Call", "Night Call", "Outreach", "Personal Care"].map((callType) => (
                <option key={callType}>{callType}</option>
              ))}
            </select>
          </label>
          <div className="rounded-lg bg-slate-50 p-3">
            <div className="text-xs font-bold uppercase text-slate-500">3. Date pattern</div>
            <div className="mt-2 grid gap-2 sm:grid-cols-3">
              {["One date", "Multiple dates", "Date range"].map((mode, index) => (
                <label className="flex items-center gap-2 rounded-md bg-white p-2 text-sm font-semibold ring-1 ring-slate-200" key={mode}>
                  <input defaultChecked={index === 2} name="service-user-date-pattern" type="radio" />
                  {mode}
                </label>
              ))}
            </div>
            <div className="mt-3 grid gap-2 sm:grid-cols-2">
              <input className="rounded-md border border-slate-200 px-3 py-2 text-sm" defaultValue="2026-05-18" type="date" />
              <input className="rounded-md border border-slate-200 px-3 py-2 text-sm" defaultValue="2026-06-18" type="date" />
            </div>
          </div>
          <div className="rounded-lg bg-slate-50 p-3">
            <div className="text-xs font-bold uppercase text-slate-500">4. Single carer or double-up</div>
            <div className="mt-2 flex flex-wrap gap-2">
              {(["Single carer", "Double-up"] as const).map((mode) => (
                <button
                  className={`rounded-md border px-3 py-2 text-sm font-bold ${allocationMode === mode ? "border-teal-500 bg-teal-50 text-teal-800" : "border-slate-200 bg-white"}`}
                  key={mode}
                  onClick={() => setAllocationMode(mode)}
                  type="button"
                >
                  {mode}
                </button>
              ))}
            </div>
          </div>
          <label className="flex items-center gap-2 rounded-lg bg-emerald-50 p-3 text-sm font-bold text-emerald-800 ring-1 ring-emerald-100">
            <input checked={makePermanent} onChange={(event) => setMakePermanent(event.target.checked)} type="checkbox" />
            Make this permanent regular allocation
          </label>
          <label className="block">
            <span className="text-xs font-bold uppercase text-slate-500">Reason/comment</span>
            <textarea className="mt-2 min-h-24 w-full rounded-md border border-slate-200 px-3 py-2 text-sm" defaultValue="Permanent rota allocation to improve continuity and reduce manual scheduling." />
          </label>
        </div>

        <div>
          <SectionTitle subtitle="5-7. Select suitable staff, assign, and optionally make permanent." title="Suitable staff list" />
          <div className="space-y-3">
            {suitableStaff.map((staffOption) => {
              const excluded = staffOption.preference === "Excluded";
              return (
                <div className={`rounded-lg border p-4 ${excluded ? "border-rose-200 bg-rose-50" : assignedStaff === staffOption.name ? "border-teal-300 bg-teal-50" : "border-slate-200 bg-white"}`} key={staffOption.name}>
                  <div className="flex flex-wrap items-start justify-between gap-3">
                    <div>
                      <div className="font-black text-slate-900">{staffOption.name}</div>
                      <div className="text-sm text-slate-500">
                        {staffOption.role} | {staffOption.locality}
                      </div>
                    </div>
                    <PillBadge tone={excluded ? "red" : staffOption.score === "97%" ? "green" : staffOption.score === "88%" ? "amber" : "blue"}>Score {staffOption.score}</PillBadge>
                  </div>
                  <div className="mt-3 grid gap-2 text-xs md:grid-cols-3">
                    <ProfileMini label="Availability" value={staffOption.availability} />
                    <ProfileMini label="Skills match" value={staffOption.skills} />
                    <ProfileMini label="Training" value={staffOption.training} />
                    <ProfileMini label="Weekly hours" value={staffOption.weeklyHours} />
                    <ProfileMini label="Overtime" value={staffOption.overtime} />
                    <ProfileMini label="Continuity" value={staffOption.continuity} />
                  </div>
                  <div className="mt-3 flex flex-wrap gap-2">
                    <PillBadge tone={staffOption.preference === "Excluded" ? "red" : staffOption.preference === "Regular" ? "green" : staffOption.preference === "Preferred" ? "teal" : "blue"}>{staffOption.preference}</PillBadge>
                    <button
                      className="rounded-md bg-[#0B1F3A] px-3 py-2 text-xs font-bold text-white disabled:cursor-not-allowed disabled:bg-slate-300"
                      disabled={excluded}
                      onClick={() => {
                        setAssignedStaff(staffOption.name);
                        setAllocationConfirmed(false);
                      }}
                      type="button"
                    >
                      Assign
                    </button>
                    <button
                      className="rounded-md border border-teal-200 bg-white px-3 py-2 text-xs font-bold text-teal-800 disabled:cursor-not-allowed disabled:text-slate-300"
                      disabled={excluded}
                      onClick={() => {
                        setAssignedStaff(staffOption.name);
                        setMakePermanent(true);
                        setAllocationConfirmed(false);
                      }}
                      type="button"
                    >
                      Make permanent
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      <div className="mt-5 grid gap-4 xl:grid-cols-[1fr_0.7fr]">
        <div className="rounded-lg bg-slate-50 p-4 ring-1 ring-slate-200">
          <div className="font-bold text-slate-900">8. Allocation checks</div>
          <div className="mt-3 grid gap-2 md:grid-cols-3">
            {["Conflicts checked", "Skills checked", "Training current", "Availability checked", "Travel placeholder checked", "Overtime checked"].map((check, index) => (
              <PillBadge key={check} tone={index === 5 && assignedStaff === "Demo Carer C" ? "amber" : "green"}>
                {check}
              </PillBadge>
            ))}
          </div>
          <div className="mt-3 rounded-md bg-amber-50 p-3 text-sm font-semibold text-amber-800 ring-1 ring-amber-100">
            Auto allocation rule: future visits use permanent staff first. If unavailable, CareVerity warns and suggests preferred carers, then float pool carers.
          </div>
        </div>
        <div className="rounded-lg bg-white p-4 ring-1 ring-slate-200">
          <div className="font-bold text-slate-900">9-10. Confirm allocation</div>
          <p className="mt-2 text-sm leading-6 text-slate-500">
            Selected: {assignedStaff} for {selectedCallType}. {allocationMode}. {makePermanent ? "Permanent allocation enabled." : "One-off allocation only."}
          </p>
          <button className="mt-4 w-full rounded-md bg-teal-600 px-4 py-2 text-sm font-bold text-white" onClick={() => setAllocationConfirmed(true)} type="button">
            Confirm allocation
          </button>
          {allocationConfirmed ? (
            <div className="mt-3 rounded-md bg-emerald-50 p-3 text-sm font-semibold text-emerald-800 ring-1 ring-emerald-200">
              Visits created in rota, Live ECM board and staff schedule. Audit record created for manager review.
            </div>
          ) : null}
        </div>
      </div>
    </Card>
  );
}

