function SystemSettingsPage({ initialSection = "Roles & Permissions" }: { initialSection?: string } = {}) {
  const [selectedSection, setSelectedSection] = useState(initialSection);
  const [medicationColour, setMedicationColour] = useState("#fecdd3");
  const [messageTypeName, setMessageTypeName] = useState("Safeguarding Concern");
  const [temporaryAccess, setTemporaryAccess] = useState(false);
  const [settingsSaved, setSettingsSaved] = useState(false);

  return (
    <div className="space-y-6">
      <Card>
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div>
            <h2 className="text-2xl font-black text-slate-900">System Settings</h2>
            <p className="mt-2 max-w-4xl text-sm leading-6 text-slate-500">
              Main account user configuration centre for organisation setup, role permissions, access hours, service types, finance, HR, medication, reports and audit-safe customisation without developer changes.
            </p>
            <div className="mt-4 flex flex-wrap gap-2">
              <PillBadge tone="green">System owner controls</PillBadge>
              <PillBadge tone="red">Sensitive changes require higher permission</PillBadge>
              <PillBadge tone="teal">Fake demo settings only</PillBadge>
            </div>
          </div>
          <div className="rounded-lg bg-slate-50 p-4 ring-1 ring-slate-200">
            <div className="text-xs font-bold uppercase text-slate-500">Settings areas</div>
            <div className="mt-1 text-3xl font-black text-slate-900">{systemSettingsSections.length}</div>
          </div>
        </div>
      </Card>

      <div className="grid gap-6 xl:grid-cols-[300px_1fr]">
        <Card className="xl:sticky xl:top-24 xl:self-start">
          <SectionTitle subtitle="Jump to a configuration area." title="Settings sections" />
          <div className="max-h-[720px] space-y-1 overflow-y-auto pr-1">
            {systemSettingsSections.map((section, index) => (
              <button
                className={`flex w-full items-center gap-2 rounded-md px-3 py-2 text-left text-sm font-semibold transition ${
                  selectedSection === section ? "bg-teal-50 text-teal-800 ring-1 ring-teal-200" : "text-slate-600 hover:bg-slate-50"
                }`}
                key={section}
                onClick={() => setSelectedSection(section)}
                type="button"
              >
                <span className="grid h-6 w-6 shrink-0 place-items-center rounded-md bg-white text-xs font-black text-slate-500 ring-1 ring-slate-200">{index + 1}</span>
                {section}
              </button>
            ))}
          </div>
        </Card>

        <div className="space-y-6">
          <Card>
            <SectionTitle
              action={
                <button className="rounded-md bg-[#0B1F3A] px-4 py-2 text-sm font-bold text-white" onClick={() => setSettingsSaved(true)} type="button">
                  Save settings change
                </button>
              }
              subtitle="Every save creates an audit record with old value, new value, changed by, reason, approval and safe rollback status."
              title={selectedSection}
            />
            <div className="grid gap-3 md:grid-cols-4">
              <SettingsStat label="Owner role" value="Full access" tone="green" />
              <SettingsStat label="Restricted fields" value={String(sensitivePermissionFields.length)} tone="red" />
              <SettingsStat label="Permission modules" value={String(permissionModules.length)} tone="teal" />
              <SettingsStat label="Audit status" value="Always on" tone="purple" />
            </div>
            {settingsSaved ? <div className="mt-4 rounded-md bg-emerald-50 p-3 text-sm font-semibold text-emerald-800 ring-1 ring-emerald-200">Demo settings change saved. Audit record queued for owner review.</div> : null}
          </Card>

          <div className="grid gap-6 xl:grid-cols-2">
            <SettingsListPanel title="1. Organisation Profile" subtitle="Provider identity, regulated service details, trading names and default governance owner." items={["Demo provider name", "Regulated activity placeholder", "CQC location ID placeholder", "Main account owner", "Default manager", "Organisation branding and document footer"]} />
            <LocationsSettingsPanel />
          </div>

          <ServiceUserAccountSettingsPanel />

          <div className="grid gap-6 xl:grid-cols-2">
            <SettingsListPanel title="4. Staff / HR Settings" subtitle="Staff file fields, document categories, locked notes and HR restricted access." items={["Core staff fields", "Sensitive NI and DBS masking", "Document upload categories", "Warning/disciplinary note restrictions", "Leave and absence triggers", "Locked record addendums"]} />
            <SettingsListPanel title="5. Recruitment Settings" subtitle="Application forms, stages, right-to-work, references, DBS and onboarding." items={hrRecruitmentSettingsRows.slice(1, 10)} />
          </div>

          <SettingsListPanel title="HR and Recruitment Detailed Settings" subtitle="Full owner configuration for staff files, recruitment stages, onboarding, probation, supervision, appraisal, absence and restricted HR access." items={hrRecruitmentSettingsRows} />

          <CallTypeSettingsPanel />

          <div className="grid gap-6 xl:grid-cols-2">
            <SettingsListPanel title="7. ECM and Live Board Settings" subtitle="Timing thresholds, wallboard display, late alerts and evidence requirements." items={["Permitted arrival window", "Late threshold", "Missed visit threshold", "Overstay tolerance", "High-risk earlier warning", "Wallboard alert layout", "ECM evidence fields"]} />
            <MedicationSettingsPanel medicationColour={medicationColour} setMedicationColour={setMedicationColour} />
          </div>

          <MessageTypeSettingsPanel messageTypeName={messageTypeName} setMessageTypeName={setMessageTypeName} />

          <div className="grid gap-6 xl:grid-cols-2">
            <FamilyPortalSettingsPanel />
            <ProfessionalContactsSettingsPanel />
          </div>

          <div className="grid gap-6 xl:grid-cols-2">
            <SettingsKeyValuePanel rows={financeSettingsRows} title="12. Finance and Invoicing Settings" />
            <SettingsListPanel title="13. Payroll Settings" subtitle="Payroll grouping, authorised users, overtime approvals and export controls." items={["Payroll groups", "Timesheet exception rules", "Overtime approval workflow", "Travel/mileage payroll export", "Payroll module working-hour restriction", "Payroll query message type"]} />
          </div>

          <div className="grid gap-6 xl:grid-cols-2">
            <SettingsListPanel title="14. E-Signature Settings" subtitle="Signature types, document version control, audit log and signed PDF export." items={esignSettingsRows} />
            <SettingsListPanel title="15. Reports and CQC Evidence Settings" subtitle="Templates, access controls, export permissions and scheduled report emails." items={reportSettingsRows} />
          </div>

          <SettingsListPanel title="16. Training and Compliance Settings" subtitle="Training matrix, expiry warnings, compliance tags and competency evidence." items={["Mandatory training matrix", "Specialist training catalogue", "Competency observations", "Policy acknowledgements", "DBS/Hillingdon Council training group tags", "Training expiry alerts", "Staff compliance report fields"]} />

          <RolePermissionSettingsPanel />
          <AccessTimeControlsPanel temporaryAccess={temporaryAccess} setTemporaryAccess={setTemporaryAccess} />

          <div className="grid gap-6 xl:grid-cols-2">
            <SettingsListPanel title="19. Security and Audit Settings" subtitle="Audit events, sensitive-field reveals, locked records and higher-level approval gates." items={["All views and edits audited", "Restricted field reveal audit", "Permission change approval", "Key safe visibility approval", "Payroll access approval", "HR warning access approval", "Rollback where safe"]} />
            <SettingsListPanel title="20. Notification Settings" subtitle="Alerts by role, tag, priority, channel and escalation time." items={["Tagged message notifications", "Late/missed visit alerts", "Medication escalation alerts", "Safeguarding manager alerts", "Blocked access manager alerts", "Report export notifications"]} />
          </div>

          <SettingsListPanel title="21. Data Retention / Archive Settings" subtitle="Retention periods, archive rules, restore permissions and deletion approvals." items={["Staff file retention placeholder", "Service user archive rules", "Finance retention rules", "Medication record retention", "Audit log retention", "Safe restore workflow", "Delete/archive permission approval"]} />

          <SettingsAuditPanel />
        </div>
      </div>
    </div>
  );
}

function SettingsStat({ label, value, tone }: { label: string; value: string; tone: Tone }) {
  return (
    <div className="rounded-md bg-slate-50 p-4 ring-1 ring-slate-100">
      <div className="text-xs font-bold uppercase text-slate-500">{label}</div>
      <div className="mt-2 text-xl font-black text-slate-900">{value}</div>
      <div className="mt-2">
        <PillBadge tone={tone}>Configured</PillBadge>
      </div>
    </div>
  );
}

function SettingsListPanel({ title, subtitle, items }: { title: string; subtitle: string; items: string[] }) {
  return (
    <Card>
      <SectionTitle subtitle={subtitle} title={title} />
      <div className="grid gap-2 md:grid-cols-2">
        {items.map((item) => (
          <label className="flex items-center gap-3 rounded-md bg-slate-50 p-3 text-sm font-semibold text-slate-700 ring-1 ring-slate-100" key={item}>
            <input defaultChecked type="checkbox" />
            {item}
          </label>
        ))}
      </div>
    </Card>
  );
}

function SettingsKeyValuePanel({ title, rows }: { title: string; rows: string[][] }) {
  return (
    <Card>
      <SectionTitle subtitle="Owner-editable settings with role-restricted access where needed." title={title} />
      <div className="space-y-3">
        {rows.map(([label, value]) => (
          <div className="rounded-md bg-slate-50 p-3 ring-1 ring-slate-100" key={label}>
            <div className="text-xs font-bold uppercase text-slate-500">{label}</div>
            <div className="mt-1 font-semibold text-slate-900">{value}</div>
          </div>
        ))}
      </div>
    </Card>
  );
}

