function roleModulePermissionLevel(role: string, module: string) {
  const seniorLeadershipRoles = ["System Owner", "Registered Manager", "Operations Manager", "Service Manager", "Branch Manager"];
  const deputyRoles = ["Deputy Manager"];
  const coordinationRoles = ["Care Coordinator", "Senior Care Coordinator", "Rota Coordinator", "On-call Coordinator", "Field Care Supervisor"];
  const adminRoles = ["Admin Manager", "Senior Administrator", "General Administrator", "Office Administrator", "Reception / Front Desk", "Records Administrator"];
  const hrRoles = ["HR Manager", "HR Administrator"];
  const recruitmentRoles = ["Recruitment Manager", "Recruitment Administrator"];
  const trainingRoles = ["Training Manager", "Training Administrator", "Training Coordinator"];
  const qualityRoles = ["Quality Assurance Manager", "Quality / Compliance Officer", "CQC Evidence Lead", "Audit Officer", "Governance Officer", "Data Protection Lead", "Information Governance Lead"];
  const financeRoles = ["Finance Manager", "Finance Administrator", "Invoicing Officer"];
  const payrollRoles = ["Payroll Manager", "Payroll Officer"];
  const careRoles = ["Care Worker", "Care Worker / Mobile User", "Permanent Care Worker", "One-off / Emergency Cover Care Worker", "Outreach Care Worker", "Additional Care Worker", "Additional Outreach Care Worker", "Float Pool Care Worker", "Medication-Authorised Care Worker", "Senior Care Worker"];
  const specialistRoles = ["Medication Lead", "Safeguarding Lead", "Moving and Handling Lead", "Infection Control Lead", "Health and Safety Lead"];
  const externalReadOnlyRoles = ["Auditor / Inspector Read-Only", "Read-Only Auditor / Inspector View", "NHS / ICB Read-Only", "Local Authority Read-Only"];

  if (role === "System Owner") return "Full access";
  if (seniorLeadershipRoles.includes(role)) return /System Settings/.test(module) && role !== "Registered Manager" ? "Manager approval required" : "Full access";
  if (deputyRoles.includes(role)) return /System Settings|Finance \/ Payroll|View bank\/payroll details|System Owner/i.test(module) ? "Manager approval required" : "Add and edit all records";
  if (coordinationRoles.includes(role)) {
    if (/Finance|Payroll|System Settings|HR \/ Staff Files|Medication/i.test(module)) return "No access";
    if (/Rota|Live ECM|Service User/i.test(module)) return "Add and edit all records";
    return "Add and edit own records";
  }
  if (adminRoles.includes(role)) return /System Settings|Finance|Payroll|DBS|Right to Work|National Insurance|bank\/payroll|HR Notes|Safeguarding/i.test(module) ? "No access" : /Dashboard|Service User|Reports|Family|Rota/i.test(module) ? "Add only" : "View only";
  if (hrRoles.includes(role)) return /HR|Add Staff|Edit Staff|DBS|Right to Work|National Insurance|Recruitment|Training Matrix|Certificates/i.test(module) ? "Restricted sensitive access" : /Service User|Live ECM|Finance|Payroll|Safeguarding/i.test(module) ? "No access" : "View only";
  if (recruitmentRoles.includes(role)) return /Recruitment|Add Staff|Right to Work|DBS/i.test(module) ? "Add and edit own records" : /HR|Training Matrix|Certificates/i.test(module) ? "View only" : "No access";
  if (trainingRoles.includes(role)) return /Training Academy|Training Matrix|Certificates/i.test(module) ? "Add and edit all records" : /HR/.test(module) ? "View only" : /Finance|Payroll|Service User|Safeguarding/i.test(module) ? "No access" : "View only";
  if (qualityRoles.includes(role)) return /Reports|CQC Evidence|Data Protection|Article 32|Audit|Client journal|Service User|Live ECM|Medication|Training Matrix/i.test(module) ? "Restricted sensitive access" : /Finance|Payroll|bank\/payroll/i.test(module) ? "No access" : "View only";
  if (financeRoles.includes(role)) return /Finance|Invoicing|Export|Print|Download/i.test(module) ? "Add and edit all records" : /Service User/.test(module) ? "View only" : /HR|Medication|Safeguarding|DBS|Right to Work/i.test(module) ? "No access" : "View only";
  if (payrollRoles.includes(role)) return /Payroll|Finance|View bank\/payroll details|Export|Print|Download/i.test(module) ? "Restricted sensitive access" : /Live ECM|Rota/.test(module) ? "View only" : /HR|Service User|Safeguarding|Medication/i.test(module) ? "No access" : "View only";
  if (role === "Medication Lead") return /Medication/.test(module) ? "Restricted sensitive access" : /Service User|Live ECM|Reports|Client journal/.test(module) ? "View only" : /Finance|Payroll|HR/.test(module) ? "No access" : "View only";
  if (role === "Safeguarding Lead") return /Reports|Service User|Client journal|CQC Evidence/i.test(module) ? "Restricted sensitive access" : /Finance|Payroll|System Settings/i.test(module) ? "No access" : "View only";
  if (specialistRoles.includes(role)) return /Service User|Training Matrix|Reports|Live ECM|Rota/i.test(module) ? "Add and edit own records" : /Finance|Payroll|System Settings|HR/i.test(module) ? "No access" : "View only";
  if (careRoles.includes(role)) return /Rota|Service User|Live ECM/i.test(module) ? "Add and edit own records" : /Training Academy|Certificates/i.test(module) ? "View only" : "No access";
  if (role === "Family Portal User") return module === "Family Portal" ? "View only" : "No access";
  if (externalReadOnlyRoles.includes(role)) return /Finance|Payroll|System Settings|Add Staff|Add Service User|Edit/i.test(module) ? "No access" : "View only";
  return "View only";
}

function permissionTone(level: string): Tone {
  if (level === "Full access") return "green";
  if (level === "No access") return "red";
  if (level === "Restricted sensitive access") return "purple";
  if (level === "Manager approval required") return "amber";
  if (level === "View only") return "slate";
  return "blue";
}

