function ReportCqcMappingPanel({ mappings }: { mappings: string[] }) {
  return (
    <Card>
      <SectionTitle subtitle="Records are mapped into inspection-ready evidence groups." title="CQC key question mapping" />
      <div className="flex flex-wrap gap-2">
        {mappings.map((mapping) => <PillBadge key={mapping} tone={mapping === "Safe" ? "red" : mapping === "Well-led" ? "blue" : mapping === "Responsive" ? "amber" : "teal"}>{mapping}</PillBadge>)}
      </div>
    </Card>
  );
}

function ReportGovernancePanel({ activeReport }: { activeReport: GovernanceReportView }) {
  if (activeReport === "Complaints Tracker & Analysis") return <ComplaintsTrackerPanel />;
  if (activeReport === "Incident / Accident Tracker & Analysis") return <IncidentAccidentTrackerPanel />;
  if (activeReport === "RIDDOR Reportability Review") return <RiddorReportabilityPanel />;
  if (activeReport === "Safeguarding Tracker & Analysis") return <SafeguardingTrackerPanel />;
  if (activeReport === "Lessons Learned / Outcomes Report") return <LessonsLearnedPanel />;
  if (activeReport === "Monthly Governance Report") return <MonthlyGovernanceReportPanel />;
  if (activeReport === "CQC Evidence Reports") return <CqcEvidenceReportsPanel />;
  if (activeReport === "KPI Trend Reports") return <KpiTrendReportsPanel />;
  if (activeReport === "Service User Risk Trend Reports") return <ServiceUserRiskTrendReportsPanel />;
  if (activeReport === "Staff / HR Compliance Reports") return <StaffHrComplianceReportsPanel />;
  if (activeReport === "Training Compliance Reports") return <TrainingComplianceReportsPanel />;
  if (activeReport === "Notifications to Professionals Report") return <NotificationsToProfessionalsPanel />;
  if (activeReport === "Export Centre") return <ExportCentrePanel />;
  if (activeReport === "Report Templates / Settings") return <ReportTemplatesSettingsPanel />;
  return <ReportsDashboardPanel />;
}

