function KpiTrendCard({ label, current, previous, change, trend, tone }: { label: string; current: string; previous: string; change: string; trend: string; tone: Tone }) {
  return (
    <Card className="p-4">
      <div className="text-xs font-bold uppercase text-slate-500">{label}</div>
      <div className="mt-2 flex items-end justify-between gap-3">
        <div className="text-2xl font-black text-slate-900">{current}</div>
        <TrendArrow trend={trend} />
      </div>
      <div className="mt-2 text-xs text-slate-500">Previous period: {previous}</div>
      <div className="mt-3"><PillBadge tone={tone}>{change}</PillBadge></div>
    </Card>
  );
}

function TrendArrow({ trend }: { trend: string }) {
  const symbol = trend === "up" ? "↑" : trend === "down" ? "↓" : "→";
  const tone = trend === "up" ? "text-emerald-600" : trend === "down" ? "text-rose-600" : "text-slate-500";
  return <span className={`text-2xl font-black ${tone}`}>{symbol}</span>;
}

function LineChart({ title, labels, series }: { title: string; labels: string[]; series: Array<[string, number[]]> }) {
  const max = Math.max(...series.flatMap((item) => item[1]));
  return (
    <Card>
      <SectionTitle subtitle="Line chart using fake demo trend data." title={title} />
      <svg className="h-56 w-full" role="img" viewBox="0 0 420 180">
        {series.map(([name, values], seriesIndex) => {
          const points = values.map((value, index) => `${20 + index * (380 / Math.max(values.length - 1, 1))},${160 - (value / max) * 130}`).join(" ");
          const colour = ["#0e9aa7", "#f59e0b", "#dc2626"][seriesIndex] ?? "#334155";
          return <polyline fill="none" key={name} points={points} stroke={colour} strokeWidth="4" />;
        })}
      </svg>
      <div className="flex flex-wrap gap-2">{series.map(([name]) => <PillBadge key={name} tone="teal">{name}</PillBadge>)}</div>
      <div className="mt-3 grid grid-cols-3 gap-2 text-xs text-slate-500">{labels.map((label) => <span key={label}>{label}</span>)}</div>
    </Card>
  );
}

function SimpleBarChart({ title, labels, values }: { title: string; labels: string[]; values: number[] }) {
  const max = Math.max(...values);
  return (
    <Card>
      <SectionTitle subtitle="Bar chart using fake demo trend data." title={title} />
      <div className="space-y-3">
        {labels.map((label, index) => (
          <div key={label}>
            <div className="mb-1 flex justify-between text-sm"><span className="font-semibold text-slate-700">{label}</span><span className="font-bold">{values[index]}</span></div>
            <div className="h-3 rounded-full bg-slate-100"><div className="h-3 rounded-full bg-teal-500" style={{ width: `${(values[index] / max) * 100}%` }} /></div>
          </div>
        ))}
      </div>
    </Card>
  );
}

function GroupedBarChart({ title, labels, values }: { title: string; labels: string[]; values: number[] }) {
  return <SimpleBarChart labels={labels} title={title} values={values} />;
}

function StackedBarChart({ title, labels, values }: { title: string; labels: string[]; values: number[] }) {
  const total = values.reduce((sum, value) => sum + value, 0);
  return (
    <Card>
      <SectionTitle subtitle="Stacked bar breakdown using fake demo data." title={title} />
      <div className="flex h-8 overflow-hidden rounded-full bg-slate-100">
        {values.map((value, index) => <div className={["bg-teal-500", "bg-blue-500", "bg-amber-500", "bg-rose-500", "bg-purple-500", "bg-slate-500"][index]} key={labels[index]} style={{ width: `${(value / total) * 100}%` }} />)}
      </div>
      <div className="mt-4 grid gap-2 md:grid-cols-2">{labels.map((label, index) => <div className="flex justify-between rounded-md bg-slate-50 p-2 text-sm" key={label}><span>{label}</span><b>{values[index]}</b></div>)}</div>
    </Card>
  );
}

function DonutChart({ title, labels, values }: { title: string; labels: string[]; values: number[] }) {
  return (
    <Card>
      <SectionTitle subtitle="Donut-style summary using accessible labels." title={title} />
      <div className="grid place-items-center">
        <div className="grid h-40 w-40 place-items-center rounded-full bg-[conic-gradient(#10b981_0_72%,#f59e0b_72%_90%,#ef4444_90%_100%)]">
          <div className="grid h-24 w-24 place-items-center rounded-full bg-white text-xl font-black">{values[0]}%</div>
        </div>
      </div>
      <div className="mt-4 grid gap-2">{labels.map((label, index) => <div className="flex justify-between text-sm" key={label}><span>{label}</span><b>{values[index]}%</b></div>)}</div>
    </Card>
  );
}

const hillingdonExportFields = {
  "Actual Call Data": ["Provider_ID", "Call_ID", "Carer_ID", "Call_Start_Datetime", "Call_End_Datetime", "Client_ID", "Log_In_Phone_No", "Log_Out_Phone_No", "Log_In GPS Location", "Log_Out GPS Location", "Log_In_Call_Origination", "Log_Out_Call_Origination", "Is_Frustrated", "Frustrated_Reason", "Cancelled", "ScheduleID"],
  "Schedule Call Data": ["ProviderID", "ScheduleID", "CarerID", "ClientID", "Schedule_Start_Datetime", "Schedule_End_Datetime", "Service Type", "Cancelled"],
  "Carer Data": ["CarerID", "ProviderID", "CarerName", "CarerGrade", "Active"],
  "Client Data": ["ClientID", "ProviderID", "ClientName", "Client Phone Number", "Clients Primary GPS Location", "Active"]
};

function HillingdonEcmExportPage() {
  const [selectedExport, setSelectedExport] = useState("Actual Call Data");
  const fields = hillingdonExportFields[selectedExport as keyof typeof hillingdonExportFields];
  const csvPreview = fields.join(",") + "\n" + fields.map((field) => `${field}_DEMO`).join(",");
  const xmlPreview = `<${selectedExport.replaceAll(" ", "_")}>\n${fields.map((field) => `  <${field.replaceAll(" ", "_")}>${field}_DEMO</${field.replaceAll(" ", "_")}>`).join("\n")}\n</${selectedExport.replaceAll(" ", "_")}>`;
  return (
    <div className="space-y-6">
      <Card>
        <SectionTitle subtitle="Export-ready integration workspace based on the uploaded Hillingdon ECM field list provided in the request." title="Hillingdon ECM Export / Integration" />
        <div className="grid gap-3 md:grid-cols-4">
          <ProfileMini label="Provider ID setting" value="DEMO-PROVIDER-001" />
          <ProfileMini label="Last successful export time" value="13 May 2026 18:30" />
          <ProfileMini label="Receipt status" value="Demo accepted" />
          <ProfileMini label="Latency monitoring" value="1.8s demo average" />
        </div>
      </Card>
      <div className="grid gap-6 xl:grid-cols-[0.8fr_1.2fr]">
        <Card>
          <SectionTitle subtitle="Select export type and run export placeholders." title="Export controls" />
          <FilterSelect label="Export-ready section" onChange={setSelectedExport} options={Object.keys(hillingdonExportFields)} value={selectedExport} />
          <div className="mt-4 grid gap-2">
            {["Export actual call data", "Export schedule call data", "Export carer data", "Export client data", "Retry export", "Backup/failover placeholder"].map((action) => <button className="rounded-md bg-[#0B1F3A] px-4 py-2 text-sm font-bold text-white" key={action} type="button">{action}</button>)}
          </div>
          <div className="mt-4 flex flex-wrap gap-2">
            {["LA-funded and self-funded visit identification", "Service level identification", "ISO 9001 readiness", "ISO 27001 readiness", "Mapping settings"].map((item) => <PillBadge key={item} tone="teal">{item}</PillBadge>)}
          </div>
        </Card>
        <Card>
          <SectionTitle subtitle="CSV and XML previews use fake demo values only." title={`${selectedExport} preview`} />
          <div className="grid gap-4 lg:grid-cols-2">
            <pre className="max-h-80 overflow-auto rounded-md bg-slate-950 p-4 text-xs text-white">{csvPreview}</pre>
            <pre className="max-h-80 overflow-auto rounded-md bg-slate-950 p-4 text-xs text-white">{xmlPreview}</pre>
          </div>
        </Card>
      </div>
      <Card>
        <SectionTitle subtitle="Field mapping for Actual Call, Schedule Call, Carer and Client data." title="Hillingdon field mapping settings" />
        <div className="grid gap-4 xl:grid-cols-2">
          {Object.entries(hillingdonExportFields).map(([section, sectionFields]) => (
            <div className="rounded-lg border border-slate-200 p-4" key={section}>
              <h3 className="font-black text-slate-900">{section}</h3>
              <div className="mt-3 flex flex-wrap gap-2">{sectionFields.map((field) => <PillBadge key={field} tone="blue">{field}</PillBadge>)}</div>
            </div>
          ))}
        </div>
      </Card>
      <div className="grid gap-6 xl:grid-cols-2">
        <MedicationSimpleTable headings={["Date/time", "Export", "Rows", "Status", "Receipt"]} rows={[["13 May 2026 18:30", "Actual Call Data", "128", "Successful", "Demo receipt accepted"], ["13 May 2026 18:35", "Schedule Call Data", "144", "Successful", "Demo receipt accepted"]]} title="Export history" />
        <MedicationSimpleTable headings={["Failed export", "Reason", "Retry status", "Owner"]} rows={[["Carer Data", "Demo validation warning", "Queued for retry", "Demo Integration Admin"], ["Client Data", "Demo missing GPS placeholder", "Awaiting mapping review", "Demo System Owner"]]} title="Failed export queue" />
      </div>
    </div>
  );
}

