function getCertificateEvidenceBadges(settings: CertificateBadgeSettings) {
  const hasCpdEvidence = settings.showCpdBadge && settings.cpdReference.trim().length > 0;
  const hasIsoEvidence = settings.showIsoBadge && settings.isoCertificateNumber.trim().length > 0;

  return [
    hasCpdEvidence ? ["CPD", "Professional Development", "Verification Required", settings.cpdReference] : null,
    hasIsoEvidence ? ["ISO 9001", "Quality Management", "Certificate Ref Required", settings.isoCertificationBody.trim() ? `${settings.isoCertificateNumber} / ${settings.isoCertificationBody}` : settings.isoCertificateNumber] : null
  ].filter((badge): badge is string[] => Boolean(badge));
}

