function displayTrainingDate(value: string) {
  const [year, month, day] = value.split("-");
  if (!year || !month || !day) return value;
  const monthName = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][Number(month) - 1] ?? month;
  return `${day} ${monthName} ${year}`;
}

function staffProfileForTraining(name: string) {
  return demoTrainingStaffProfiles.find((profile) => profile.name === name) ?? {
    name,
    ref: staff.find((member) => member.name === name)?.ref ?? "CV-DEMO-EMP-UNKNOWN",
    role: staff.find((member) => member.name === name)?.role ?? "Care Worker",
    departmentTeam: "Demo team"
  };
}

function staffSlugFromName(name: string) {
  const member = staff.find((staffMember) => staffMember.name === name);
  if (member) return staffSlug(member);
  return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function resolveTrainingAssignmentTargets(form: TrainingAssignmentFormState) {
  if (form.assignmentType === "Individual staff member") return form.selectedStaff ? [form.selectedStaff] : [];
  if (form.assignmentType === "Multiple selected staff") return form.selectedStaffMembers;
  if (form.assignmentType === "Staff role") return demoTrainingStaffProfiles.filter((profile) => profile.role === form.role || profile.role.includes(form.role)).map((profile) => profile.name);
  if (form.assignmentType === "All care workers") return demoTrainingStaffProfiles.filter((profile) => /care worker/i.test(profile.role)).map((profile) => profile.name);
  if (form.assignmentType === "All admin staff") return demoTrainingStaffProfiles.filter((profile) => /administrator|coordinator/i.test(profile.role)).map((profile) => profile.name);
  if (form.assignmentType === "All managers") return demoTrainingStaffProfiles.filter((profile) => /manager/i.test(profile.role)).map((profile) => profile.name);
  if (form.assignmentType === "New starters") return ["Demo Care Worker B"];
  if (form.assignmentType === "Staff with expiring training") return ["Demo Care Worker A", "Demo Care Worker B"];
  return [];
}

function makeTrainingAssignmentRecord(form: TrainingAssignmentFormState, staffName: string, index: number): TrainingAssignmentRecord {
  const profile = staffProfileForTraining(staffName);
  const timestamp = new Date().toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" });
  return {
    id: `training-assignment-${Date.now()}-${index}`,
    staff: staffName,
    staffRef: profile.ref,
    staffRole: profile.role,
    departmentTeam: form.departmentTeam || profile.departmentTeam,
    course: form.course,
    assignmentType: form.assignmentType,
    status: "Assigned",
    assignedDate: form.assignedDate,
    dueDate: form.dueDate,
    mandatory: form.mandatory,
    priority: form.priority,
    completionRule: form.completionRule,
    certificateRequired: form.certificateRequired,
    certificateStatus: form.certificateRequired === "Yes" ? "Pending completion" : "Not required",
    reminderFrequency: form.reminderFrequency,
    assignedBy: form.assignedBy,
    notes: form.notes,
    connectedOutcome: "Appears in staff file, My Training and Training Matrix",
    auditDateTime: timestamp,
    auditReference: `TRAIN-AUD-${Date.now()}-${index + 1}`
  };
}

function readDemoTrainingAssignments() {
  return readLocalJson<TrainingAssignmentRecord[]>(demoStoreKeys.trainingAssignments, defaultTrainingAssignmentRecords);
}

function writeDemoTrainingAssignments(records: TrainingAssignmentRecord[]) {
  writeLocalJson(demoStoreKeys.trainingAssignments, records);
  if (typeof window !== "undefined") window.dispatchEvent(new Event("careverity-training-assignments-updated"));
}

function useDemoTrainingAssignments() {
  const [records, setRecords] = useState<TrainingAssignmentRecord[]>(defaultTrainingAssignmentRecords);

  useEffect(() => {
    const syncRecords = () => setRecords(readDemoTrainingAssignments());
    syncRecords();
    window.addEventListener("storage", syncRecords);
    window.addEventListener("careverity-training-assignments-updated", syncRecords);
    return () => {
      window.removeEventListener("storage", syncRecords);
      window.removeEventListener("careverity-training-assignments-updated", syncRecords);
    };
  }, []);

  return records;
}

