              {["Certificate number", "Staff name", "Course title", "Issue date", "Expiry/update date", "Trainer name", "Template used", "Generated by", "Status", "Staff file link", "Audit log", "Actions"].map((heading) => <th className="p-3" key={heading}>{heading}</th>)}
