function InformationGovernanceForm({ title, rows }: { title: string; rows: string[][] }) {
  return (
    <Card>
      <SectionTitle subtitle="Demo form template with role-based access and audit-ready fields." title={title} />
      <div className="grid gap-3 md:grid-cols-2">
        {rows.map(([label, value]) => (
          <label className={value.length > 80 ? "block md:col-span-2" : "block"} key={label}>
            <span className="text-xs font-black uppercase text-slate-500">{label}</span>
            <input className="mt-1 w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-sm font-semibold text-slate-800" defaultValue={value} />
          </label>
        ))}
      </div>
      <div className="mt-4 flex flex-wrap gap-2">
        {["Save record", "Manager sign-off", "Export PDF placeholder", "Audit log"].map((action, index) => (
          <button className={`rounded-md px-3 py-2 text-xs font-bold ${index === 0 ? "bg-teal-600 text-white" : "bg-slate-50 text-slate-700 ring-1 ring-slate-200"}`} key={action} type="button">{action}</button>
        ))}
      </div>
    </Card>
  );
}

function BackupExportImportPage() {
  const importInputRef = useRef<HTMLInputElement>(null);
  const [statusMessage, setStatusMessage] = useState("Ready to export or import CareVerity demo data.");
  const [lastPayload, setLastPayload] = useState(() => buildCareVerityBackupPayload("full"));

  const refreshPayload = (scope: CareVerityBackupScope) => {
    const payload = buildCareVerityBackupPayload(scope);
    setLastPayload(payload);
    return payload;
  };

  const exportJson = (scope: CareVerityBackupScope, label: string) => {
    const payload = refreshPayload(scope);
    appendBackupAudit(label, `Exported ${scope} JSON backup with ${Object.keys(payload.localStorage).length} CareVerity local-storage keys.`);
    const json = JSON.stringify(payload, null, 2);
    const blob = new Blob([json], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-");
    anchor.href = url;
    anchor.download = `CareVerity_${scope}_backup_${stamp}.json`;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    URL.revokeObjectURL(url);
    setStatusMessage(`${label} created and download started.`);
  };

  const restoreBackupPayload = (payload: Record<string, unknown>) => {
    const localStorageSnapshot = payload.localStorage;
    if (typeof window !== "undefined" && localStorageSnapshot && typeof localStorageSnapshot === "object" && !Array.isArray(localStorageSnapshot)) {
      Object.entries(localStorageSnapshot as Record<string, unknown>).forEach(([key, value]) => {
        if (key.startsWith("careverity-") && typeof value === "string") {
          window.localStorage.setItem(key, value);
        }
      });
    }

    if (Array.isArray(payload.staffFiles)) {
      writeLocalJson(demoStoreKeys.staff, payload.staffFiles as StaffMember[]);
    }
    if (Array.isArray(payload.serviceUserFiles)) {
      writeLocalJson(demoStoreKeys.clients, payload.serviceUserFiles as ServiceUserRecord[]);
    }
    const callPackages = payload.callPackages as { savedCallPackages?: Record<string, RotaCallCard[]> } | undefined;
    if (callPackages?.savedCallPackages && typeof callPackages.savedCallPackages === "object") {
      writeLocalJson(demoStoreKeys.calls, callPackages.savedCallPackages);
    }
    const rotaAllocations = payload.rotaAllocations as { savedAllocations?: DemoAllocationRecord[] } | undefined;
    if (Array.isArray(rotaAllocations?.savedAllocations)) {
      writeLocalJson(demoStoreKeys.allocations, rotaAllocations.savedAllocations);
    }

    appendBackupAudit("Import CareVerity Demo Data", "Imported JSON backup into local prototype storage.");
    setLastPayload(buildCareVerityBackupPayload("full"));
    setStatusMessage("Import complete. Demo data has been restored into this browser's local storage. Refresh or reopen modules to see the restored state.");
  };

  const handleImportFile = (file: File | undefined) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const parsed = JSON.parse(String(reader.result)) as Record<string, unknown>;
        restoreBackupPayload(parsed);
      } catch {
        setStatusMessage("Import failed. Please choose a valid CareVerity JSON backup file.");
      }
    };
    reader.readAsText(file);
  };

  const loadDemoSeedData = async () => {
    try {
      const response = await fetch("/demo-data/careverity-demo-seed.json", { cache: "no-store" });
      if (!response.ok) {
        throw new Error("Seed file unavailable");
      }
      const payload = (await response.json()) as Record<string, unknown>;
      restoreBackupPayload(payload);
      appendBackupAudit("Load Demo Seed Data", "Reloaded saved demo seed data from /public/demo-data/careverity-demo-seed.json.");
      setStatusMessage("Demo seed data loaded from the project file. Refresh or reopen modules to see the seeded state.");
    } catch {
      setStatusMessage("Could not load the demo seed file. Check /public/demo-data/careverity-demo-seed.json exists in the workspace.");
    }
  };

  const resetDemoData = () => {
    if (typeof window !== "undefined") {
      [demoStoreKeys.staff, demoStoreKeys.clients, demoStoreKeys.calls, demoStoreKeys.allocations, demoStoreKeys.visit, demoStoreKeys.visitAudit, demoStoreKeys.lastExport, demoStoreKeys.status].forEach((key) => window.localStorage.removeItem(key));
    }
    appendBackupAudit("Reset Demo Data", "Cleared CareVerity demo staff, service users, call packages, allocations and workflow status from local storage.");
    setLastPayload(buildCareVerityBackupPayload("full"));
    setStatusMessage("Demo data reset. Built-in baseline demo records remain available in the prototype.");
  };

  const summaryRows = [
    ["Staff files", String(lastPayload.staffFiles.length)],
    ["Service user files", String(lastPayload.serviceUserFiles.length)],
    ["Saved call-package groups", String(Object.keys(lastPayload.callPackages.savedCallPackages ?? {}).length)],
    ["Saved rota allocations", String(lastPayload.rotaAllocations.savedAllocations?.length ?? 0)],
    ["Training courses", String(lastPayload.trainingAcademyData.courses?.length ?? 0)],
    ["Certificate records", String(lastPayload.certificates.records?.length ?? 0)],
    ["Roles", String(lastPayload.rolesAndPermissions.roles?.length ?? 0)],
    ["CareVerity local-storage keys", String(Object.keys(lastPayload.localStorage).length)]
  ] satisfies Array<[string, string]>;

  const auditRows = readLocalJson<Array<{ action: string; detail: string; dateTime: string; user: string }>>(demoStoreKeys.backupAudit, []).slice(0, 8);
  const databaseStatus = getCareVerityDatabaseStatus();
  const databaseExportRows = [
    ["Demo local export", "Available now via browser localStorage JSON"],
    ["Database export placeholder", databaseStatus.supabaseConfigured ? "Ready to connect to Supabase provider exports" : "Waiting for Supabase env keys"],
    ["Provider-specific export", "Must filter by company_id/provider_id"],
    ["Staff export", "Role-controlled HR/System Owner export"],
    ["Service user export", "Role-controlled manager/coordinator export"],
    ["Audit export", "Read-only auditor/system owner export"],
    ["Import history export", "Company import batch report from company_import_batches"]
  ] satisfies Array<[string, string]>;

  return (
    <div className="space-y-6">
      <Card className="border-l-4 border-l-teal-500">
        <SectionTitle
          action={<PillBadge tone="teal">Prototype migration tool</PillBadge>}
          subtitle="Export, import, reset and migrate CareVerity ECM prototype data stored in this browser's local storage."
          title="Backup / Export / Import"
        />
        <div className="rounded-lg bg-rose-50 p-4 text-sm font-bold leading-6 text-rose-900 ring-1 ring-rose-100">
          Do not export or import real personal data unless the system is properly secured, encrypted and authorised.
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          {summaryRows.map(([label, value]) => <RotaStat key={label} label={label} tone="teal" value={value} />)}
        </div>
      </Card>

      <Card className="border-l-4 border-l-blue-500">
        <SectionTitle
          action={<PillBadge tone={databaseStatus.demoMode ? "amber" : databaseStatus.supabaseConfigured ? "green" : "red"}>{databaseStatus.demoMode ? "Demo local export" : "Database export mode"}</PillBadge>}
          subtitle="Database exports must be role-controlled, provider-scoped and audit logged before production use."
          title="Database export readiness"
        />
        <div className="rounded-lg bg-blue-50 p-4 text-sm font-bold leading-6 text-blue-900 ring-1 ring-blue-100">
          Database export must be role-controlled and audit logged. {tenantQueryWarning}
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          {databaseExportRows.map(([label, value]) => (
            <div className="rounded-lg bg-slate-50 p-4 ring-1 ring-slate-100" key={label}>
              <div className="text-xs font-black uppercase text-slate-500">{label}</div>
              <div className="mt-2 text-sm font-bold text-slate-700">{value}</div>
            </div>
          ))}
        </div>
      </Card>

      <Card>
        <SectionTitle subtitle="Exports download JSON files that can be imported into another CareVerity prototype browser." title="Backup actions" />
        <input
          accept=".json,application/json"
          className="hidden"
          onChange={(event) => handleImportFile(event.target.files?.[0])}
          ref={importInputRef}
          type="file"
        />
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          <button className="rounded-lg bg-[#0B1F3A] p-4 text-left text-sm font-black text-white transition hover:bg-slate-800" onClick={() => exportJson("full", "Export Full CareVerity Demo Data")} type="button">
            Export Full CareVerity Demo Data
            <span className="mt-2 block text-xs font-semibold text-slate-200">Staff, clients, rota, calls, journal, training, certificates, settings, roles and audit logs.</span>
          </button>
          <button className="rounded-lg bg-teal-600 p-4 text-left text-sm font-black text-white transition hover:bg-teal-700" onClick={() => importInputRef.current?.click()} type="button">
            Import CareVerity Demo Data
            <span className="mt-2 block text-xs font-semibold text-teal-50">Upload a CareVerity JSON backup and restore it to local storage on this computer.</span>
          </button>
          <button className="rounded-lg bg-slate-100 p-4 text-left text-sm font-black text-slate-800 ring-1 ring-slate-200 transition hover:bg-white" onClick={() => exportJson("settings", "Export Settings Only")} type="button">
            Export Settings Only
            <span className="mt-2 block text-xs font-semibold text-slate-500">Roles, permissions, call types, message types, governance settings and system evidence settings.</span>
          </button>
          <button className="rounded-lg bg-blue-600 p-4 text-left text-sm font-black text-white transition hover:bg-blue-700" onClick={() => exportJson("staff-client", "Export Staff and Client Demo Data Only")} type="button">
            Export Staff and Client Demo Data Only
            <span className="mt-2 block text-xs font-semibold text-blue-50">Staff files, service users, avatars, call packages, saved allocations and availability-related data.</span>
          </button>
          <button className="rounded-lg bg-rose-600 p-4 text-left text-sm font-black text-white transition hover:bg-rose-700" onClick={resetDemoData} type="button">
            Reset Demo Data
            <span className="mt-2 block text-xs font-semibold text-rose-50">Clears local prototype records created by the demo workflows.</span>
          </button>
          <button className="rounded-lg bg-emerald-600 p-4 text-left text-sm font-black text-white transition hover:bg-emerald-700" onClick={() => exportJson("migration", "Create Migration Backup")} type="button">
            Create Migration Backup
            <span className="mt-2 block text-xs font-semibold text-emerald-50">Full migration file for moving the prototype and demo state to another computer.</span>
          </button>
          <button className="rounded-lg bg-purple-600 p-4 text-left text-sm font-black text-white transition hover:bg-purple-700" onClick={loadDemoSeedData} type="button">
            Load Demo Seed Data
            <span className="mt-2 block text-xs font-semibold text-purple-50">Reloads the saved seed file from this workspace into browser local storage.</span>
          </button>
        </div>
        <div className="mt-4 rounded-md bg-slate-50 p-3 text-sm font-bold text-slate-700 ring-1 ring-slate-100">{statusMessage}</div>
      </Card>

      <div className="grid gap-6 xl:grid-cols-[1fr_0.85fr]">
        <Card>
          <SectionTitle subtitle="The JSON file includes these sections so another computer can restore the prototype state." title="Export contents" />
          <div className="grid gap-2 md:grid-cols-2">
            {[
              "staff files",
              "service user files",
              "profile picture/avatar metadata",
              "rota allocations",
              "call packages",
              "one-off calls",
              "emergency calls",
              "client journal entries",
              "training academy data",
              "certificates",
              "roles and permissions",
              "availability/access schedules",
              "audit logs",
              "settings"
            ].map((item) => (
              <div className="rounded-md bg-slate-50 p-3 text-sm font-bold text-slate-700 ring-1 ring-slate-100" key={item}>
                <Icon className="mr-2 inline h-4 w-4 text-teal-600" name="check" />
                {item}
              </div>
            ))}
          </div>
        </Card>
        <Card>
          <SectionTitle subtitle="Recent export, import and reset actions are kept as prototype audit evidence." title="Backup audit log" />
          {auditRows.length ? (
            <div className="space-y-2">
              {auditRows.map((row) => (
                <div className="rounded-md bg-slate-50 p-3 text-sm ring-1 ring-slate-100" key={`${row.action}-${row.dateTime}`}>
                  <div className="font-black text-slate-900">{row.action}</div>
                  <div className="mt-1 text-xs font-semibold text-slate-500">{row.user} | {row.dateTime}</div>
                  <div className="mt-2 text-slate-600">{row.detail}</div>
                </div>
              ))}
            </div>
          ) : (
            <div className="rounded-md bg-slate-50 p-4 text-sm font-semibold text-slate-600 ring-1 ring-slate-100">No backup/import audit entries yet.</div>
          )}
        </Card>
      </div>
    </div>
  );
}

function ProductionReadinessPage() {
  const databaseStatus = getCareVerityDatabaseStatus();
  const controlCounts = careverityLaunchSecurityControls.reduce(
    (totals, control) => ({
      ...totals,
      [control.status]: (totals[control.status] ?? 0) + 1
    }),
    {} as Record<string, number>
  );
  const hardStops = [...careverityLaunchHardStops, ...databaseStatus.hardStops];
  const statusTone = (status: string): Tone => {
    if (status === "Pass") return "green";
    if (status === "Prepared") return "blue";
    if (status === "Blocked") return "red";
    return "amber";
  };
  const checklistPanels = [
    ["OWASP Top 10 test plan", careverityOwaspChecklist],
    ["Penetration test checklist", careverityPenetrationChecklist],
    ["Cyber Essentials readiness", careverityCyberEssentialsChecklist],
    ["DPIA support checklist", careverityDpiaChecklist],
    ["Backup and restore checklist", careverityBackupRestoreChecklist],
    ["Breach-reporting workflow", careverityBreachWorkflowSteps],
    ["Privacy notice / DPA templates", careverityPrivacyTemplateChecklist]
  ] satisfies Array<[string, readonly string[]]>;

  return (
    <div className="space-y-6">
      <Card className="border-l-4 border-l-rose-500">
        <SectionTitle
          action={<PillBadge tone="red">Launch blocked</PillBadge>}
          subtitle="Security, privacy, tenant isolation, UAT and business compliance gates for UK launch. Demo records only until every blocked gate is resolved."
          title="UK Launch Readiness"
        />
        <div className="rounded-lg bg-rose-50 p-4 text-sm font-bold leading-6 text-rose-900 ring-1 ring-rose-100">
          Reference: {careverityLaunchReference}. {careverityLaunchDecision}
        </div>
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          <RotaStat label="Controls passed" tone="green" value={String(controlCounts.Pass ?? 0)} />
          <RotaStat label="Controls prepared" tone="blue" value={String(controlCounts.Prepared ?? 0)} />
          <RotaStat label="Blocked gates" tone="red" value={String((controlCounts.Blocked ?? 0) + hardStops.length)} />
          <RotaStat label="Runtime mode" tone={databaseStatus.demoMode ? "amber" : "blue"} value={databaseStatus.demoMode ? "Demo" : "Database"} />
          <RotaStat label="Supabase connected" tone={databaseStatus.supabaseConfigured ? "green" : "amber"} value={databaseStatus.supabaseConfigured ? "Yes" : "No"} />
        </div>
        <div className="mt-4 rounded-lg bg-amber-50 p-4 text-sm font-bold leading-6 text-amber-900 ring-1 ring-amber-100">
          {tenantQueryWarning}
        </div>
      </Card>

      <Card>
        <SectionTitle title="Hard stops before launch" subtitle="CareVerity must not be marked ready while any hard stop remains open." />
        <div className="space-y-2">
          {hardStops.map((stop) => (
            <div className="flex items-start gap-3 rounded-lg bg-rose-50 p-3 text-sm font-bold text-rose-900 ring-1 ring-rose-100" key={stop}>
              <Icon className="mt-0.5 h-4 w-4 shrink-0 text-rose-600" name="alert" />
              <span>{stop}</span>
            </div>
          ))}
        </div>
      </Card>

      <Card>
        <SectionTitle title="Database and production status" subtitle={databaseStatus.message} />
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          {[
            ["Environment", ".env.example contains Supabase and multi-tenant placeholders"],
            ["Schema", "supabase/schema.sql contains CareVerity provider, care, rota, MAR, finance, import and audit tables"],
            ["Service layer", "/lib/careverity-db.ts switches between demo/localStorage and Supabase mode and blocks tenant-scoped database calls without companyId/providerId"],
            ["Storage", "provider-documents/company_id folders planned for restricted document areas"],
            ["Audit", "audit_logs schema includes append-only/hash-chain fields, action, module, old/new value, reason, IP/device and tenant identifiers"],
            ["Middleware", "Protected CareVerity routes require auth when demo mode is disabled and security headers are emitted"],
            ["Demo safety", "Current frontend and local demo seed data remain available for UAT only"]
          ].map(([label, value]) => (
            <div className="rounded-lg bg-slate-50 p-4 ring-1 ring-slate-100" key={label}>
              <div className="text-xs font-black uppercase text-slate-500">{label}</div>
              <div className="mt-2 text-sm font-bold leading-6 text-slate-700">{value}</div>
            </div>
          ))}
        </div>
      </Card>

      <Card>
        <SectionTitle title="Security and privacy control register" subtitle="Each item maps to a launch gate. Prepared means the structure exists; it does not mean production evidence has passed." />
        <div className="grid gap-3 md:grid-cols-2">
          {careverityLaunchSecurityControls.map((control) => {
            const tone = statusTone(control.status);
            return (
              <div className="rounded-lg bg-slate-50 p-4 ring-1 ring-slate-100" key={control.area}>
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <div className="font-black text-slate-900">{control.area}</div>
                    <div className="mt-1 text-sm font-semibold leading-6 text-slate-500">{control.evidence}</div>
                  </div>
                  <PillBadge tone={tone}>{control.status}</PillBadge>
                </div>
                <div className="mt-3 rounded-md bg-white p-3 text-xs font-bold leading-5 text-slate-600 ring-1 ring-slate-100">{control.launchGate}</div>
              </div>
            );
          })}
        </div>
      </Card>

      <div className="grid gap-6 xl:grid-cols-2">
        {checklistPanels.map(([title, rows]) => (
          <Card key={title}>
            <SectionTitle title={title} />
            <div className="space-y-2">
              {rows.map((row) => (
                <div className="rounded-md bg-slate-50 p-3 text-sm font-semibold leading-6 text-slate-700 ring-1 ring-slate-100" key={row}>
                  <Icon className="mr-2 inline h-4 w-4 text-teal-600" name="check" />
                  {row}
                </div>
              ))}
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

const demoExportPreviewTypes: DemoExportPreviewType[] = [
  "Service User File Export",
  "Staff File Export",
  "Visit Evidence Export",
  "Rota Allocation Export",
  "ECM Audit Export",
  "Full Demo Pack Export"
];

function flattenDemoExportRows(value: unknown, prefix = ""): string[][] {
  if (value === null || value === undefined) return [[prefix, "Not included in this preview"]];
  if (Array.isArray(value)) {
    if (value.length === 0) return [[prefix, "No rows"]];
    return value.flatMap((item, index) => flattenDemoExportRows(item, `${prefix}${prefix ? " > " : ""}${index + 1}`));
  }
  if (typeof value === "object") {
    return Object.entries(value as Record<string, unknown>).flatMap(([key, item]) => flattenDemoExportRows(item, `${prefix}${prefix ? " > " : ""}${key}`));
  }
  return [[prefix, String(value)]];
}

